export const ARTICLES: Article[] = [
  { titre: "ABBA", texte: "ABBA, souvent stylisé AꓭBA, est un groupe suédois de pop, originaire de Stockholm. Formé le 1er novembre 1971, le groupe est originellement composé d'Agnetha Fältskog, Benny Andersson, Björn Ulvaeus et Anni-Frid « Frida » Lyngstad." },
  { titre: "Abeille", texte: "Les abeilles (Anthophila) forment un clade d'insectes hyménoptères de la super-famille des Apoïdes. Au moins 20 000 espèces d'abeilles sont répertoriées sur la planète dont environ 2 000 en Europe et près de 1 000 en France métropolitaine." },
  { titre: "Abidjan", texte: "Abidjan est la ville la plus peuplée de la Côte d'Ivoire. Elle fut la capitale administrative et politique du pays jusqu'en 1983, date du transfert de jure de la capitale à Yamoussoukro." },
  { titre: "Aborigènes d'Australie", texte: "Les Aborigènes d’Australie (en anglais : Aboriginal Australians) sont les premiers humains connus à s'être établis sur le territoire de l’Australie et sont reconnus comme l’un des deux peuples autochtones d’Australie avec les Insulaires du détroit de Torrès." },
  { titre: "Abraham", texte: "Abraham est un personnage des écritures juives, considéré comme le principal patriarche des religions juive, chrétienne et musulmane par la majorité des courants qui les constituent. Il est une des figures centrales du Livre de la Genèse." },
  { titre: "Accident vasculaire cérébral", texte: "Un accident vasculaire cérébral (AVC), anciennement accident cérébrovasculaire (ACV) et populairement appelé attaque cérébrale, infarctus cérébral ou congestion cérébrale (AVC et ACV étant tous deux des terminologies acceptées), est un déficit neurologique soudain d'origine vasculaire causé par un infarctus ou une" },
  { titre: "Achéménides", texte: "L'Empire achéménide est le premier empire perse de l'Histoire. Il fut gouverné par Cyrus II et ses successeurs sur une grande partie du Moyen-Orient durant le Ier millénaire av. J.-C." },
  { titre: "Achille", texte: "Achille est un héros légendaire de la guerre de Troie, fils de Pélée, roi de Phthie en Thessalie, et de Thétis, une Néréide (nymphe marine). Il est fréquemment appelé « Péléide » ou « Éacide », épithètes qui rappellent son ascendance." },
  { titre: "Acide acétylsalicylique", texte: "L’acide acétylsalicylique (AAS), plus connu sous le nom commercial d’aspirine, est un antiagrégant plaquettaire. C’est la substance active de nombreux médicaments aux propriétés antalgiques, antipyrétiques et anti-inflammatoires." },
  { titre: "Acide aminé", texte: "Un acide aminé est un composé organique qui possède un groupe fonctionnel amine et un groupe fonctionnel acide carboxylique. Bien que plus de 500 acides aminés existent dans la nature, les plus importants sont de loin les 22 acides α-aminés incorporés dans les protéines." },
  { titre: "Acide désoxyribonucléique", texte: "L'acide désoxyribonucléique, ou ADN, est une macromolécule biologique présente dans presque toutes les cellules ainsi que chez de nombreux virus. L'ADN contient toute l'information génétique, appelée génome, permettant le développement, le fonctionnement et la reproduction des êtres vivants." },
  { titre: "Acier", texte: "Un acier est un alliage métallique constitué principalement de fer et de carbone. Il se distingue des fontes et des ferroalliages par sa teneur en carbone comprise entre 0,02 % et 2 % en masse." },
  { titre: "Acier inoxydable", texte: "L'acier inoxydable, couramment appelé acier inox ou inox, est un acier (alliage à base de fer et de carbone), comportant moins de 1,2 % de carbone et plus de 10,5 % de chrome, dont la propriété remarquable est d'être peu sensible à la corrosion et de ne pas se dégrader en rouille." },
  { titre: "Acné", texte: "L'acné est une maladie dermatologique courante et chronique du système pilosébacé (qui comprend le follicule pileux, la tige pilaire et la glande sébacée sécrétant le sébum, à la racine du poil). C'est une maladie inflammatoire de la peau dans laquelle les glandes sébacées jouent un rôle clé." },
  { titre: "Acropole d'Athènes", texte: "L'acropole d'Athènes est un plateau rocheux calcaire s'élevant au centre de la ville d'Athènes à laquelle elle a longtemps servi de citadelle, de l'Athènes antique à l'occupation ottomane, ainsi que de sanctuaire religieux durant l'Antiquité." },
  { titre: "Acteur", texte: "Un acteur, ou comédien, est un artiste qui prête son physique ou sa voix à un personnage fictif dans une œuvre artistique animée, au cinéma, au théâtre, à la télévision, à la radio ou encore dans un jeu vidéo, conformément à certaines conventions artistiques." },
  { titre: "Ada Lovelace", texte: "Ada Lovelace, de son nom complet Augusta Ada King, comtesse de Lovelace, née Ada Byron le 10 décembre 1815 à Londres et morte le 27 novembre 1852 à Marylebone dans la même ville, est une pionnière de la science informatique." },
  { titre: "Adam", texte: "Adam, en ancien français Adan, est un personnage de la Torah, de la Bible et du Coran. Il est mentionné dans le livre de la Genèse qui date du premier millénaire avant Jésus-Christ. Dans ce texte, qui fonde les croyances juives, chrétiennes et musulmanes, Adam est le premier homme (au sens d'être humain) créé par Dieu." },
  { titre: "Adam Smith", texte: "Adam Smith, né le 5 juin 1723 à Kirkcaldy et mort le 17 juillet 1790 à Édimbourg, est un philosophe et économiste écossais ainsi qu'une des principales figures des Lumières écossaises." },
  { titre: "Adolescence", texte: "L'adolescence (du latin ădŏlēscēns, -centĭa, « croissant, grandissant, se développant ») est une phase du développement humain physique et mental qui se produit pendant la période de la vie humaine s'étendant de la puberté (ou de la fin de l'enfance au sens strict) jusqu'à l'âge adulte." },
  { titre: "Adolf Hitler", texte: "Adolf Hitler, né le 20 avril 1889 à Braunau am Inn (Autriche-Hongrie) et mort suicidé le 30 avril 1945 à Berlin, est un idéologue d'extrême droite et un homme d'État allemand d'origine autrichienne." },
  { titre: "Adolphe Thiers", texte: "Adolphe Thiers, né le 15 avril 1797 (26 germinal an V) à Marseille (Bouches-du-Rhône) et mort le 3 septembre 1877 à Saint-Germain-en-Laye (Seine-et-Oise), est un avocat, journaliste, historien et homme d'État français." },
  { titre: "Affaire Dreyfus", texte: "L'affaire Dreyfus est une affaire d'État devenue un conflit politique majeur de la Troisième République, survenu en France à la fin du XIXe siècle autour de l'accusation de trahison faite au capitaine Alfred Dreyfus, juif d'origine alsacienne, qui est finalement innocenté." },
  { titre: "Afghanistan", texte: "L'Afghanistan, en forme longue de facto l'émirat islamique d'Afghanistan mais encore reconnu internationalement en tant que République Islamique d'Afghanistan, est un pays d'Asie du Sud ou d'Asie centrale sans accès à la mer entouré par l'Ouzbékistan au nord, la Chine et le Tadjikistan au nord-est, le Pakistan à" },
  { titre: "Afrique", texte: "L'Afrique est un continent terrestre bordé à l'est par l'océan Indien et à l'ouest par l'océan Atlantique. Centré sur l'équateur, et s'étirant au-delà des lattitudes tropicales des deux hémisphères, ses extrémités atteignent la mer Méditérannée au nord, et l'océan Austral au sud." },
  { titre: "Afrique de l'Ouest", texte: "L'Afrique de l’Ouest est une région terrestre couvrant toute la partie occidentale de l’Afrique subsaharienne. Elle comprend approximativement les pays côtiers au nord du golfe de Guinée jusqu’au fleuve Sénégal, les pays couverts par le bassin du fleuve Niger ainsi que les pays de l’arrière-pays sahélien." },
  { titre: "Afrique du Nord", texte: "L'Afrique du Nord est un sous-continent culturel de la partie septentrionale de l’Afrique. Elle est parfois définie comme s'étendant des rives de l'Atlantique, du Maroc à l'ouest, au canal de Suez et à la mer Rouge, en Égypte à l'est." },
  { titre: "Afrique subsaharienne", texte: "L'Afrique subsaharienne ou simplement la Subsaharie est l'étendue du continent africain au sud du Sahara, séparée écologiquement des pays du Nord par le climat rude du plus vaste désert chaud du monde." },
  { titre: "Agatha Christie", texte: "Agatha Christie est une femme de lettres britannique, auteure de nombreux romans policiers, née le 15 septembre 1890 à Torquay et morte le 12 janvier 1976 à Wallingford au Royaume-Uni." },
  { titre: "Agence spatiale européenne", texte: "L'Agence spatiale européenne (ASE ; en anglais : European Space Agency ; en allemand : Europäische Weltraumorganisation ), le plus souvent désignée par son sigle anglais ESA, est une agence spatiale intergouvernementale fondée en 1975 qui coordonne les projets spatiaux menés en commun par 23 pays européens." },
  { titre: "Agnosticisme", texte: "L'agnosticisme est une attitude philosophique consistant à aborder de façon sceptique les questions de religion et de métaphysique, et à affirmer que l'esprit humain ne peut pas accéder à l'absolu." },
  { titre: "Agression sexuelle", texte: "Une agression sexuelle est tout acte de nature sexuelle non consenti, qui implique de toucher les parties intimes du corps humain sans l'acquiescement explicite de la victime." },
  { titre: "Agriculture", texte: "L’agriculture (du latin agricultura, composé à partir de ager, « champ », et de cultura, « culture ») est un processus par lequel les êtres humains aménagent leurs écosystèmes et contrôlent le cycle biologique d'espèces domestiquées, dans le but de produire des aliments et d'autres ressources utiles à leurs sociétés." },
  { titre: "Aigle", texte: "Aigle est le nom vernaculaire de certains grands rapaces planeurs diurnes de la famille des Accipitridés. Dans la nomenclature aviaire en langue française, le terme désigne trente-huit espèces d'oiseaux qui constituent douze genres (dont certaines espèces aujourd'hui disparues)." },
  { titre: "Aigle royal", texte: "L'Aigle royal (Aquila chrysaetos) est une espèce d'oiseaux de la famille des Accipitridae. C'est un rapace brun foncé, avec un plumage plus brun-doré sur la tête et le cou." },
  { titre: "Aiglefin", texte: "L’aiglefin, églefin ou èglefin (Melanogrammus aeglefinus) ou ânon ou haddock (s'il est fumé), est une espèce de poissons de la famille des Gadidae, unique représentant du genre Melanogrammus (monotypique)." },
  { titre: "Ail cultivé", texte: "L'ail (pluriel : ails ou aulx), ail commun ou ail cultivé (Allium sativum) est une espèce de plantes potagères vivaces monocotylédones dont les bulbes, à l'odeur et au goût forts, sont souvent employés comme condiment en cuisine." },
  { titre: "Akhenaton", texte: "Amenhotep IV (né probablement entre 1371/1365 av. J.-C. et mort vers 1338/1337 av. J.-C., Aménophis IV en grec ancien, d'après le nom donné par Manéthon à son prédécesseur ; Manéthon ne le nomme pas explicitement), ou Akhenaton (ou plus rarement Khounaton), est le dixième pharaon de la XVIIIe dynastie." },
  { titre: "Akira Kurosawa", texte: "Akira Kurosawa est un réalisateur, producteur, scénariste et monteur japonais, né le 23 mars 1910 à Tokyo, où il est mort le 6 septembre 1998. Il est considéré comme l'un des cinéastes les plus célèbres et influents de l'histoire du cinéma." },
  { titre: "Alaska", texte: "L'Alaska est le 49e État des États-Unis, dont la capitale est Juneau et la plus grande ville Anchorage, où habite environ 40 % de la population de l'État." },
  { titre: "Albanie", texte: "L'Albanie, en forme longue la république d'Albanie, est une république située en Europe du Sud, dans la partie occidentale de la péninsule des Balkans. Elle possède une façade maritime à l'ouest, donnant sur la mer Adriatique et la mer Ionienne ; l'Italie est distante de quatre-vingts kilomètres via le canal d'Otrante." },
  { titre: "Albédo", texte: "L'albédo, ou albedo (sans accent), est le pouvoir réfléchissant d'une surface, c'est-à-dire le rapport du flux d'énergie lumineuse réfléchie au flux d'énergie lumineuse incidente." },
  { titre: "Alberta", texte: "L'Alberta est une province du Canada. Située dans l'Ouest du pays, elle constitue une des trois provinces des Prairies. Elle est bordée par la Colombie-Britannique à l'ouest, la Saskatchewan à l'est, les Territoires du Nord-Ouest au nord et partage une frontière avec les États-Unis au sud." },
  { titre: "Alchimie", texte: "L’alchimie est une protoscience qui peut se définir comme « un ensemble de pratiques et de spéculations en rapport avec la transmutation des métaux »." },
  { titre: "Alexandre Dumas", texte: "Alexandre Dumas (dit aussi Alexandre Dumas père) est un écrivain français né le 24 juillet 1802 à Villers-Cotterêts (Aisne) et mort le 5 décembre 1870 au hameau de Puys, ancienne commune de Neuville-lès-Dieppe, aujourd'hui intégrée à Dieppe (Seine-Maritime)." },
  { titre: "Alexandre Grothendieck", texte: "Alexandre Grothendieck, né Alexander Grothendieck, est un mathématicien français, né le 28 mars 1928 à Berlin et mort le 13 novembre 2014 à l'hôpital de Saint-Lizier, à côté de Saint-Girons (Ariège). Resté longtemps apatride, tout en vivant principalement en France, il acquiert la nationalité française en 1971." },
  { titre: "Alexandre Ier", texte: "Alexandre Ier ou Alexandre Pavlovitch Romanov, né le 12 décembre 1777 (23 décembre dans le calendrier grégorien) à Saint-Pétersbourg et mort le 19 novembre 1825 (1er décembre dans le calendrier grégorien) à Taganrog, fils de Paul Ier et de Sophie-Dorothée de Wurtemberg, est empereur de Russie du 23 mars 1801 à sa mort" },
  { titre: "Alexandre le Grand", texte: "Alexandre le Grand ou Alexandre III, né le 21 juillet 356 av. J.-C. à Pella et mort le 11 juin 323 av. J.-C. à Babylone, est un roi de Macédoine et l'un des personnages les plus célèbres de l'Antiquité." },
  { titre: "Alexandre Pouchkine", texte: "Alexandre Sergueïevitch Pouchkine, né le 26 mai 1799 (6 juin dans le calendrier grégorien) à Moscou et mort le 29 janvier 1837 (10 février dans le calendrier grégorien) à Saint-Pétersbourg, est un poète, dramaturge et romancier russe, considéré comme un des plus importants écrivains de son pays." },
  { titre: "Alexandre Soljenitsyne", texte: "Alexandre Soljenitsyne (ou Soljénitsyne), de son nom complet Alexandre Issaïevitch Soljenitsyne, né le 28 novembre 1918 (11 décembre dans le calendrier grégorien) à Kislovodsk et mort le 3 août 2008 à Moscou, est un écrivain russe, auteur d'ouvrages de renommée internationale tels que Une journée d'Ivan Denissovitch," },
  { titre: "Alexandre VI", texte: "Rodrigo de Borja, né Roderic Llançol i de Borja le 1er janvier 1431 à Xàtiva (royaume de Valence, couronne d'Aragon) et mort à Rome le 18 août 1503, devenu Rodrigo Borgia après son arrivée en Italie, est le 214e pape de l’Église catholique sous le nom d’Alexandre VI de 1492 à 1503." },
  { titre: "Alexandrie", texte: "Alexandrie est une ville d'Égypte. En 2023, elle comptait plus de 5 362 517 habitants. Elle a été fondée par Alexandre le Grand en 331 avant notre ère." },
  { titre: "Alexis de Tocqueville", texte: "Alexis-Charles-Henri Clérel, comte de Tocqueville, couramment Alexis de Tocqueville, né le 29 juillet 1805 à Paris et mort le 16 avril 1859 à Cannes, est un magistrat, écrivain, historien, académicien, philosophe, voyageur, politologue, précurseur de la sociologie et homme politique français." },
  { titre: "Alfred Hitchcock", texte: "Alfred Hitchcock est un réalisateur, scénariste et producteur de cinéma britannique, né le 13 août 1899 à Leytonstone (Londres) et mort le 29 avril 1980 à Bel Air (Los Angeles)." },
  { titre: "Alfred Nobel", texte: "Alfred Bernhard Nobel /'alfrəd 'bɛɳhɑ :ɖ noˈbɛ :l /, né le 21 octobre 1833 à Stockholm en Suède et mort le 10 décembre 1896 à Sanremo en Italie, est un chimiste, industriel et fabricant d'armes suédois." },
  { titre: "Alfredo Di Stéfano", texte: "Alfredo Di Stéfano Laulhé est un footballeur puis entraîneur, né le 4 juillet 1926 à Buenos Aires et mort le 7 juillet 2014 à Madrid. De nationalité argentine puis naturalisé espagnol en 1956, il évolue au poste d'attaquant, du milieu des années 1940 au milieu des années 1960." },
  { titre: "Alfredo Stroessner", texte: "Alfredo Stroessner Matiauda est un militaire et un homme d'État paraguayen. Commandant en chef des forces armées et membre du Parti colorado, il dirige le Paraguay pendant près de trente-cinq ans, de 1954 à 1989, avant d'être renversé par un coup d'État." },
  { titre: "Alger", texte: "Alger, surnommée El Bahdja (« la joyeuse »), El Mahrussa (« la bien-gardée ») ou El Beida (« la blanche ») ou même Alger la blanche, est la capitale de l'Algérie et en est la ville la plus peuplée." },
  { titre: "Algérie", texte: "L'Algérie (/al.ʒe.ʁi/ ; arabe : الجزائر (al-Jazā'ir) ; en arabe algérien : دزاير (Dzayer) ou الجزاير (El Djazaïr) ; en tamazight ⴷⵣⴰⵢⵔ (Dzayer)), en forme longue la République algérienne démocratique populaire ou République algérienne démocratique et populaire, est un État souverain d’Afrique du Nord faisant partie du" },
  { titre: "Ali ibn Abi Talib", texte: "Ali bin Abi Talib, né vers 600 à La Mecque et mort assassiné en 661 à Koufa, est le cousin germain du prophète de l'islam Mahomet et fils d'Abû Tâlib, oncle de Mahomet qui l'a élevé et protégé comme son propre fils après la mort de son père Abdullah en 570." },
  { titre: "Aliénor d'Aquitaine", texte: "Aliénor d'Aquitaine, aussi connue sous le nom d'Éléonore d'Aquitaine ou d'Éléonore de Guyenne, née vers 1124 et morte à Poitiers le 31 mars ou le 1er avril 1204, a été tour à tour reine de France, puis reine d'Angleterre." },
  { titre: "Allah", texte: "Allah est le mot arabe qui désigne « Dieu », et signifie littéralement, « le dieu » avec un article défini, faisant référence à un dieu considéré par principe comme unique, le « dieu unique » des religions monothéistes." },
  { titre: "Allemagne", texte: "L'Allemagne (en allemand : Deutschland ), en forme longue la République fédérale d'Allemagne (Bundesrepublik Deutschland), est un État d'Europe centrale, et selon certaines définitions d'Europe de l'Ouest, entouré par la mer du Nord, le Danemark et la mer Baltique au nord, par la Pologne à l'est-nord-est, la Tchéquie" },
  { titre: "Allemand", texte: "L'allemand est l'une des langues indo-européennes appartenant à la branche des langues germaniques, parlée notamment en Allemagne, en Autriche, en Suisse, au Liechtenstein, au Luxembourg, en Belgique et dans certaines régions limitrophes des pays voisins." },
  { titre: "Almoravides", texte: "Les Almoravides sont une dynastie berbère sanhajienne, qui constitua du XIe au XIIe siècle une confédération tribale, un mouvement politico-religieux, puis un empire englobant le Maroc, le Sahara occidental, la Mauritanie, une partie du Mali moderne et l'ouest de l'Algérie, ainsi que le sud de la péninsule Ibérique." },
  { titre: "Alpes", texte: "Les Alpes sont une chaîne de montagnes qui s'étend en Europe, recouvrant la frontière nord de l'Italie, le Sud-Est de la France, Monaco, la Suisse, le Liechtenstein, l'Autriche, le Sud de l'Allemagne, la Slovénie et la Hongrie." },
  { titre: "Alphabet", texte: "Un alphabet (de alpha et bêta, les deux premières lettres de l’alphabet grec) est un système d'écriture constitué d'un ensemble de symboles dont chacun représente, par exemple, un des phonèmes d’une langue." },
  { titre: "Alphabet arabe", texte: "L'alphabet arabe est un abjad, c'est-à-dire un système d'écriture ne notant que les consonnes (à peu de chose près). Il comporte initialement vingt-huit lettres et s'écrit horizontalement de droite à gauche." },
  { titre: "Alphabet cyrillique", texte: "L'alphabet cyrillique est un alphabet permettant l'écriture de nombreuses langues d'Europe de l'Est et d'Asie centrale, principalement dans l'ex-URSS." },
  { titre: "Alphabet grec", texte: "L'alphabet grec est un alphabet bicaméral de vingt-quatre lettres, principalement utilisé pour écrire la langue grecque depuis la fin du IXe ou le début du VIIIe siècle av. J.-C. C'est le premier et le plus ancien alphabet, dans l'acception la plus réduite de ce mot, car il note chaque voyelle et consonne avec un" },
  { titre: "Alphabet latin", texte: "L'alphabet latin est un alphabet bicaméral comportant vingt-six lettres de base, principalement utilisé pour écrire les langues d’Europe de l'Ouest, d'Europe du Nord et d'Europe centrale, ainsi que les langues de nombreux pays qui ont été exposés à une forte influence européenne, notamment à travers la colonisation" },
  { titre: "Alstroemeria", texte: "Alstroemeria est un genre de plantes, les alstrœmères ou alstrœméries, à fleurs vivaces, à racines tubéreuses, de la famille des Liliaceae, ou des Alstroemeriaceae selon la classification phylogénétique." },
  { titre: "Amelia Earhart", texte: "Amelia Earhart, également connue sous le nom de Lady Lindy, est une aviatrice américaine, née le 24 juillet 1897 à Atchison (Kansas), disparue le 2 juillet 1937 dans l'océan Pacifique et déclarée officiellement morte le 5 janvier 1939." },
  { titre: "Amerigo Vespucci", texte: "Amerigo Vespucci, né le 9 mars 1454 dans la république de Florence, et mort le 22 février 1512 à Séville (royaume de Castille), est un commerçant, navigateur et explorateur florentin dont le prénom servit en 1507 pour baptiser le Nouveau Monde (America)." },
  { titre: "Amérique latine", texte: "L’Amérique latine (en espagnol et en portugais : América Latina) est une aire culturelle à la définition variable, regroupant une partie des territoires d'Amérique qui ont été colonisés par les Européens parlant des langues romanes (c'est-à-dire dérivées du latin), soit entre vingt et plus de trente pays actuels selon" },
  { titre: "Anatolie", texte: "L'Anatolie ou Asie Mineure est une vaste péninsule et bloc de territoires situés à l'extrémité occidentale de l'Asie (et donc de l'Asie occidentale)." },
  { titre: "Ancien Testament", texte: "L'Ancien Testament, aussi appelé Premier Testament, est, pour les chrétiens, la partie de leur Bible relative à la période qui précède Jésus-Christ. Il est formé des livres de la Bible hébraïque (le Tanakh) et d'autres livres de la fin de la période qui ne sont pas inclus dans le canon hébraïque actuel." },
  { titre: "Andorre", texte: "L'Andorre, en forme longue la principauté d'Andorre (en catalan : Andorra et Principat d’Andorra), est un État d'Europe du Sud et, selon certaines définitions, d'Europe de l'Ouest, en fait d'Europe du Sud-Ouest." },
  { titre: "André Gide", texte: "André Gide, né le 22 novembre 1869 à Paris dans le 6e arrondissement, mort le 19 février 1951 à Paris dans le 7e arrondissement, est un écrivain français. Il obtient le prix Nobel de littérature en 1947." },
  { titre: "Andreï Tarkovski", texte: "Andreï Tarkovski est un réalisateur, scénariste et écrivain soviétique, né le 4 avril 1932 à Zavrajié dans le raïon de Iouriévets (ru) en URSS (actuellement raïon de Kady (ru), oblast d'Ivanovo en Russie) et mort le 29 décembre 1986 à Neuilly-sur-Seine en France d'un cancer du poumon." },
  { titre: "Andrew Jackson", texte: "Andrew Jackson, né le 15 mars 1767 à Waxhaws (en) (Les Carolines) et mort le 8 juin 1845 à Nashville (Tennessee), est un militaire, planteur esclavagiste et homme d'État américain. Il est le 7e président des États-Unis, en fonction du 4 mars 1829 au 4 mars 1837, et le premier issu du Parti démocrate." },
  { titre: "Android", texte: "Android, prononcé en français, est un système d'exploitation mobile open source fondé sur le noyau Linux et développé par un consortium d'entreprises, l'Open Handset Alliance, sponsorisé par Google." },
  { titre: "Andy Warhol", texte: "Andrew Warhola, dit Andy Warhol, né le 6 août 1928 à Pittsburgh en Pennsylvanie et mort le 22 février 1987 à New York, est un artiste américain et l'un des principaux représentants du pop art." },
  { titre: "Ange", texte: "Un ange est une créature surnaturelle dans de nombreuses traditions, notamment dans les trois religions abrahamiques et dans l'Avesta. Ce terme désigne un envoyé de Dieu, c'est-à-dire un intermédiaire entre Dieu et les hommes." },
  { titre: "Angela Merkel", texte: "Angela Merkel, née Angela Kasner le 17 juillet 1954 à Hambourg, est une femme d'État allemande. Membre de l'Union chrétienne-démocrate (CDU), elle est chancelière fédérale d'Allemagne du 22 novembre 2005 au 8 décembre 2021." },
  { titre: "Angleterre", texte: "L'Angleterre est une nation constitutive du Royaume-Uni. Elle est entourée par le pays de Galles à l'ouest et l'Écosse au nord, et par la mer d'Irlande au nord-ouest, la mer Celtique au sud-ouest, la mer du Nord à l'est, et la Manche au sud, qui la sépare de l'Europe continentale." },
  { titre: "Anglicanisme", texte: "L'anglicanisme est une confession chrétienne issue de la rupture du roi d'Angleterre Henri VIII avec l'Église catholique romaine et la papauté en 1534, formalisée par l'Acte de suprématie." },
  { titre: "Angola", texte: "L’Angola (en forme longue : la république d'Angola ; en portugais : República de Angola) est un État du sud-ouest de l'Afrique, limitrophe de la république démocratique du Congo au nord et au nord-est, de la république du Congo au nord-ouest (par l'enclave du Cabinda), de la Zambie à l'est-sud-est et de la Namibie au" },
  { titre: "Anime", texte: "Un anime, ou animé, également appelé parfois japanime ou japanimation, est une série d'animation ou un film d'animation en provenance du Japon souvent adapté d'un manga. C'est le diminutif du mot animēshon, lui-même transcription de l'anglais animation." },
  { titre: "Animisme", texte: "L’animisme (du latin animus, originairement « esprit », puis « âme ») est, dans le jargon de l'anthropologie, la croyance dans le fait qu'un esprit, une force vitale voire une forme de conscience, peut animer aussi bien les êtres vivants, les objets mais aussi des éléments naturels, comme les pierres ou le vent." },
  { titre: "Anna Karénine", texte: "Anna Karénine est un roman de Léon Tolstoï paru en 1877 en feuilleton dans Le Messager russe. Il est considéré comme un chef-d'œuvre de la littérature." },
  { titre: "Anna Wintour", texte: "Anna Wintour, née le 3 novembre 1949 à Hampstead (Grand Londres), est une journaliste britannique, rédactrice en chef de l'édition américaine du magazine Vogue entre 1988 et 2025, directrice artistique de Condé Nast depuis 2013 et responsable du contenu mondial au sein du groupe depuis 2020." },
  { titre: "Anne Frank", texte: "Anne Frank, née le 12 juin 1929 à Francfort-sur-le-Main en Allemagne sous la République de Weimar et morte en février ou mars 1945 à Bergen-Belsen en Allemagne nazie, est une jeune adolescente juive allemande connue pour avoir écrit un journal intime." },
  { titre: "Année bissextile", texte: "Une année bissextile (ou un an bissextil) est une année de 366 jours au lieu de 365 pour une année commune. Le jour ajouté est le 29 février parce que ce mois compte habituellement vingt-huit jours dans le calendrier grégorien et qu'il s'agit d'une subsistance du calendrier julien." },
  { titre: "Anouar el-Sadate", texte: "Anouar el-Sadate, transcrit également ʼAnwar as-Sādāt est un homme d'État égyptien, né le 25 décembre 1918 à Mit Abou al-Koum (en) et assassiné le 6 octobre 1981 au Caire." },
  { titre: "Antananarivo", texte: "Antananarivo ou Tananarive dans sa version francisée, ou encore la cité des mille, est la capitale économique et politique de Madagascar, de la province d'Antananarivo et de la région Analamanga. Ses habitants s'appellent les Antananariviens, ou Tananariviens." },
  { titre: "Antarctique", texte: "L'Antarctique, parfois appelé « le Continent Austral » ou « le Continent Blanc », est le continent le plus méridional de la Terre. Situé autour du pôle Sud, il est entouré des mers de Ross et de Weddell et, suivant les classifications, des océans Atlantique, Indien et Pacifique ou du seul océan Austral." },
  { titre: "Antigua-et-Barbuda", texte: "Antigua-et-Barbuda ou Antigue-et-Barbude (en anglais : Antigua and Barbuda), est un État insulaire des Antilles en Amérique du Nord ayant pour capitale Saint John's, situé à une cinquantaine de kilomètres au nord de la Guadeloupe et au nord-est de l'île du territoire britannique d'outre-mer de Montserrat." },
  { titre: "Antimoine", texte: "L'antimoine est l'élément chimique de numéro atomique 51, de symbole Sb (Stibium). L'adjectif « antimonié » qualifie un corps ou une matière qui contient de l'antimoine." },
  { titre: "Antioche", texte: "Antioche, ou Antioche-sur-l'Oronte afin de la distinguer des autres Antioche plus récentes, est une ville historique originellement fondée sur la rive gauche de l'Oronte dans la Syrie historique et qu'occupe la ville moderne d'Antakya, en Turquie." },
  { titre: "Antiquité", texte: "L'Antiquité (du latin antiquus signifiant « antérieur, ancien ») est une époque de l'histoire. Classiquement, elle couvre la période allant de l'invention de l'écriture, vers 3400-3200 av. J.-C., jusqu'à la chute de l'Empire romain d'Occident, en 476." },
  { titre: "Anubis", texte: "Anubis est un dieu funéraire de l'Égypte antique, maître des nécropoles et protecteur des embaumeurs, représenté comme un grand canidé noir couché sur le ventre, ou comme un homme à tête de canidé." },
  { titre: "Anvers", texte: "Anvers est une ville belge dans la Région flamande, chef-lieu de la province d'Anvers et de l'arrondissement administratif du même nom, située au cœur de la Dorsale européenne." },
  { titre: "Apartheid", texte: "L’apartheid était une politique ségrégative, dite de « développement séparé » (afsonderlike ontwikkeling), affectant séparément, selon des critères raciaux ou ethniques hiérarchiquement distincts, des populations dans des zones géographiques déterminées." },
  { titre: "Apollon", texte: "Apollon, ou Phébus / Phœbus, est, dans la religion grecque antique, le dieu des arts, du chant, de la musique, de la beauté masculine, de la poésie et de la lumière, et le conducteur des neuf muses. Apollon est également le dieu des purifications et de la guérison, mais peut apporter la peste par son arc." },
  { titre: "Appalaches", texte: "Les Appalaches sont une chaîne de montagnes située dans l'Est de l'Amérique du Nord et s'étendant de Terre-Neuve (Canada), au nord, jusqu'au centre de l'État de l'Alabama, au sud (États-Unis). Elle culmine au mont Mitchell (2 037 mètres) en Caroline du Nord." },
  { titre: "Appareil génital féminin", texte: "L'appareil génital féminin intervient dans les fonctions reproductives et sexuelles de la femme. Il est composé de la vulve, du vagin, de l'utérus, des trompes et des ovaires. La partie de l'appareil reproducteur située à l'intérieur du corps est dite tractus génital féminin." },
  { titre: "Appareil génital masculin", texte: "L'appareil génital masculin est l'appareil reproducteur de l'homme. Il est composé des cordons spermatiques, du scrotum, des testicules, des épididymes, des canaux déférents, des canaux éjaculateurs, des vésicules séminales, de la prostate, de l'urètre et du pénis." },
  { titre: "Arabie saoudite", texte: "L'Arabie saoudite, en forme longue le royaume d'Arabie saoudite, est une monarchie arabe et islamique depuis l'unification du royaume en 1932 par Abdelaziz ibn Saoud." },
  { titre: "Arachide", texte: "L'arachide (Arachis hypogaea), dont le fruit s'appelle selon les régions francophones du monde, cacahuète, cacahouète (du nahuatl tlālcacahuatl), arachide, pois de terre, pistache de terre ou pinotte (de l'anglais peanut), est une plante de la famille des légumineuses (Fabaceae) originaire du nord-ouest de l'Argentine" },
  { titre: "Arbre à pain", texte: "L'arbre à pain (Artocarpus altilis) est un arbre de la famille des Moracées, originaire d'Océanie, domestiqué dans cette région pour son fruit comestible et aujourd'hui largement répandu sous les tropiques." },
  { titre: "Arc-en-ciel", texte: "Un arc-en-ciel est un photométéore — un phénomène optique se produisant dans le ciel — visible dans la direction opposée au Soleil quand il brille pendant la pluie. C'est un arc de cercle coloré d'un dégradé de couleurs." },
  { titre: "Arctique", texte: "L'Arctique est la région entourant le pôle Nord de la Terre, à l’intérieur et aux abords du cercle polaire arctique. Elle s'oppose à l'Antarctique, au sud." },
  { titre: "Argentine", texte: "L'Argentine, en forme longue la République argentine, est un pays d'Amérique du Sud partageant ses frontières avec le Chili à l'ouest, la Bolivie et le Paraguay au nord, le Brésil et l'Uruguay au nord-est, et enfin l'océan Atlantique à l'est et au sud." },
  { titre: "Argile", texte: "L’argile est une matière rocheuse naturelle à base de silicates ou d'aluminosilicates hydratés de structure lamellaire, provenant en général de l'altération de silicates à charpente tridimensionnelle, tels que les feldspaths." },
  { titre: "Arme nucléaire", texte: "Une arme nucléaire est une arme non conventionnelle qui utilise l'énergie dégagée par la fission de noyaux atomiques lourds (uranium, plutonium dans le cas de la bombe A), ou par une combinaison de ce phénomène avec celui de la fusion de noyaux légers (hydrogène dans le cas des bombes H)." },
  { titre: "Arménie", texte: "L'Arménie (en arménien : Հայաստան, Hayastan), en forme longue la république d'Arménie (en arménien : Հայաստանի Հանրապետություն, Hayastani Hanrapetut’yun), est un État-nation unitaire, démocratique et multipartite." },
  { titre: "Artémis", texte: "Dans la mythologie et la religion grecque antique, Artémis est principalement la déesse de la nature sauvage, de la chasse et des accouchements. Fille de Zeus et de Léto, elle est la sœur jumelle d'Apollon (ou simplement sa sœur selon l'hymne homérique qui lui est consacré), avec lequel elle partage beaucoup de traits." },
  { titre: "Arthropodes", texte: "Les Arthropodes (Arthropoda), du grec arthron « articulation » et podos « pied », aussi appelés « articulés », sont un embranchement d'animaux protostomiens qui serait apparu il y a 543 Ma." },
  { titre: "Artichaut", texte: "L’artichaut (Cynara cardunculus var. scolymus (L.) Benth.) ou Cynara scolymus L., 1753 est une espèce de plante dicotylédone de la famille des Astéracées (ou Composées) appartenant au genre Cynara." },
  { titre: "Arts martiaux mixtes", texte: "Les arts martiaux mixtes souvent désignés par le sigle anglais MMA pour mixed martial arts, anciennement appelés combat libre ou free-fight, sont un sport de combat de percussion-préhension, combinant les techniques de percussion, telles que coups de pied, de poing, de genou et de coude, et les techniques de" },
  { titre: "Asexualité", texte: "L’asexualité est l'orientation sexuelle d'une personne qui ne ressent pas ou peu d'attirance sexuelle pour d’autres personnes, ou ne veut pas de relations sexuelles. L'asexualité a aussi parfois été définie comme un désintérêt relatif pour le sexe, ou plus rarement comme une absence d'orientation sexuelle." },
  { titre: "Assyrie", texte: "L'Assyrie (māt aššur, le « pays d'Assur », en assyrien) est une ancienne région du nord de la Mésopotamie et un empire qui s'est formé à partir de celle-ci." },
  { titre: "Astérix", texte: "Astérix, anciennement Astérix le Gaulois, est une série de bande dessinée française créée le 29 octobre 1959 par le scénariste français René Goscinny et le dessinateur français Albert Uderzo dans le no 1 du journal français Pilote." },
  { titre: "Astrologie", texte: "L'astrologie est un ensemble de croyances et de pratiques fondées sur l'interprétation symbolique des correspondances supposées entre les configurations célestes (la position et le mouvement des planètes du système solaire) et les affaires humaines, collectives ou individuelles." },
  { titre: "Astronomie", texte: "L'astronomie est la discipline scientifique qui étudie les objets célestes afin d'expliquer leurs propriétés physiques et chimiques ainsi que leur origine et leur évolution. Elle prend sa source dans l'observation du ciel." },
  { titre: "Athéna", texte: "Athéna, ou Athéné, est une déesse grecque antique et une des principales divinités des panthéons grecs. Ses pouvoirs, très étendus, concernent principalement la protection des cités et de la vie civique, la guerre, l'artisanat et les techniques." },
  { titre: "Attaque de Pearl Harbor", texte: "L'attaque de Pearl Harbor est une attaque surprise menée par les forces aéronavales japonaises le 7 décembre 1941 contre la base navale de Pearl Harbor située sur l'île d'Oahu, à Hawaï." },
  { titre: "Attentat de Sarajevo", texte: "L’attentat de Sarajevo est l’assassinat perpétré le dimanche 28 juin 1914, de l’archiduc François-Ferdinand, héritier de l'Empire austro-hongrois, et de son épouse, Sophie Chotek, duchesse de Hohenberg, par le nationaliste serbe Gavrilo Princip, membre du groupe Jeune Bosnie (Mlada Bosna)." },
  { titre: "Attila", texte: "Attila, né peut-être vers 395-400 dans les plaines du Danube et mort en mars 453 dans la région de la Tisza dans l'Est de la Hongrie actuelle, fréquemment appelé Attila le Hun, est le souverain des Huns de 434 jusqu'à sa mort en mars 453." },
  { titre: "Auguste", texte: "Auguste, né le 23 septembre 63 av. J.-C. à Rome et mort le 19 août 14 apr. J.-C. à Nola, près de Naples, est le premier empereur romain, régnant du 16 janvier 27 av. J.-C. jusqu'à sa mort." },
  { titre: "Auguste et Louis Lumière", texte: "Auguste et Louis Lumière, souvent désignés par l'expression frères Lumière, sont deux ingénieurs et industriels français qui ont joué un rôle primordial dans l'histoire du cinéma et de la photographie." },
  { titre: "Auguste Renoir", texte: "Pierre-Auguste Renoir dit Auguste Renoir, né le 25 février 1841 à Limoges (Haute-Vienne) et mort le 3 décembre 1919 au domaine des Collettes à Cagnes-sur-Mer, est l'un des plus célèbres peintres français." },
  { titre: "Auguste Rodin", texte: "Auguste Rodin (René François Auguste Rodin), né à Paris le 12 novembre 1840 et mort à Meudon le 17 novembre 1917, est l'un des plus importants sculpteurs français de la seconde moitié du XIXe siècle, considéré comme un des pères de la sculpture moderne." },
  { titre: "Autochtones d'Amérique", texte: "Les autochtones d'Amérique constituent les peuples qui habitent originairement les Amériques, avant la colonisation européenne, ainsi que leur descendance." },
  { titre: "Automobile", texte: "Une automobile (simplification historique de l'expression « voiture légère automobile ») est un véhicule à roues, motorisé, destiné au transport terrestre de quelques personnes et de leurs bagages." },
  { titre: "Autriche-Hongrie", texte: "L'Autriche-Hongrie (en allemand : Österreich-Ungarn, en hongrois : Ausztria-Magyarország), en forme longue habituelle la Monarchie austro-hongroise (en allemand : Österreichisch-Ungarische Monarchie, en hongrois : Osztrák-Magyar Monarchia), parfois appelée l'Empire austro-hongrois, est un ancien empire d'Europe" },
  { titre: "Avion", texte: "Un avion est un aérodyne (un aéronef plus lourd que l'air), entraîné par un propulseur, dont la portance aérodynamique est obtenue par des surfaces fixes (ailes)." },
  { titre: "Aztèques", texte: "Les Aztèques, ou Mexicas (du nom de leur capitale, Mexico-Tenochtitlan), sont un ancien peuple amérindien du groupe nahua, c'est-à-dire de langue nahuatl." },
  { titre: "Baba Yaga", texte: "Baba Yaga est une figure marquante de la mythologie slave. La Baba Yaga est la figure féminine surnaturelle la plus fréquente des contes slaves, elle n'existe nulle part ailleurs (ni dans la littérature, ni dans le reste du folklore)." },
  { titre: "Babylone", texte: "Babylone (akkadien : Bāb-ili(m) ; sumérien : KÁ.DINGIR.RA ; arabe : بابل, Bābil ; araméen : Babel) était une ville antique de Mésopotamie. C'est aujourd'hui un site archéologique majeur qui prend la forme d'un champ de ruines incluant des reconstructions partielles dans un but politique ou touristique." },
  { titre: "Backgammon", texte: "Le backgammon est un jeu de hasard raisonné pour deux joueurs pratiqué sur un tablier avec des dés. Un joueur gagne lorsqu'il retire tous ses pions du tablier. Le backgammon fait partie de la famille des jeux de tables, une des plus anciennes catégories de jeu de tablier." },
  { titre: "Balbuzard pêcheur", texte: "Le Balbuzard pêcheur (Pandion haliaetus) est une espèce de rapaces diurnes de taille moyenne ; c'est un piscivore spécialisé et cosmopolite." },
  { titre: "Baleine à bosse", texte: "La Baleine à bosse, le Mégaptère, la Jubarte ou, au Canada francophone, le Rorqual à bosse (Megaptera novaeangliae) est une espèce de cétacés à fanons (mysticètes). Sa longueur moyenne est de 14 mètres, pour une masse de 30 tonnes." },
  { titre: "Baleine bleue", texte: "La baleine bleue (Balænoptera musculus), appelée aussi rorqual bleu, est une espèce de cétacés de la famille des balænopteridés. Sa longueur moyenne est de 25 à 27 m pour une masse de 130 tonnes, les femelles étant plus grandes que les mâles." },
  { titre: "Balkans", texte: "Les Balkans, comprenant principalement la péninsule balkanique, sont une région géographique située dans l’Europe du Sud-Est. La péninsule est bordée par des mers sur trois côtés : la mer Adriatique et la mer Ionienne à l'ouest, la mer Égée au sud et la mer de Marmara et la mer Noire à l'est." },
  { titre: "Baltimore", texte: "Baltimore est une ville du Nord-Est des États-Unis située dans l'État du Maryland. Constituant un des plus grands ports maritimes de la côte est, la ville abrite la prestigieuse université Johns-Hopkins et, dans sa banlieue, un campus de l'université du Maryland." },
  { titre: "Bamako", texte: "Bamako, la capitale du Mali. Dotée d'un important port fluvial sur le Niger et centre commercial rayonnant sur toute la sous-région, la ville est aussi le principal centre administratif du pays, ainsi que le siège du district de Bamako." },
  { titre: "Banane", texte: "La banane est le fruit ou la baie dérivant de l’inflorescence du bananier. Les bananes sont des fruits très généralement stériles issus de variétés domestiquées. Seuls les fruits des bananiers sauvages et de quelques cultivars domestiques contiennent des graines." },
  { titre: "Bande dessinée", texte: "Une bande dessinée (dénomination communément abrégée en BD ou en bédé) est une forme d'expression artistique, souvent désignée comme le « neuvième art », utilisant une juxtaposition de dessins (ou d'autres types d'images fixes, mais pas uniquement photographiques), articulés en séquences narratives et le plus souvent" },
  { titre: "Bangladesh", texte: "Le Bangladesh, en forme longue la république populaire du Bangladesh, est un pays sud-asiatique. Situé au nord du golfe du Bengale, quasiment enclavé dans l'Inde, il a une petite frontière commune avec la Birmanie." },
  { titre: "Bantous", texte: "On nomme « Bantu » (du kikongo bantu, signifiant « humains », singulier muntu), les locuteurs des langues bantoues (environ quatre cent cinquante langues) sur le continent africain. Ils sont répartis du Cameroun aux Comores et du Soudan à l’Afrique du Sud." },
  { titre: "Barbade", texte: "La Barbade (en anglais : Barbados ) est un micro-État insulaire situé en mer des Caraïbes, à proximité de la limite de celle-ci avec l'océan Atlantique, soit à environ trois kilomètres au large de la pointe la plus orientale de l'île." },
  { titre: "Barcelone", texte: "Barcelone est la capitale administrative et économique de la Catalogne, de la province de Barcelone, de la comarque du Barcelonès ainsi que de son aire et de sa région métropolitaines, en Espagne." },
  { titre: "Baroque", texte: "Le baroque est un mouvement artistique qui trouve son origine en Italie dans des villes telles que Rome, Mantoue, Venise et Florence dès le milieu du XVIe siècle et qui se termine au milieu du XVIIIe siècle." },
  { titre: "Baseball", texte: "Le baseball est un sport collectif dérivé des mêmes racines que le cricket, qui se pratique sur un terrain de gazon et de sable. Il se joue avec des battes pour frapper une balle lancée, et des gants pour rattraper la balle." },
  { titre: "Basilique Saint-Pierre", texte: "La basilique Saint-Pierre (en latin : Sancti Petri et en italien : Basilica di San Pietro in Vaticano) ou la basilique papale Saint-Pierre au Vatican (Basilica Papale di San Pietro in Vaticano), parfois appelée Saint-Pierre de Rome, est l'édifice religieux le plus important du catholicisme." },
  { titre: "Basket-ball", texte: "Le basket-ball ou basketball, fréquemment désigné par son abréviation basket, est un sport collectif de balle opposant deux équipes de cinq joueurs sur un terrain de forme rectangulaire." },
  { titre: "Bataille d'Hastings", texte: "La bataille d'Hastings se déroule au cours de la conquête normande de l'Angleterre le 14 octobre 1066 à une dizaine de kilomètres au nord-ouest de la ville d'Hastings, dans le Sussex de l'Est." },
  { titre: "Bavière", texte: "La Bavière (en allemand : Bayern), officiellement l'État libre de Bavière (Freistaat Bayern), est située dans le Sud-Est de l'Allemagne et est un des seize Länder allemands. Sa capitale est Munich. Elle est nommée Boiaria, Bajuvaria ou simplement Bavaria en latin, Bayern en allemand." },
  { titre: "Bénin", texte: "Le Bénin, en forme longue la république du Bénin, historiquement connu sous le nom de Dahomey, est un État d'Afrique de l'Ouest, qui couvre une superficie de 114 763 km2 et s'étend sur 700 km, du fleuve Niger au nord à la côte atlantique au sud." },
  { titre: "Benito Mussolini", texte: "Benito Mussolini, né le 29 juillet 1883 à Predappio (royaume d'Italie) et mort le 28 avril 1945 à Giulino di Mezzegra, est un journaliste, idéologue et homme d'État d'extrême droite italien." },
  { titre: "Benjamin Franklin", texte: "Benjamin Franklin /ˈbɛnd͡ʒəmɪn ˈfɹæŋklɪn/, né le 17 janvier 1706 à Boston et mort le 17 avril 1790 à Philadelphie, est un imprimeur, éditeur, écrivain, naturaliste, humaniste, inventeur, abolitionniste, diplomate et homme politique américain." },
  { titre: "Benoît de Nursie", texte: "Benoît de Nursie (en italien : Norcia ; en latin : Benedictus de Nursia), saint Benoît (en latin : Sanctus Benedictus de Nursia) pour les catholiques et les orthodoxes, né vers 480 à Nursie en Ombrie et mort en 547 dans le monastère du Mont-Cassin, est le fondateur de l'ordre des Bénédictins et a largement inspiré le" },
  { titre: "Berbères", texte: "Les Berbères, ou Amazighs, sont un groupe ethnique, autochtone d'Afrique du Nord. Connus dans l'Antiquité sous le nom de Libyens, les Berbères ont porté différents noms durant l'histoire, tels que Mazices, Maures, Numides, Gétules, Garamantes et autres." },
  { titre: "Bernard Montgomery", texte: "Bernard Law Montgomery, 1er vicomte Montgomery d'Alamein, est un field marshal britannique, né le 17 novembre 1887 à Londres et mort le 24 mars 1976 à Alton (Hampshire). On le connaît aussi sous son surnom « Monty »." },
  { titre: "Bertolt Brecht", texte: "Bertolt Brecht, né le 10 février 1898 à Augsbourg (Bavière) et mort le 14 août 1956 à Berlin-Est (RDA), est un dramaturge, metteur en scène, écrivain et poète allemand." },
  { titre: "Bertrand Russell", texte: "Bertrand Arthur William Russell, 3e comte Russell, né le 18 mai 1872 à Trellech (Monmouthshire) et mort le 2 février 1970 près de Penrhyndeudraeth (pays de Galles), est un mathématicien, logicien, philosophe, épistémologue, homme politique et moraliste britannique." },
  { titre: "Bette Davis", texte: "Bette Davis, née le 5 avril 1908 à Lowell (Massachusetts) et morte le 6 octobre 1989 à Neuilly-sur-Seine (France), est une actrice américaine, renommée pour sa forte personnalité et son talent artistique exprimé au cours d'une carrière longue de six décennies et composée de plus d'une centaine de films." },
  { titre: "Bibliothèque d'Alexandrie", texte: "La bibliothèque d'Alexandrie, fondée à Alexandrie, en Égypte, par Ptolémée Ier, ancien général d'Alexandre le Grand, en 288 avant notre ère, est la plus célèbre bibliothèque de l'Antiquité. Elle réunissait en son sein les ouvrages les plus importants de l'époque hellénistique." },
  { titre: "Bibliothèque nationale de France", texte: "La Bibliothèque nationale de France (BnF ou BNF), ainsi dénommée depuis 1994, est la bibliothèque nationale de la République française, inaugurée sous cette nouvelle appellation le 30 mars 1995 par le président de la République, François Mitterrand." },
  { titre: "Bière", texte: "La bière est une boisson alcoolisée obtenue par fermentation alcoolique d'un moût de produits végétaux amylacés tels que l'orge, le maïs, le riz, la banane, le manioc… Ce moût est obtenu à l'issue d'une étape importante de la fabrication de la bière, le brassage, opération à l'origine des vocables brasseur et" },
  { titre: "Bill Cosby", texte: "William Cosby, Jr., dit Bill Cosby, né le 12 juillet 1937 à Philadelphie, Pennsylvanie (États-Unis) est un acteur, producteur, scénariste, humoriste, compositeur et réalisateur américain." },
  { titre: "Bill Gates", texte: "William Henry Gates III, dit Bill Gates, né le 28 octobre 1955 à Seattle (État de Washington) est un informaticien, entrepreneur, homme d'affaires, milliardaire et philanthrope américain. Il est cofondateur de Microsoft en 1975 et son principal actionnaire jusqu’en 2014." },
  { titre: "Billie Holiday", texte: "Eleanora Fagan dite Billie Holiday et surnommée Lady Day, née à Philadelphie (Pennsylvanie) le 7 avril 1915 et morte à New York (État de New York) le 17 juillet 1959, est l'une des plus grandes chanteuses américaines de blues et de jazz." },
  { titre: "Billy Wilder", texte: "Billy Wilder, né le 22 juin 1906 à Sucha en Galicie (à l'époque dans l'Empire austro-hongrois, aujourd'hui Pologne) et mort le 27 mars 2002 à Beverly Hills en Californie (États-Unis), est un réalisateur, producteur et scénariste autrichien de films noirs et de comédies." },
  { titre: "Bisexualité", texte: "La bisexualité est le fait d'éprouver une attirance sexuelle ou des sentiments amoureux pour plusieurs genres. La bisexualité ne se limite pas au binaire de genre, mais elle est souvent perçue à tort comme telle." },
  { titre: "Blackjack", texte: "Le blackjack, black jack, black jacks ou encore black-jack (signifiant « valet noir » en anglais) est un jeu de cartes populaire dans les casinos physiques et les casinos virtuels." },
  { titre: "Blaise Pascal", texte: "Blaise Pascal, né le 19 juin 1623 à Clermont-Ferrand (devenue Clermont-Ferrand) en Auvergne et mort le 19 août 1662 à Paris, est un polymathe : mathématicien, physicien, inventeur, philosophe, moraliste et théologien français." },
  { titre: "Boson de Higgs", texte: "Le boson de Higgs, ou boson BEH, est une particule élémentaire du modèle standard de la physique des particules produite par l'excitation du champ de Higgs, lequel donne leur masse à certaines particules, notamment celles de la matière ordinaire, par le mécanisme de Higgs." },
  { titre: "Bouleau", texte: "Les bouleaux (Betula) forment un genre de plantes à fleurs de la famille des bétulacées. La plupart des espèces sont des arbres ; quelques-unes, comme Betula nana, sont des chaméphytes." },
  { titre: "Brandy", texte: "Brandy est un terme de langue anglaise qui désigne une eau-de-vie de vin, obtenue par distillation de vin de cépages rouges ou blancs. Le cognac est un type de brandy qui vient tout simplement de la région de Cognac." },
  { titre: "Brazzaville", texte: "Brazzaville est la capitale politique et administrative, ainsi que la ville la plus peuplée de la république du Congo. Elle fut la capitale de la France libre de 1940 à 1942 et de l'Afrique-Équatoriale française de 1910 à 1958." },
  { titre: "Brésil", texte: "Le Brésil, en forme longue la république fédérative du Brésil (República Federativa do Brasil ), est le plus grand État d'Amérique latine. Désigné comme pays-continent, le Brésil est le cinquième plus grand pays de la planète, derrière la Russie, le Canada, les États-Unis et la Chine." },
  { titre: "Bretagne", texte: "La Bretagne, dérivé du latin Britannia, est une région historique et culturelle du Nord-Ouest de la France, et une des six nations dites celtiques. La péninsule qu'elle occupe est située entre la Manche au nord, la mer Celtique et la mer d'Iroise à l'ouest et le golfe de Gascogne au sud." },
  { titre: "Bruce Lee", texte: "Lee Jun-fan, dit Bruce Lee, est un artiste martial, acteur, réalisateur, producteur et scénariste sino-américain, né le 27 novembre 1940 à San Francisco (États-Unis) et mort le 20 juillet 1973 à Hong Kong." },
  { titre: "Brunei", texte: "Brunei ou Brunéi, en forme longue Brunei Darussalam ou Brunéi Darussalam (en malais : Negara Brunei Darussalam), est un micro-État situé dans le nord de l’île de Bornéo, en Asie du Sud-Est. Il partage l'île avec la Malaisie et l’Indonésie." },
  { titre: "Budapest", texte: "Budapest est la plus grande ville et la capitale de la Hongrie. Elle se situe en aval du coude du Danube entre le massif de Transdanubie et l'Alföld. Ses habitants sont les Budapestois (en hongrois, budapesti, -ek)." },
  { titre: "Buenos Aires", texte: "Buenos Aires, officiellement la ville autonome de Buenos Aires (en espagnol : Ciudad Autónoma de Buenos Aires), est la capitale et la ville la plus importante de l'Argentine. Située dans l'hémisphère sud, elle constitue l'une des capitales les plus méridionales de la Terre." },
  { titre: "Bulgarie", texte: "La Bulgarie, en forme longue la république de Bulgarie, est un pays d'Europe du Sud-Est situé dans les Balkans, et qui fait partie de l’Union Européenne depuis 2007." },
  { titre: "Burkina Faso", texte: "Le Burkina Faso, « patrie des (Hommes) intègres » ou « patrie de l'intégrité » (Burkina se traduisant par « intégrité, honneur » en mooré et Faso se traduisant par « terre ou patrie » en dioula) ou Burkina, anciennement république de Haute-Volta, est un pays d'Afrique de l'Ouest." },
  { titre: "Burundi", texte: "Le Burundi, en forme longue la république du Burundi (en kirundi : Republika y'Uburundi), est un pays d'Afrique de l'Est sans accès à la mer mais possédant un grand rivage sur le lac Tanganyika, situé dans la région des Grands Lacs et bordé à l'ouest par la république démocratique du Congo, au nord par le Rwanda et à" },
  { titre: "Buster Keaton", texte: "Joseph Keaton Jr., dit Buster Keaton, est un acteur, réalisateur, scénariste, producteur et cascadeur américain, né le 4 octobre 1895 à Piqua (Kansas) et mort le 1er février 1966 à Hollywood (Californie)." },
  { titre: "Calendrier grégorien", texte: "Le calendrier grégorien est un calendrier solaire conçu à la fin du XVIe siècle pour prendre en compte la dérive séculaire du calendrier julien alors en usage." },
  { titre: "Calendrier hégirien", texte: "Le calendrier hégirien ou calendrier musulman est un calendrier lunaire synodique non solaire, fondé sur une année de 12 mois lunaires de 29 ou 30 jours chacun. Le jour hégirien commence au coucher du soleil et s'achève au même moment le lendemain." },
  { titre: "Calendrier julien", texte: "Le calendrier julien est un calendrier solaire utilisé dans la Rome antique, introduit par Jules César en 46 av. J.-C. pour remplacer le calendrier romain républicain. Il a été employé en Europe occidentale jusqu'à son remplacement par le calendrier grégorien à la fin du XVIe siècle." },
  { titre: "Californie", texte: "La Californie (en anglais et en espagnol : California) est un État des États-Unis qui fait partie de la région de la Sun Belt dans l'Ouest américain. Sa capitale est Sacramento. Avec 39 528 223 habitants selon le recensement officiel de 2020, la Californie est l'État le plus riche et le plus peuplé du pays." },
  { titre: "Cambodge", texte: "Le Cambodge (en khmer : កម្ពុជា, romanisé en Kâmpŭchéa), ou en forme longue le royaume du Cambodge (en khmer : ព្រះរាជាណាចក្រកម្ពុជា, romanisé en Preăhréachéanachâkr Kâmpŭchéa), aussi appelé Srok Khmer, ស្រុកខ្មែរ, littéralement « le pays khmer », est un pays d'Asie du Sud-Est, peuplé d’environ 17 millions d'habitants." },
  { titre: "Cameroun", texte: "Le Cameroun, en forme longue la république du Cameroun (en anglais : Cameroon et Republic of Cameroon), est un État d'Afrique centrale et occidentale situé entre le Nigeria au nord-nord-ouest, le Tchad au nord-nord-est, la République centrafricaine à l'est, la république du Congo au sud-est, le Gabon au sud, la Guinée" },
  { titre: "Campagne de Russie", texte: "La campagne de Russie, également connue en Russie comme la guerre patriotique de 1812, est une campagne militaire menée par l’empereur Napoléon Ier en 1812 et lors de laquelle les troupes françaises ont envahi l'Empire russe." },
  { titre: "Camps de concentration nazis", texte: "Les camps de concentration nazis sont des centres de détention de grande taille créés par le Troisième Reich à partir de 1933 et jusqu'à la fin de la Seconde Guerre mondiale, pour interner, exploiter la force de travail et tuer des opposants politiques, des résidents d'un pays conquis, des groupes ethniques ou" },
  { titre: "Canal de Panama", texte: "Le canal de Panama (espagnol : canal de Panamá) est un canal maritime de 80 km de long, qui traverse l'isthme de Panama en Amérique centrale, reliant l’océan Pacifique et l’océan Atlantique. Sa construction a été l'un des projets d’ingénierie les plus difficiles jamais entrepris." },
  { titre: "Canal de Suez", texte: "Le canal de Suez est un canal navigable situé en Égypte. Long de 193,3 km, large de 280 à 345 m et profond de 22,5 m, il relie, via trois lacs naturels, la ville portuaire de Port-Saïd en mer Méditerranée à la ville de Suez dans le golfe de Suez au nord de la mer Rouge." },
  { titre: "Cannelle", texte: "La cannelle est une épice constituée de l'écorce intérieure de certains arbres (les canneliers) de la famille des Lauracées. Toutes les parties de la plante étant aromatiques, l'épice englobe également les fleurs, les fruits et les déchets (appelés chips) de l'arbre, qu'ils soient entiers, écrasés ou moulus." },
  { titre: "Canton", texte: "Canton ou Guangzhou est la capitale de la province du Guangdong dans le sud de la Chine. Elle a le statut administratif de ville sous-provinciale de la république populaire de Chine." },
  { titre: "Cap Horn", texte: "Le cap Horn (en espagnol : cabo de Hornos, en yagan : Loköshpi) est un cap situé à l’extrémité sud de l'île Horn, dans la partie chilienne de l’archipel de la Terre de Feu. Ce point est généralement considéré comme étant le plus austral de l’Amérique du Sud." },
  { titre: "Cap-Vert", texte: "Le Cap-Vert, officiellement Cabo Verde, en forme longue la république du Cap-Vert ou république de Cabo Verde (en portugais : Cabo Verde et República de Cabo Verde), est un État insulaire d'Afrique de l'Ouest, composé d'un archipel de dix îles volcaniques." },
  { titre: "Capétiens", texte: "Les Capétiens forment une dynastie princière d’origine franque, issue des Robertiens dont l'origine certaine remonte à Robert le Fort qui vivait au IXe siècle en Neustrie et dont l'arrière-petit-fils Hugues Capet est élu roi des Francs en 987." },
  { titre: "Celtes", texte: "Les Celtes constituent, durant la protohistoire européenne, un groupe de populations indo-européennes parlant des langues celtiques et présentant une certaine unité culturelle, bien que les interactions culturelles de l'Europe celtique ancienne demeurent incertaines et controversées." },
  { titre: "Changement climatique", texte: "Le changement climatique, également nommé réchauffement climatique voire dérèglement climatique, est l'effet de l'augmentation rapide de la température moyenne de la surface terrestre en cours aux XXe et XXIe siècles ainsi que, plus généralement, la modification des régimes météorologiques à grande échelle qui en" },
  { titre: "Chapelle Sixtine", texte: "La chapelle Sixtine (en italien, Cappella Sistina), appelée originellement chapelle de Sixte, est une des salles des palais pontificaux du Vatican et fait partie des musées du Vatican." },
  { titre: "Charles de Gaulle", texte: "Charles de Gaulle, couramment appelé le général de Gaulle ou simplement le Général, né le 22 novembre 1890 à Lille (Nord) et mort le 9 novembre 1970 à Colombey-les-Deux-Églises (Haute-Marne), est un militaire, résistant, homme d'État et écrivain français." },
  { titre: "Charles Dickens", texte: "Charles Dickens, né le 7 février 1812 à Landport, près de Portsmouth, dans le Hampshire, comté de la côte sud de l'Angleterre, et mort le 9 juin 1870 à Gad's Hill Place à Higham dans le Kent, est un écrivain anglais, considéré comme le plus grand romancier de l'époque victorienne." },
  { titre: "Charles Ier", texte: "Charles Ier, né le 19 novembre 1600 à Dunfermline et mort le 30 janvier 1649 à Londres, est roi d'Angleterre, d'Écosse et d'Irlande de 1625 à son exécution en 1649." },
  { titre: "Charles Lindbergh", texte: "Charles Lindbergh, né le 4 février 1902 à Détroit (Michigan) et mort le 26 août 1974 à Kipahulu sur l'île de Maui (Hawaï), est un des pionniers américains de l'aviation." },
  { titre: "Charles Martel", texte: "Charles Martel (en latin : Carolus Martellus ; en allemand : Karl Martell), né vers 688 à Andenne, en Belgique actuelle, et mort le 22 octobre 741 à Quierzy en France actuelle, est un homme d’État et chef militaire franc qui, en tant que duc des Francs et maire du palais, était de facto dirigeant de la Francie de 718" },
  { titre: "Charles Perrault", texte: "Charles Perrault, né le 12 janvier 1628 à Paris et mort dans la même ville le 16 mai 1703 est un homme de lettres français, célèbre pour ses Contes de ma mère l’Oye." },
  { titre: "Charles Quint", texte: "Charles de Habsbourg, couramment appelé en français Charles Quint, né le 24 février 1500 à Gand (comté de Flandre) et mort le 21 septembre 1558 au monastère de Yuste (Espagne), élu le 28 juin 1519 empereur sous le nom de Charles V, est le monarque européen le plus puissant de la première moitié du XVIe siècle." },
  { titre: "Charlie Chaplin", texte: "Charlie Chaplin est un acteur, réalisateur, scénariste, producteur et compositeur britannique, né le 16 avril 1889 à Walworth, un district du Sud de Londres (Royaume-Uni), et mort le 25 décembre 1977 à Corsier-sur-Vevey (Suisse)." },
  { titre: "Chat", texte: "Le Chat, plus spécifiquement désigné sous le nom de Chat domestique (Felis catus), est une espèce de mammifères de l’Ordre des Carnivores, de la famille des félins (Félidés)." },
  { titre: "Château de Versailles", texte: "Le château de Versailles est un château et un monument historique français situé à Versailles, dans les Yvelines. Il fut la résidence principale des rois de France Louis XIV, Louis XV et Louis XVI." },
  { titre: "Che Guevara", texte: "Ernesto Rafael Guevara De La Serna, nommé Ernesto Guevara, plus connu sous le nom de « Che Guevara » (/(t)ʃe ɡevaʁa/ ; en espagnol : /t͡ʃe ɡeˈβaɾa/) ou « le Che », né le 14 juin 1928 d'après son acte de naissance (mais réellement le 14 mai 1928 d'après sa mère) à Rosario (Argentine) et mort exécuté le 9 octobre 1967 à" },
  { titre: "Cheval", texte: "Le cheval (Equus ferus caballus ou Equus caballus) est un grand mammifère herbivore et ongulé à sabot unique ; c'est l'une des espèces de la famille des Équidés (Equidae), lesquelles ont évolué, au cours des derniers 45 à 55 millions d'années, à partir d'un petit mammifère possédant plusieurs doigts." },
  { titre: "Chicago", texte: "Chicago est la troisième ville des États-Unis par sa population et est située dans le nord-est de l'État de l'Illinois. C'est la plus grande ville de la région du Midwest dont elle forme le principal centre économique et culturel." },
  { titre: "Chien", texte: "Le Chien, plus précisément désigné sous le nom de Chien domestique (Canis familiaris ou Canis lupus familiaris), est une espèce de mammifère de la famille des Canidés (Canidae). Il s’agit de la forme domestiquée du loup gris (Canis lupus), laquelle comprend également le dingo, retourné à l'état sauvage." },
  { titre: "Chili", texte: "Le Chili, en forme longue la république du Chili (en espagnol Chile et República de Chile), est un pays d’Amérique du Sud partageant ses frontières avec le Pérou et la Bolivie au nord et avec l’Argentine au nord-est, à l'est et au sud-est." },
  { titre: "Chine", texte: "La Chine, en forme longue la république populaire de Chine, également appelée de manière informelle Chine populaire et Chine communiste, est un pays d'Asie de l'Est." },
  { titre: "Christophe Colomb", texte: "Christophe Colomb (en ligure : Cristoffa Combo ; en italien : Cristoforo Colombo ; en espagnol : Cristóbal Colón) est un navigateur génois, né en 1451 sur le territoire de la république de Gênes et mort le 20 mai 1506 à Valladolid (Espagne)." },
  { titre: "Cinéma", texte: "Le cinéma est un art du spectacle. En français, il est désigné comme le « septième art », d'après l'expression du critique Ricciotto Canudo dans les années 1920." },
  { titre: "Cinéma français", texte: "Le cinéma français occupe une place privilégiée dans l'histoire du cinéma, avec des scientifiques comme Joseph Plateau et Étienne-Jules Marey, des inventeurs de premier rang dont les découvertes ont été fondamentales, et avec des pionniers aussi imaginatifs que Alice Guy-Blaché, Émile Reynaud, Louis Lumière, Georges" },
  { titre: "Climatisation", texte: "La climatisation est la technique qui consiste à modifier, contrôler et réguler les conditions climatiques (température, humidité, niveau de poussières, etc.) d’un intérieur pour des raisons de confort (automobile, bureaux, maisons individuelles) ou pour des raisons techniques (laboratoires médicaux, locaux de" },
  { titre: "Cocaïne", texte: "La cocaïne est un alcaloïde tropanique extrait de la feuille de coca. Célèbre psychotrope, elle est un très puissant stimulant du système nerveux central, et sa consommation est extrêmement addictive." },
  { titre: "Coccinellidae", texte: "Les Coccinellidae, en français coccinellidés, sont une famille d'insectes de l'ordre des coléoptères, appelés aussi coccinelles, ou encore familièrement ou régionalement « bêtes à bon Dieu » ou « pernettes »." },
  { titre: "Cocotier", texte: "Le Cocotier (Cocos nucifera) est une espèce de palmiers de la famille des Arecaceae, décrite par Carl von Linné. Le Cocotier n'est donc pas un arbre mais une plante monocotylédone." },
  { titre: "Coelacanthiformes", texte: "Les Coelacanthiformes (nom scientifique), Cœlacanthiformes (nom scientifique francisé) ou Cœlacanthes sont un ordre de poissons sarcoptérygiens. Il en existe de nombreux fossiles et deux espèces vivantes connues, du genre Latimeria (Latimeria chalumnae et Latimeria menadoensis)." },
  { titre: "Coleoptera", texte: "Les coléoptères (Coleoptera) sont un ordre d'Insectes holométaboles dotés d'élytres protégeant leurs ailes. Le mot « coléoptère » vient du grec κολεός / koleós « fourreau » et πτερόν / pterón « aile »." },
  { titre: "Conférence de Yalta", texte: "La conférence de Yalta est une réunion des principaux responsables de l'Union soviétique (Joseph Staline), du Royaume-Uni (Winston Churchill) et des États-Unis (Franklin D. Roosevelt). Elle s'est tenue du 4 au 11 février 1945 dans le palais de Livadia, situé dans les environs de la station balnéaire de Yalta en Crimée." },
  { titre: "Conflit israélo-palestinien", texte: "Le conflit israélo-palestinien oppose Palestiniens et Israéliens au Proche-Orient. Il oppose deux mouvements nationaux (le sionisme et le nationalisme palestinien)." },
  { titre: "Conflit nord-irlandais", texte: "Le conflit nord-irlandais, appelé aussi « The Troubles » (en français : Les Problèmes ; en irlandais : Na Trioblóidi ; en scots : The Truibils), est une période de violences et d'agitation politique en Irlande du Nord dans la seconde moitié du XXe siècle." },
  { titre: "Confucius", texte: "Confucius, né le 28 septembre 551 av. J.-C. à Zou et mort le 11 avril 479 av. J.-C. à Qufu dans l’actuelle province du Shandong, est un philosophe chinois. Son patronyme est Kong, son prénom Qiu, et son prénom social Zhongni." },
  { titre: "Congrès de Vienne", texte: "Le congrès de Vienne est une conférence de représentants diplomatiques des grandes puissances européennes qui a eu lieu à Vienne du 18 septembre 1814 au 9 juin 1815." },
  { titre: "Connaissance", texte: "La connaissance est une notion aux sens multiples, à la fois utilisée dans le langage courant et objet d'étude poussée de la part des sciences cognitives et des philosophes contemporains." },
  { titre: "Conquête de l'Ouest", texte: "La conquête de l'Ouest est le processus de colonisation, par des populations essentiellement d'origine européenne et le gouvernement des États-Unis au XIXe siècle, des immenses territoires qui s'étendent en Amérique du Nord entre le Mississippi et l'océan Pacifique, habités jusqu'alors par les peuples dits amérindiens." },
  { titre: "Constantin Ier", texte: "Constantin Ier, né le 27 février 272 à Naissus (l’actuelle Niš en Serbie) en Mésie supérieure et mort le 22 mai 337 près de Nicomédie (l’actuelle Izmit en Turquie), dans la Province Romaine de Bithynie et Pont, est un empereur romain majeur du IVe siècle." },
  { titre: "Constantinople", texte: "Constantinople (en grec ancien : Κωνσταντινούπολις / Kônstantinoúpolis ; en grec moderne : Κωσταντινούπολη / Konstantinoúpolis ; en latin : Constantinopolis ; en turc ottoman : قسطنطينية (Kostantiniyye)) est, de sa fondation en 330 par Constantin Ier (empereur de 306 à 337), sur le site de l'ancienne Byzance, jusqu'à" },
  { titre: "Constellation", texte: "Une constellation est, pour les dictionnaires, « un groupe d'étoiles voisines (observées en apparence depuis la Terre) sur la sphère céleste, présentant une figure conventionnelle déterminée, à laquelle on a donné un nom particulier » ; c'est aussi une « région du ciel conventionnellement délimitée qui inclut ce" },
  { titre: "Constitution des États-Unis", texte: "La Constitution des États-Unis est, selon ses propres termes, la loi suprême des États-Unis d'Amérique. Acceptée le 17 septembre 1787 par une convention réunie à Philadelphie, elle s'applique depuis le 4 mars 1789." },
  { titre: "Continent", texte: "Un continent (du latin continere pour « tenir ensemble », ou continens terra, les « terres continues ») désigne au sens propre une vaste étendue émergée continue du sol à la surface du globe terrestre." },
  { titre: "Coran", texte: "Le Coran est le texte sacré de l’islam. Pour les musulmans, il reprend mot pour mot la parole d'Allah (Dieu). Œuvre de l’Antiquité tardive (VIIe siècle), le Coran reste le premier et le plus ancien livre connu en arabe à ce jour." },
  { titre: "Cosaques", texte: "Les cosaques sont un groupe de populations majoritairement slaves originaire de régions de la steppe pontique situées sur les actuels territoires de l'Ukraine et de la Russie." },
  { titre: "Cosme de Médicis", texte: "Cosme de Médicis (Côme en français moderne et en italien Cosimo de' Medici), né le 27 septembre 1389 à Florence et mort le 1er août 1464 dans cette même ville, fut banquier, capitaine et homme d'État florentin, dirigeant effectif de la république de Florence durant la majeure partie de la Renaissance italienne." },
  { titre: "Côte d'Ivoire", texte: "La Côte d'Ivoire, en forme longue la république de Côte d'Ivoire (RCI), est un État situé en Afrique, dans la partie occidentale du golfe de Guinée. Elle présente sensiblement la forme d'un carré d'environ 600 km de côté." },
  { titre: "Crassus", texte: "Marcus Licinius Crassus (latin abrégé : M•LICINIVS•P•F•P•N•CRASSVS), né vers 115 av. J.-C. à Rome et mort en 53 av. J.-C., est un général et homme politique romain qui joua un rôle essentiel dans le passage de la République à l'Empire." },
  { titre: "Crète", texte: "La Crète, historiquement également appelée Candie (en latin, italien et vénitien : Candia), est la plus grande et la plus peuplée des îles de Grèce, et la cinquième plus grande île de la mer Méditerranée." },
  { titre: "Cristiano Ronaldo", texte: "Cristiano Ronaldo dos Santos Aveiro, couramment appelé Cristiano Ronaldo ou Ronaldo et surnommé CR7, né le 5 février 1985 à Funchal (Portugal), est un footballeur international portugais qui évolue actuellement au poste d'attaquant au Al-Nassr FC." },
  { titre: "Croatie", texte: "La Croatie, en forme longue la république de Croatie, en croate : Hrvatska et Republika Hrvatska, est un pays d'Europe centrale et du Sud. Sa capitale est Zagreb, la ville la plus peuplée du pays." },
  { titre: "Croisade", texte: "Une croisade, au Moyen Âge, est une expédition militaire bénie par la papauté, visant principalement à sécuriser ou reconquérir les lieux saints de la chrétienté en Terre sainte, en particulier Jérusalem et le Saint-Sépulcre." },
  { titre: "Cuba", texte: "Cuba, en forme longue la république de Cuba (en espagnol : República de Cuba), est un État insulaire des Caraïbes formé de l'île de Cuba (la plus grande île des Antilles), de l'île de la Jeunesse (appelée île aux Pins jusqu'en 1978) et de 4 095 cayes et îlots." },
  { titre: "Dada", texte: "Le mouvement dada, aussi appelé dadaïsme ou simplement dada, est un mouvement intellectuel, littéraire et artistique du début du XXe siècle, qui se caractérise par une remise en cause de toutes les conventions et contraintes idéologiques, esthétiques et politiques." },
  { titre: "Daghestan", texte: "La république du Daghestan est une république russe fédérée, selon la traduction officielle un sujet de la fédération de Russie. Il s'agit de la plus importante des républiques de Ciscaucasie, pour ce qui est de la superficie et de la population." },
  { titre: "Dakar", texte: "La ville de Dakar (wolof : Ndakaaru) est la capitale de la république du Sénégal et de la région de Dakar. Elle compte 1 056 009 habitants sur les 3 630 000 habitants (estimation 2018) que compte l'ensemble de la région de Dakar." },
  { titre: "Degré Celsius", texte: "Le degré Celsius, de symbole °C, est l'unité de l’échelle de température Celsius, qui est une unité dérivée du Système international, introduite le 25 décembre 1948. Son nom est une référence à l'astronome et physicien suédois Anders Celsius, inventeur en 1742 d'une des premières échelles centigrades de température." },
  { titre: "Degré Fahrenheit", texte: "Le degré Fahrenheit (symbole : °F) est une unité de mesure de la température, proposée par le physicien allemand Daniel Gabriel Fahrenheit en 1724." },
  { titre: "Détroit", texte: "Détroit est la principale cité (city) de l'État du Michigan aux États-Unis, beaucoup plus connue que sa capitale Lansing, et siège du comté de Wayne." },
  { titre: "Détroit d'Ormuz", texte: "Le détroit d'Ormuz est un détroit du golfe Persique. Il permet la communication avec le golfe d'Oman et doit son nom à l'île iranienne d’Ormuz, située au sud-est de Bandar Abbas. Les pays frontaliers sont, au nord, l'Iran et, au sud, les Émirats arabes unis (depuis Al" },
  { titre: "Détroit de Gibraltar", texte: "Le détroit de Gibraltar est situé au sud de l'Espagne, au nord du Maroc, à l'est de l'océan Atlantique et dans l'Ouest de la mer Méditerranée. C'est le seul passage maritime entre l'océan Atlantique et la mer Méditerranée, dont il constitue la partie la plus occidentale." },
  { titre: "Détroit de Magellan", texte: "Le détroit de Magellan (en espagnol : estrecho de Magallanes) est un passage maritime situé au sud du Chili en Patagonie, dans la région de Magallanes et de l'Antarctique chilien." },
  { titre: "Diamant", texte: "Le diamant est un minéral, constitué d'atomes de carbone à l'état cristallin. Sa renommée vient de sa rareté à l'état naturel et de son utilisation en joaillerie." },
  { titre: "Django Reinhardt", texte: "Jean Reinhardt, plus connu sous le nom de Django Reinhardt, est un guitariste français de jazz né le 23 janvier 1910 à Liberchies — aujourd'hui une section de la commune de Pont-à-Celles — dans la province de Hainaut, près de la ville de Charleroi, en Belgique, et mort le 16 mai 1953 à Fontainebleau." },
  { titre: "Dmitri Chostakovitch", texte: "Dmitri Dmitrievitch Chostakovitch, né le 12 septembre 1906 (25 septembre 1906 dans le calendrier grégorien) à Saint-Pétersbourg dans l'Empire russe et mort le 9 août 1975 à Moscou en URSS, est un compositeur russe de la période soviétique." },
  { titre: "Dodo", texte: "Le Dronte de Maurice (Raphus cucullatus) est une espèce d'oiseaux appartenant à la famille des Columbidae, endémique de l'île Maurice, disparue depuis la fin du XVIIe siècle." },
  { titre: "Dogue allemand", texte: "Le dogue allemand (Deutsche Dogge) est une race de chien molossoïde à poil court, originaire d'Allemagne, classée par la Fédération cynologique internationale (FCI) dans le groupe 2, section 2.1, sous le standard N°235." },
  { titre: "Doigt", texte: "Les doigts sont les extrémités articulées des mains de l'être humain et de certains animaux — l'expression courante « doigts de pied » désigne les orteils. La présence de doigts caractérise le clade des tétrapodes." },
  { titre: "Dollar américain", texte: "Le dollar américain ou dollar des États-Unis ou dollar US (symbole monétaire : $ ; code ISO : USD pour United States dollar) est la monnaie nationale des États-Unis et de ses territoires d'outre-mer ou Commonwealth (comme Porto Rico) ; c'est aussi celle de l'Équateur, du Zimbabwe, des États fédérés de Micronésie, des" },
  { titre: "Dolly Parton", texte: "Dolly Rebecca Parton, née le 19 janvier 1946 à Pittman Center (Tennessee), est une chanteuse country et pop, autrice-compositrice-interprète, musicienne multi-instrumentiste, actrice, scénariste, philanthrope, femme d'affaires et productrice américaine." },
  { titre: "Domitien", texte: "Domitien (Titus Flavius Domitianus) né le 24 octobre 51 et mort le 18 septembre 96 à Rome, est empereur romain de 81 jusqu'à sa mort. Il est le troisième et dernier représentant de la dynastie flavienne." },
  { titre: "Dopamine", texte: "La dopamine (DA) est un neurotransmetteur, une molécule biochimique qui permet la communication au sein du système nerveux, et l'un des neurotransmetteurs qui influent directement sur le comportement." },
  { titre: "Dragon de Komodo", texte: "Le dragon de Komodo ou varan de Komodo (Varanus komodoensis) est une espèce de varans qui se rencontre dans les îles de Komodo, Rinca, Florès, Gili Motang et Gili Dasami en Indonésie centrale." },
  { titre: "Drone", texte: "Les drones ou plus rarement écrit drônes sont des engins sans équipage dont le pilotage est automatique ou télécommandé, qu'ils soient volants, terrestres ou encore amphibies, à usage civil ou à celui des forces armées ou de sécurité (police, douane, gendarmerie ) d'un État." },
  { titre: "Durian", texte: "Le durian ou durion, Durio zibethinus (Murray), est une espèce d'arbres tropicaux à feuillage persistant de la famille des Bombacaceae (classification classique) ou des Malvaceae (classification phylogénétique) qui produit des fruits comestibles." },
  { titre: "Eau de Javel", texte: "L'eau de Javel (appelée aussi javel ou anciennement eau de Javelle) est une solution liquide oxydante fréquemment utilisée comme désinfectant et comme décolorant." },
  { titre: "Échecs", texte: "Les échecs, ou le jeu d'échecs, sont un jeu de société opposant deux joueurs de part et d'autre d'un tablier appelé « échiquier » constitué par un quadrillage carré de 64 cases, alternativement blanches et noires." },
  { titre: "Eleanor Roosevelt", texte: "Anna Eleanor Roosevelt (« Éléonore », la version traduite de son prénom, est souvent aussi d'usage pour les francophones), née le 11 octobre 1884 et morte le 7 novembre 1962, est une figure politique, diplomate et militante américaine." },
  { titre: "Elizabeth Taylor", texte: "Elizabeth Taylor, communément appelée Liz Taylor, est une actrice britannico-américaine, née le 27 février 1932 dans le quartier d'Hampstead Garden Suburb de Londres et morte le 23 mars 2011 dans le quartier de Beverly Grove de Los Angeles." },
  { titre: "Ella Fitzgerald", texte: "Ella Fitzgerald, née le 25 avril 1917 à Newport News (Virginie) et morte le 15 juin 1996 à Beverly Hills, est une chanteuse de jazz américaine." },
  { titre: "Elvis Presley", texte: "Elvis Presley, né le 8 janvier 1935 à Tupelo dans le Mississippi, aux États-Unis, et mort le 16 août 1977 à Memphis dans le Tennessee, est un chanteur et acteur américain." },
  { titre: "Empire allemand", texte: "L'Empire allemand (en allemand : Deutsches Kaiserreich) est le régime politique de l'Allemagne de 1871 à 1918. État-nation historique de l'Allemagne, fonctionnant comme une monarchie parlementaire autoritaire avec une organisation territoriale fédérale." },
  { titre: "Empire britannique", texte: "L'Empire britannique (en anglais : British Empire), ou empire colonial britannique, est l'ensemble des territoires qui, sous des statuts divers (colonies, protectorats, dominions, mandats, tutelles) ont été gouvernés ou administrés du début du XVIIe à la fin du XXe siècle par l'Angleterre (empire colonial anglais)," },
  { titre: "Empire byzantin", texte: "L’Empire romain d'Orient, ou Empire byzantin, est l'État apparu vers le IVe siècle dans la partie orientale de l'Empire romain, au moment où celui-ci se divise progressivement en deux." },
  { titre: "Empire carolingien", texte: "L'Empire carolingien est le résultat de l'expansion territoriale du royaume franc sous l'influence de la dynastie carolingienne pendant le haut Moyen Âge. Il s'étend de l'Europe occidentale à l'Europe centrale." },
  { titre: "Empire colonial français", texte: "L’Empire colonial français est l’ensemble des colonies, protectorats, territoires sous mandat et territoires ayant été sous tutelle, gouvernés ou administrés par la France." },
  { titre: "Empire d'Autriche", texte: "L’empire d’Autriche (allemand : Kaisertum Österreich ; graphie XIXe siècle : Kaiserthum Oesterreich) est proclamé le 11 août 1804 par François II du Saint-Empire, qui adopte le titre héréditaire d’empereur d’Autriche sous le nom de François Ier." },
  { titre: "État de New York", texte: "L'État de New York (en anglais : New York State, State of New York ou simplement New York) est un État des États-Unis, le quatrième le plus peuplé du pays avec 19,7 millions d'habitants en 2022. Il se trouve dans le nord-est du pays et a pour capitale la ville d'Albany, située dans le nord-est de l'État." },
  { titre: "États fédérés de Micronésie", texte: "Les États fédérés de Micronésie en forme longue ou Micronésie en forme courte (en anglais : Federated States of Micronesia, souvent abrégé en FSM, et Micronesia) sont un État fédéral insulaire du Sud-Ouest de l'océan Pacifique nord, constitué de quatre États, d'ouest en est, Yap, Chuuk, Pohnpei et Kosrae." },
  { titre: "États-Unis", texte: "Les États-Unis, en forme longue les États-Unis d'Amérique, également appelés de manière informelle les USA ou l'Amérique (en anglais : United States, United States of America, US, USA, America), ou familièrement les States, sont un État transcontinental dont une large majorité du territoire se situe en Amérique du" },
  { titre: "Éthiopie", texte: "L'Éthiopie, en forme longue la République fédérale démocratique d'Éthiopie (en amharique : ኢትዮጵያ, Ītyōṗṗyā et የኢትዮጵያ ፌዴራላዊ ዲሞክራሲያዊ ሪፐብሊክ ye-Ītyōṗṗyā Fēdēralāwī Dīmōkrāsīyāwī Rīpeblīk ) est un pays d'Afrique de l'Est." },
  { titre: "Eunuque", texte: "Un eunuque est un homme castré. La castration se limite généralement à l'ablation des testicules (orchidectomie), mais il arrive qu'elle concerne également le pénis, alors connue sous le nom de pénectomie (souvent avec un tube inséré pour garder ouvert l'urètre)." },
  { titre: "Euro", texte: "L'euro (symbole monétaire : € ; code ISO : EUR) est la monnaie unique de l'Union économique et monétaire formée au sein de l'Union européenne (UE). Actuellement, elle est commune à vingt-et-un États membres de l'UE qui forment ainsi la zone euro." },
  { titre: "F. Scott Fitzgerald", texte: "Francis Scott Key Fitzgerald, né le 24 septembre 1896 à Saint Paul dans l'État du Minnesota et mort le 21 décembre 1940 à Hollywood, est un écrivain américain." },
  { titre: "Famille Rothschild", texte: "La famille Rothschild est une famille d'origine juive allemande ashkénaze, qui a essaimé dans plusieurs pays et dont les membres sont aujourd'hui de différentes nationalités et confessions." },
  { titre: "Federico Fellini", texte: "Federico Fellini, né le 20 janvier 1920 à Rimini et mort le 31 octobre 1993 à Rome, est un réalisateur, scénariste de cinéma et de bande dessinée, caricaturiste, acteur et écrivain italien." },
  { titre: "Federico García Lorca", texte: "Federico García Lorca est un poète et dramaturge espagnol, également prosateur, peintre, pianiste et compositeur, né le 5 juin 1898 à Fuente Vaqueros, près de Grenade, et mort le 19 août 1936." },
  { titre: "Felix Mendelssohn", texte: "Jakob Ludwig Felix Mendelssohn Bartholdy, plus couramment appelé Felix Mendelssohn (parfois Félix avec accent), né le 3 février 1809 à Hambourg et mort le 4 novembre 1847 à Leipzig, est un compositeur, chef d'orchestre et pianiste allemand du début de la période romantique." },
  { titre: "François d'Assise", texte: "François d'Assise (en italien : Francesco d'Assisi), né Giovanni di Pietro Bernardone en 1181 ou 1182 à Assise (Italie actuelle), et mort le 3 octobre 1226 dans cette même ville, est un religieux catholique italien, diacre, mystique, auteur d'écrits, et fondateur de l'ordre des Frères mineurs (O.F.M.) en 1210," },
  { titre: "François Ier", texte: "François Ier, né sous le nom de François d’Angoulême le 12 septembre 1494 à Cognac et mort le 31 mars 1547 à Rambouillet, est un roi de France ayant régné de 1515 jusqu’à sa mort. Fils de Charles d'Orléans et de Louise de Savoie, il appartient à la branche de Valois-Angoulême de la dynastie capétienne." },
  { titre: "François Mitterrand", texte: "François Mitterrand, né le 26 octobre 1916 à Jarnac (Charente) et mort le 8 janvier 1996 dans le 7e arrondissement de Paris, est un homme d'État français. Il est président de la République française du 21 mai 1981 au 17 mai 1995." },
  { titre: "François Rabelais", texte: "François Rabelais (également connu sous deux anagrammes de son nom : Alcofribas Nasier ou bien Serafin Calobarsy — où « Françoys » est écrit en moyen français), né à la Devinière à Seuilly, près de Chinon (dans l'ancienne province de Touraine), en 1483 ou en 1494 selon les sources, et mort à Paris le 9 avril 1553, est" },
  { titre: "François Truffaut", texte: "François Truffaut est un cinéaste français, né le 6 février 1932 dans le 17e arrondissement de Paris et mort le 21 octobre 1984 à Neuilly-sur-Seine." },
  { titre: "Fred Astaire", texte: "Frederick Austerlitz, dit Fred Astaire, est un acteur, danseur à claquettes, chanteur, magicien et compositeur américain, né le 10 mai 1899 à Omaha (Nebraska) et mort le 22 juin 1987 à Los Angeles (Californie)." },
  { titre: "Freyja", texte: "Freyja est une déesse majeure des mythologies germanique et nordique, mentionnée ou représentée dans de nombreux récits. Néanmoins, certaines sources documentées de cette tradition religieuse sont à considérer avec prudence, car elles ont pu subir l'influence des représentations chrétiennes ou classiques." },
  { titre: "Gabon", texte: "Le Gabon (en forme longue, la République gabonaise) est un pays situé en Afrique centrale, traversé par l'équateur, frontalier à l'est, au sud-est et au sud de la république du Congo, au nord-nord-ouest de la Guinée équatoriale et au nord du Cameroun." },
  { titre: "Galaxie d'Andromède", texte: "La galaxie d'Andromède, également désignée M31 dans le Catalogue de Messier et NGC 224, est une galaxie spirale située à environ 2,55 millions d'années-lumière du Soleil, dans la constellation d'Andromède." },
  { titre: "Gale", texte: "La gale ou scabiose (respectivement de galla « galle » et de scabies « gale ») est une maladie infectieuse de la peau causée par un parasite de type acarien microscopique, le sarcopte (Sarcoptes scabiei)." },
  { titre: "Galice", texte: "La Galice (en galicien : Galicia ou Galiza ; en espagnol : Galicia) est une communauté avec un statut de nation historique (en galicien : nacionalidade histórica), située à l'extrémité nord-ouest de l'Espagne." },
  { titre: "Gambie", texte: "La Gambie, en forme longue la république de Gambie (en anglais : Gambia ou The Gambia, et Republic of The Gambia), est un pays d'Afrique de l'Ouest." },
  { titre: "Gaza", texte: "Gaza est la principale ville de la bande de Gaza. Elle est parfois appelée « ville de Gaza » ou « Gaza-ville » pour la distinguer du territoire auquel elle donne son nom." },
  { titre: "Genève", texte: "Genève est une ville suisse située à l'extrémité sud-ouest du Léman. Elle est la deuxième ville de Suisse après Zurich, et le chef-lieu de la République et canton de Genève (GE)." },
  { titre: "Georg Friedrich Haendel", texte: "Georg Friedrich Haendel ou Georg Friederich Händel est un compositeur saxon, devenu anglais par naturalisation, né le 23 février 1685 à Halle-sur-Saale et mort le 14 avril 1759 à Westminster." },
  { titre: "Ghana", texte: "Le Ghana, en forme longue la république du Ghana (en anglais : Republic of Ghana), est un pays d'Afrique de l'Ouest situé au bord du golfe de Guinée. La langue officielle du Ghana est l'anglais et la devise nationale est le cedi." },
  { titre: "Gibraltar", texte: "Gibraltar est un territoire britannique d'outre-mer, situé dans le sud de la péninsule Ibérique, en bordure de la mer d'Alboran et du détroit de Gibraltar, ce dernier reliant la Méditerranée à l'océan Atlantique." },
  { titre: "Glasgow", texte: "Glasgow est la principale métropole d’Écosse et la troisième ville du Royaume-Uni, derrière Londres et Birmingham. Elle a aussi le statut de council area et de région de lieutenance, après avoir eu celui de district au sein de la région du Strathclyde (du 15 mai 1975 au 31 mars 1996) dont elle est le siège." },
  { titre: "Gnosticisme", texte: "Le gnosticisme est l’ensemble des mouvements religieux et philosophiques qui se développent au cours des IIe et IIIe siècles dans les limites de l’Empire romain, caractérisés par l’idée que la connaissance (en grec : gnôsis) des mystères de l’humanité, du divin et du monde, est possible et nécessaire au salut de l’âme" },
  { titre: "Gottfried Wilhelm Leibniz", texte: "Gottfried Wilhelm Leibniz, parfois francisé en Godefroid-Guillaume Leibniz, né à Leipzig le 1er juillet 1646 et mort à Hanovre le 14 novembre 1716, est un philosophe, scientifique, mathématicien, logicien, diplomate, juriste, historien, bibliothécaire et philologue allemand." },
  { titre: "Goulag", texte: "Le Goulag est l'organisme central gérant les camps de travail forcé en Union soviétique. La police politique placée à la tête du système pénal développa le Goulag comme instrument de terreur et d'expansion industrielle, visant en particulier à permettre l'exploitation des richesses naturelles de Sibérie." },
  { titre: "Grace Kelly", texte: "Grace Kelly, née le 12 novembre 1929 à Philadelphie et morte le 14 septembre 1982 à Monaco, est une actrice américaine, devenue princesse consort de Monaco par son mariage avec le prince Rainier III en 1956." },
  { titre: "Grand cachalot", texte: "Le Grand cachalot (Physeter macrocephalus ou P. catodon), communément appelé cachalot et parfois cachalot macrocéphale, est une espèce de cétacés à dents de la famille des physétéridés et unique représentant actuel de son genre, Physeter." },
  { titre: "Grand requin blanc", texte: "Le Grand requin blanc (Carcharodon carcharias) est une espèce de requins de la famille des Lamnidae et de l'ordre des Lamniformes (et non des Carcharhiniformes car il est dépourvu de paupières nictitantes)." },
  { titre: "Gregory Peck", texte: "Gregory Peck est un acteur américain, né le 15 avril 1916 à La Jolla dans le quartier de San Diego en Californie et mort le 12 juin 2003 à Los Angeles dans le même état." },
  { titre: "Greta Garbo", texte: "Greta Lovisa Gustafsson, dite Greta Garbo /ˈɡrêːta ˈɡǎrːbʊ/ est une actrice suédoise naturalisée américaine, née le 18 septembre 1905 à Stockholm et morte le 15 avril 1990 à New York." },
  { titre: "Grigori Raspoutine", texte: "Grigori Raspoutine, né le 21 janvier 1869 à Pokrovskoïe et assassiné le 30 décembre 1916 à Pétrograd, est un paysan russe devenu pèlerin itinérant, mystique populaire et guérisseur par la prière." },
  { titre: "Guam", texte: "Guam est une île située dans l'est-sud-est de la mer des Philippines, à la lisière de celle-ci avec l'océan Pacifique, et au sud-sud-ouest des Mariannes du Nord. Elle est la plus grande île (549 km2) de Micronésie et de l'archipel des îles Mariannes, dont elle est l'île la plus méridionale." },
  { titre: "Guatemala", texte: "Le Guatemala ou Guatémala, en forme longue la république du Guatemala ou république du Guatémala (en espagnol : República de Guatemala), est un pays d'Amérique centrale frontalier avec quatre pays : le Mexique, le Belize, le Salvador et le Honduras." },
  { titre: "Gueorgui Joukov", texte: "Gueorgui Konstantinovitch Joukov, né le 1er décembre 1896 et mort le 18 juin 1974, est un militaire et homme politique russe, puis soviétique. D'abord sous-officier dans l'Armée impériale russe pendant la Première Guerre mondiale, il devient officier de l'Armée rouge et du Parti lors de la guerre civile." },
  { titre: "Guerre de la Triple-Alliance", texte: "La guerre de la Triple-Alliance, au sens strict, a opposé du 1er mai 1865 (date du traité) au 1er mars 1870 une coalition composée de l'empire du Brésil, de l’Argentine et de l’Uruguay, au Paraguay." },
  { titre: "Guerre des Deux-Roses", texte: "La guerre des Deux-Roses est un ensemble d'affrontements, constituant globalement une guerre civile discontinue de 1455 à 1485, qui eut lieu en Angleterre entre la maison royale de Lancastre et la maison royale d'York, toutes deux branches cadettes de la maison Plantagenêt qui régnait alors." },
  { titre: "Guerre du Golfe", texte: "La guerre du Golfe est un conflit qui oppose, du 2 août 1990 au 28 février 1991, l'Irak à une coalition de 35 États dirigée par les États-Unis à la suite de l'invasion du Koweït par l'Irak." },
  { titre: "Guerre du Pacifique", texte: "La guerre du Pacifique comprend les campagnes menées à partir de 1941 dans la zone Asie-Pacifique, dans le cadre de l'affrontement entre les Alliés et l'empire du Japon. La politique expansionniste du Japon visait l'ensemble de la région." },
  { titre: "Guerre du Péloponnèse", texte: "La guerre du Péloponnèse est le conflit qui oppose la ligue de Délos, menée par Athènes, et la ligue du Péloponnèse, sous l'hégémonie de Sparte." },
  { titre: "Guerre franco-allemande de 1870", texte: "La guerre franco-allemande de 1870-1871 (en allemand Deutsch-Französische Krieg), parfois appelée guerre franco-prussienne, guerre de 1870, est un conflit qui oppose, du 19 juillet 1870 au 29 janvier 1871, la France à une coalition d'États allemands dirigée par la Prusse et comprenant les vingt-et-un autres États" },
  { titre: "Guerre froide", texte: "La guerre froide est la période de fortes tensions géopolitiques durant la seconde moitié du XXe siècle entre, d'une part, les États-Unis et leurs alliés constitutifs du bloc de l'Ouest et, d'autre part, l'Union des républiques socialistes soviétiques (URSS) et ses États satellites formant le bloc de l'Est." },
  { titre: "Guinée", texte: "La Guinée, en forme longue la république de Guinée, parfois appelée de manière informelle Guinée-Conakry du nom de sa capitale, est un pays d'Afrique de l'Ouest de 17,5 millions d'habitants (2025)." },
  { titre: "Guinée équatoriale", texte: "La Guinée équatoriale, en forme longue la république de Guinée équatoriale (en espagnol : Guinea Ecuatorial et República de Guinea Ecuatorial, en portugais : Guiné Equatorial et República da Guiné Equatorial) est un pays d'Afrique centrale." },
  { titre: "Guinée-Bissau", texte: "La Guinée-Bissau ou Guinée-Bissao, en forme longue la république de Guinée-Bissau ou république de Guinée-Bissao (en portugais : Guiné-Bissau et República da Guiné-Bissau), est un pays lusophone d'Afrique de l'Ouest." },
  { titre: "Gulf Stream", texte: "Le courant du Golfe, plus communément appelé Gulf Stream, est un courant océanique chaud, de surface, prenant sa source entre la Floride et les Bahamas, le long de la côte est des États-Unis et qui se disperse dans l'océan Atlantique quelque part au large de la Nouvelle-Écosse et de Terre-Neuve tout en se prolongeant" },
  { titre: "Hangeul", texte: "Le hangeul, aussi orthographié hangûl ou hangul en français, appelé josŏn'gŭl en Corée du Nord, est l’alphabet officiel du coréen, à la fois en Corée du Nord et en Corée du Sud." },
  { titre: "Hannah Arendt", texte: "Hannah Arendt, née Johanna Arendt le 14 octobre 1906 à Hanovre et morte le 4 décembre 1975 dans l'Upper West Side (New York), est une politologue, philosophe et journaliste allemande naturalisée américaine, connue pour ses travaux sur l’activité politique, le totalitarisme, la modernité et la philosophie de l'histoire." },
  { titre: "Hannibal Barca", texte: "Hannibal Barca (en phénicien : 𐤇𐤍𐤁𐤏𐤋, Hanni-ba'al est un nom théophore signifiant « qui a la faveur de Baal » et Barca, « foudre »), généralement appelé Annibal ou Hannibal, né en 247 av. J.-C. à Carthage (au nord-est de l'actuelle Tunis en Tunisie) et mort entre 183 av. J.-C. et 181 av. J.-C. en Bithynie (près" },
  { titre: "Hans Christian Andersen", texte: "Hans Christian Andersen, né le 2 avril 1805 à Odense et mort le 4 août 1875 à Copenhague, est un romancier, dramaturge, conteur et poète danois, célèbre pour ses nouvelles et ses « contes de fées »." },
  { titre: "Harriet Tubman", texte: "Harriet Tubman, née Araminta Ross vers juillet 1822 (ou entre 1820 et 1825, date incertaine qui varie selon les sources) et morte le 10 mars 1913 à Auburn (État de New York), est une militante antiesclavagiste, abolitionniste et antiraciste américaine, puis féministe et militante des droits civiques." },
  { titre: "Harry Houdini", texte: "Harry Houdini, nom de scène d'Ehrich Weisz, né le 24 mars 1874 à Budapest alors en Autriche-Hongrie et mort le 31 octobre 1926 à Détroit aux États-Unis, est un illusionniste américain d'origine hongroise." },
  { titre: "Harry S. Truman", texte: "Harry S. Truman, parfois appelé simplement Harry Truman, né le 8 mai 1884 à Lamar (Missouri) et mort le 26 décembre 1972 à Kansas City (Missouri), est un homme d'État américain." },
  { titre: "Hectare", texte: "L'hectare (symbole : ha) est une unité de mesure de superficie valant 100 ares. Un hectare équivaut à une surface carrée de 100 mètres de côté, soit 10 000 mètres carrés." },
  { titre: "Hélicoptère", texte: "Un hélicoptère est un aéronef dont la sustentation et la propulsion sont assurées par une voilure tournante, couramment appelée rotor, et entraînée par un ou plusieurs moteurs." },
  { titre: "Hergé", texte: "Hergé (de son vrai nom Georges Remi), né le 22 mai 1907 à Etterbeek et mort le 3 mars 1983 à Woluwe-Saint-Lambert (aujourd'hui dans la Région de Bruxelles-Capitale), est un auteur de bande dessinée belge, principalement connu pour Les Aventures de Tintin, l'une des bandes dessinées européennes les plus populaires du" },
  { titre: "Hermann Göring", texte: "Hermann Göring, ou Goering, né à Rosenheim le 12 janvier 1893 et mort à Nuremberg le 15 octobre 1946, est un militaire, homme politique et criminel de guerre allemand, dirigeant de premier plan du parti nazi et du gouvernement du Troisième Reich." },
  { titre: "Hermann Hesse", texte: "Hermann Hesse, né le 2 juillet 1877 à Calw dans le royaume de Wurtemberg (Empire allemand) et mort le 9 août 1962 à Montagnola (Suisse), est un romancier, poète, peintre et essayiste allemand puis, à partir de 1924, suisse." },
  { titre: "Hernán Cortés", texte: "Hernán Cortés (parfois écrit Cortès ou Cortez), de son nom complet Hernando Cortés de Monroy y Pizarro Altamirano, probablement né en 1485 à Medellín (Estrémadure) et mort le 2 décembre 1547 à Castilleja de la Cuesta, près de Séville, est un conquistador espagnol qui, en 1521-1522, s'est emparé de l'Empire aztèque au" },
  { titre: "Hmong", texte: "Les Hmong ou Mong sont un groupe ethnique d'Asie du Sud, présent dans le sud de la Chine (principalement dans la province du Guizhou), et dans le nord de tous les pays de l'Indochine au sein d'une région appelée « Zomia »." },
  { titre: "Hô Chi Minh-Ville", texte: "Hô Chi Minh-Ville ou Hồ Chí Minh-Ville /o.tʃi.min.vil/ ou /o.ʃi.min.vil/, encore souvent appelée Saïgon /saj.gɔ̃/, qui fut le nom officiel jusqu'en 1976, est la plus grande ville du Viêt Nam et son poumon économique, devant la capitale Hanoï." },
  { titre: "Holothurie", texte: "Les Holothuries (Holothuroidea) sont une classe d'animaux marins de l'embranchement des échinodermes au corps mou et oblong et possédant un cercle de tentacules autour de la bouche. Elles sont aussi appelées concombres de mer ou bêches de mer et possèdent une grande diversité de surnoms sur les différentes côtes." },
  { titre: "Homme de Denisova", texte: "L'Homme de Denisova, ou Dénisovien, est une espèce éteinte du genre Homo, identifiée par analyse génétique en mars 2010 à partir d'une phalange humaine fossile datée d'environ 41 000 ans, trouvée dans la grotte de Denisova, dans les montagnes de l'Altaï en Sibérie (Russie)." },
  { titre: "Homme de Néandertal", texte: "L'Homme de Néandertal (Homo neanderthalensis), ou Néandertalien, est une espèce éteinte du genre Homo, qui a vécu en Europe, au Moyen-Orient et en Asie centrale, jusqu'à environ 40 000 ans avant le présent." },
  { titre: "Homo sapiens", texte: "Homo sapiens, plus communément appelé « homme moderne », « homme », « Homme », « humain » ou « être humain », est une espèce de Primates originaire d'Afrique qui s'est aujourd'hui répandue et naturalisée sur l'ensemble de la Terre hormis l'Antarctique." },
  { titre: "Hydrochoerus hydrochaeris", texte: "Le Capybara (Hydrochoerus hydrochaeris), connu localement sous le nom de Cabiaï en Guyane, ou plus spécifiquement désigné sous les noms de Grand Hydrochère, Grand Cabiaï ou Grand Capybara, est une espèce de mammifères rongeurs hystricognathes de la famille des Caviidés." },
  { titre: "Ibn Battûta", texte: "Ibn Battûta, de son nom complet ʾAbu ʿAbd Allah Muḥammad Ibn ʿAbd Allah al-Lawātī aṭ-Ṭanjī Ibn Baṭṭūṭa, né le 24 février 1304 à Tanger et mort en 1368 (ou peut-être 1377) à Fès ou Marrakech, est un explorateur et voyageur d'origine berbère qui aurait parcouru plus de 120 000 km entre 1325 et 1349, de l'ancien" },
  { titre: "Ibn Khaldoun", texte: "Ibn Khaldoun (en arabe : ; nom complet : أبو زيد عبد الرحمن بن محمد بن خلدون الحضرمي (Abu Zayd 'Abd al-Rahmân Ibn Muhammad Ibn Khaldoun al-Hadrami), né le 27 mai 1332 à Tunis et mort le 17 mars 1406 au Caire, est un historien, économiste, géographe, démographe, précurseur de la sociologie et homme d'État arabe." },
  { titre: "Idi Amin Dada", texte: "Idi Amin Dada Oumee, né Idi Awo-Ongo Angoo vers 1925 à Koboko et mort le 16 août 2003 à Djeddah, est un militaire et homme d'État ougandais, exerçant un pouvoir absolu sur le pays entre le 25 janvier 1971 et le 11 avril 1979, en tant que président à vie." },
  { titre: "Iekaterinbourg", texte: "Iekaterinbourg ou Ekaterinbourg (/je.ka.t̪e.ʁin̪.buʁg/ ou /(j)e.ka.t̪e.ʁɛ̃.buʁ/, en russe : Екатеринбург /jɪ.kə.tʲɪ.rʲɪn.burk/, d'après l'impératrice Catherine Ire), appelée Sverdlovsk de 1924 à 1991 (à l'époque soviétique), est par sa population la quatrième ville de Russie et le centre administratif du district" },
  { titre: "Ignace de Loyola", texte: "Ignace de Loyola (Ignacio Loiolakoa en basque, Íñigo López de Loyola en espagnol), né en 1491 à Loiola et mort le 31 juillet 1556 à Rome, est un prêtre et théologien basque-espagnol." },
  { titre: "Igor Stravinsky", texte: "Igor Fiodorovitch Stravinsky, né le 17 juin 1882 à Oranienbaum en Russie et mort le 6 avril 1971 à New York aux États-Unis, est un compositeur, chef d'orchestre et pianiste russe, naturalisé français en 1934 puis américain en 1945, de musique moderne." },
  { titre: "Illinois", texte: "L'Illinois est un État du Midwest des États-Unis. Sa capitale est Springfield, mais la plus grande ville est Chicago, troisième agglomération des États-Unis, qui concentre à elle seule plus du cinquième de la population totale de l'État (65 % avec l'agglomération)." },
  { titre: "Inceste", texte: "L’inceste est un rapport sexuel entre apparentés, très généralement un viol ou une agression sexuelle imposés par des individus détenant une autorité familiale à des individus plus jeunes. Il fait l'objet d'interdits variables selon les époques, les pays, la nature des liens de parenté, l'âge, et les lois en vigueur." },
  { titre: "Inde", texte: "L'Inde (en hindi : भारत (Bhārat), en anglais : India), en forme longue la république de l'Inde (en hindi : भारत गणराज्य (Bhārat Gaṇarājya), en anglais : Republic of India), également appelée le Bharat dans sa constitution, est un pays d'Asie du Sud occupant la majeure partie du sous-continent indien." },
  { titre: "Indira Gandhi", texte: "Indira Priyadarshini Gandhi, née Nehru le 19 novembre 1917 à Prayagraj (provinces unies d'Agra et d'Oudh, Raj britannique), et morte assassinée le 31 octobre 1984 à New Delhi (Delhi), est une femme d'État indienne." },
  { titre: "Indochine", texte: "L'Indochine, péninsule indochinoise ou encore Asie du Sud-Est continentale est une péninsule du continent asiatique située au sud de la Chine et à l'est de l'Inde. Elle est entourée à l'ouest par le golfe du Bengale, la mer d'Andaman et le détroit de Malacca et à l'est par la mer de Chine méridionale." },
  { titre: "Indonésie", texte: "L'Indonésie, en forme longue la république d'Indonésie (en indonésien Indonesia et Republik Indonesia) est un pays transcontinental situé principalement en Asie du Sud-Est, avec certaines parties de son territoire s’étendant en Océanie." },
  { titre: "Intersexuation", texte: "L'intersexuation, aussi appelée intersexualité, se définit selon l’ONU comme « une manière de décrire les caractères sexuels biologiques d’un individu, notamment ses organes génitaux, ses gonades, ses taux d’hormones et ses chromosomes » lorsque ces caractères ne correspondent pas aux définitions traditionnelles du" },
  { titre: "Invasions barbares", texte: "Les invasions barbares, ou grandes migrations, sont un ensemble de migrations de peuples dans l'Antiquité tardive, principalement en Europe, commençant par l’arrivée des Huns en Europe centrale et orientale aux environs de 375, et finissant par celles des Lombards en Italie en 568 et des Slaves dans l’Empire romain" },
  { titre: "Italien", texte: "L'italien (en italien : italiano) est une langue indo-européenne de la famille des langues romanes. Il existe un très grand nombre de dialectes italo-romans." },
  { titre: "Ivy League", texte: "La Ivy League est un groupe de huit universités privées du Nord-Est des États-Unis. Figurant parmi les universités les plus anciennes du pays, sept d'entre elles ayant été fondées par les Britanniques avant l'indépendance, elles ont pour point commun de figurer parmi les plus prestigieuses du pays et du monde." },
  { titre: "Jack London", texte: "Jack London, né John Griffith Chaney le 12 janvier 1876 à San Francisco et mort le 22 novembre 1916 à Glen Ellen, Californie, est un écrivain américain dont les thèmes de prédilection sont l'aventure et la nature sauvage." },
  { titre: "Jazz", texte: "Le jazz est un genre musical originaire du Sud des États-Unis, créé à la fin du XIXe siècle et au début du XXe siècle au sein des communautés afro-américaines." },
  { titre: "Jean", texte: "Jean (grec : Ἰωάννης ; araméen ܝܘܚܢܢ ܫܠܝܚܐ, Yohanan Shliha, Jean l'apôtre ; hébreu : יהוחנן, Yehohānan, arabe : يوحنا (christianisme) Yohana, يحيى (islam) Yahia), est un Juif du Ier siècle qui fait partie des Douze Apôtres de Jésus." },
  { titre: "Jean Calvin", texte: "Jean Calvin, né Jehan Cauvin le 10 juillet 1509 à Noyon et mort le 27 mai 1564 à Genève, est un théologien français, un important réformateur, et un pasteur emblématique de la Réforme protestante du XVIe siècle, notamment pour son apport à la doctrine dite du calvinisme." },
  { titre: "Jean Cocteau", texte: "Jean Cocteau, né le 5 juillet 1889 à Maisons-Laffitte (Seine-et-Oise) et mort le 11 octobre 1963 dans sa maison à Milly-la-Forêt (Seine-et-Oise), est un poète, peintre, dessinateur, dramaturge et cinéaste français." },
  { titre: "Jean Giraud", texte: "Jean Giraud, connu sous son vrai nom et sous les pseudonymes Mœbius (/møbjys/) et Gir, né le 8 mai 1938 à Nogent-sur-Marne et mort le 10 mars 2012 à Montrouge, est un auteur de bande dessinée et illustrateur français." },
  { titre: "Jean-Paul Sartre", texte: "Jean-Paul Sartre, né le 21 juin 1905 dans le 16e arrondissement de Paris et mort le 15 avril 1980 dans le 14e arrondissement, est un philosophe, écrivain et journaliste français." },
  { titre: "Jean-Sébastien Bach", texte: "Jean-Sébastien Bach (en allemand : Johann Sebastian Bach) est un compositeur et musicien allemand né le 21 mars 1685 (31 mars dans le calendrier grégorien) à Eisenach dans le duché de Saxe-Eisenach et mort le 28 juillet 1750 à Leipzig." },
  { titre: "John Adams", texte: "John Adams, né le 30 octobre 1735 à Braintree (province de la baie-du-Massachusetts) et mort le 4 juillet 1826 à Quincy (Massachusetts), est un avocat, diplomate et homme d'État américain." },
  { titre: "Joseph Conrad", texte: "Joseph Conrad, de son nom d'origine (en polonais) Józef Teodor Konrad Korzeniowski, né le 3 décembre 1857 à Berditchev (actuelle Ukraine, alors dans l'Empire russe), et mort le 3 août 1924 à Bishopsbourne (Angleterre), est un écrivain polonais et britannique d'expression anglaise." },
  { titre: "Joseph Goebbels", texte: "Joseph Goebbels, né le 29 octobre 1897 à Rheydt et mort par suicide le 1er mai 1945 à Berlin, est un homme d'État allemand et criminel nazi. Proche d'Adolf Hitler, il fut, avec Hermann Göring et Heinrich Himmler, l'un des dirigeants les plus puissants et influents du Troisième Reich." },
  { titre: "Jupiter", texte: "Jupiter est la cinquième planète du Système solaire par ordre d'éloignement au Soleil, et la plus grande par la taille et la masse devant Saturne, qui est comme elle une planète géante gazeuse." },
  { titre: "Kaaba", texte: "La Kaaba, Ka'ba ou Ka'aba, est un édifice recouvert d'une étoffe de soie noire, la kiswa, presque au centre de la cour de la grande mosquée de la Mecque (al-Masjid al-haram). Elle est le lieu le plus sacré de l'islam, et elle est entourée de différents édicules." },
  { titre: "Kali", texte: "Kali (en sanskrit काली (Kālī) ou कालिका (Kālikā)) est, dans l'hindouisme, la déesse de la préservation, de la transformation et de la destruction. Elle ne doit pas être confondue avec le démon \"Kali\" qui préside au Kali Yuga." },
  { titre: "Kareem Abdul-Jabbar", texte: "Kareem Abdul-Jabbar, né Ferdinand Lewis Alcindor (ou Lew Alcindor) le 16 avril 1947 à New York, est un joueur de basket-ball de National Basketball Association (NBA)." },
  { titre: "Karen Blixen", texte: "Karen Blixen, ex-baronne Karen von Blixen-Finecke, du nom de son ex-époux le baron suédois Bror von Blixen-Finecke, née Karen Christentze Dinesen le 17 avril 1885 à Rungstedlund dans la commune de Hørsholm et décédée le 7 septembre 1962 à Rungstedlund, est une entrepreneuse au Kenya et une femme de lettres danoise." },
  { titre: "Karl Marx", texte: "Karl Marx, né le 5 mai 1818 à Trèves dans le grand-duché du Bas-Rhin et mort le 14 mars 1883 à Londres, est un philosophe, économiste, historien, sociologue, journaliste, théoricien de la révolution, du socialisme, du socialisme libertaire et du communisme, un internationaliste et idéologue prussien." },
  { titre: "Karma", texte: "Karma ou karman en sanskrit ; de la racine verbale kṛ, signifie « acte » ), ou kamma en pali, est l'action sous toutes ses formes, puis dans un sens plus religieux l'action rituelle. C'est aussi une notion désignant communément le cycle des causes et des conséquences liées à l'existence des êtres sensibles." },
  { titre: "Kazan", texte: "Kazan est la sixième plus grande ville de Russie, capitale de la république du Tatarstan. Elle forme sa propre subdivision en tant qu'okroug urbain, et elle est divisée en sept arrondissements. Située sur le cours moyen de la Volga, elle se situe dans le centre-est de la partie européenne du pays." },
  { titre: "Kenya", texte: "Le Kenya ou Kénya, en forme longue la république du Kenya ou république du Kénya (en Gĩkũyũ Bũrũri wa Kĩrĩnyaga en swahili : Kenya et Jamhuri ya Kenya, en anglais : Kenya et Republic of Kenya), est un pays d’Afrique de l'Est, limitrophe du Soudan du Sud au nord-ouest, de l’Éthiopie au nord, de la Somalie à l’est, de" },
  { titre: "Kiev", texte: "Kiev ou Kyïv est la capitale et la ville la plus peuplée d'Ukraine (3 000 000 habitants en 2025). Elle est située au centre-nord du pays sur les rives du fleuve Dniepr." },
  { titre: "Kilimandjaro", texte: "Le Kilimandjaro ou Kilimanjaro est une montagne située dans le Nord-Est de la Tanzanie et composée de trois volcans : le Shira à l'ouest, culminant à 3 962 mètres d'altitude, le Mawenzi à l'est, s'élevant à 5 149 mètres d'altitude, et le Kibo, le plus récent géologiquement, situé entre les deux autres et dont le pic" },
  { titre: "Kinshasa", texte: "Kinshasa, appelée Léopoldville de 1881 à 1966, est la capitale et la plus grande ville de la république démocratique du Congo (RDC) et l'une des plus peuplées d'Afrique ; elle s’étend sur 9 965 km2." },
  { titre: "Kirghizistan", texte: "Le Kirghizistan, Kirghizstan ou la Kirghizie, en forme longue la République kirghize, est un pays enclavé d'Asie centrale, situé dans les chaînes de montagnes du Tian Shan et du Pamir. Bichkek est la capitale et la plus grande ville du pays." },
  { titre: "Kiribati", texte: "Les Kiribati, en forme longue la république de Kiribati ou la république des Kiribati (en gilbertin : Kiribati ; en anglais : Republic of Kiribati), anciennement connues sous le nom des îles Gilbert, sont un État archipélagique en Océanie, composé de trois archipels de l'océan Pacifique : les îles Gilbert proprement" },
  { titre: "Lac Titicaca", texte: "Le lac Titicaca, situé dans la cordillère des Andes, est traversé par la frontière entre la Bolivie et le Pérou. C'est le plus grand lac d’eau douce d'Amérique du Sud en volume d'eau et en longueur, mais pas en superficie (le lac Maracaibo couvre une superficie de plus de 13 000 km2)." },
  { titre: "Lao Tseu", texte: "Lao Tseu ou Lao-Tseu, Laozi ou Lao Zi, plus communément appelé en Chine Tàishàng lǎojūn, de son vrai nom Li Er, aurait été un sage chinois et, selon la tradition, un contemporain de Confucius (milieu du VIe siècle av. J.-C. – milieu du Ve siècle av. J.-C., fin de la période des Printemps et Automnes)." },
  { titre: "Latin", texte: "Le latin (en latin : Lingua latīna ou Latīna lingua) est une langue indo-européenne de la famille des langues italiques, parlée à l'origine par les Latins dans le Latium de la Rome antique. Le latin, ainsi que les langues romanes (dites parfois néo-latines), sont la seule branche des langues italiques à avoir survécu." },
  { titre: "Laurel et Hardy", texte: "Laurel et Hardy est le nom d'un duo comique constitué en 1927 et formé par les acteurs Stan Laurel et Oliver Hardy. Durant une carrière de près de 25 ans et de plus de 100 films, ce duo atteindra une notoriété telle qu’il reste sans doute à ce jour le tandem le plus célèbre de toute l’histoire du cinéma." },
  { titre: "Lauren Bacall", texte: "Betty Joan Perske, dite Lauren Bacall, est une actrice américaine, née le 16 septembre 1924 à New York, où elle est morte le 12 août 2014, connue pour sa voix grave et son regard sensuel pour lequel elle est surnommée « The Look » (« Le regard »)." },
  { titre: "Laurence Olivier", texte: "Laurence Olivier, né le 22 mai 1907 à Dorking dans le Surrey et mort le 11 juillet 1989 à Steyning (Sussex de l'Ouest), est un comédien, metteur en scène, directeur de théâtre, réalisateur et scénariste britannique qui, avec ses contemporains Ralph Richardson et John Gielgud, faisait partie du trio d'acteurs masculins" },
  { titre: "Laurent de Médicis", texte: "Laurent de Médicis (en italien : Lorenzo di Piero de' Medici : « Laurent, fils de Pierre de Médicis »), surnommé Laurent le Magnifique (Lorenzo il Magnifico), né le 1er janvier 1449 à Florence et mort dans cette même ville le 8 avril 1492, est un homme d'État italien et le chef du gouvernement de la République" },
  { titre: "Le Caravage", texte: "Michelangelo Merisi da Caravaggio, francisé Caravage ou le Caravage, est un peintre italien, né le 29 septembre 1571 à Milan et mort le 18 juillet 1610 à Porto Ercole." },
  { titre: "Le Corbusier", texte: "Charles-Édouard Jeanneret, dit Le Corbusier, est un architecte, urbaniste, designer, peintre, sculpteur, homme de lettres, poète et théoricien suisse naturalisé français en 1930, né le 6 octobre 1887 à La Chaux-de-Fonds en Suisse et mort le 27 août 1965 à Roquebrune-Cap-Martin en France." },
  { titre: "Le Jardin des délices", texte: "Le Jardin des délices est une peinture à l'huile sur bois du peintre néerlandais Jérôme Bosch, appartenant à la période des primitifs flamands. L'œuvre est structurée en triptyque, format souvent utilisé par les peintres du début du XVe siècle jusqu'au début du XVIIe siècle dans la partie septentrionale de l'Europe." },
  { titre: "Le Lac des cygnes", texte: "Le Lac des cygnes, op. 20 est un ballet en quatre actes sur une musique de Piotr Ilitch Tchaïkovski et un livret de Vladimir Begitchev inspiré d'une légende allemande. Il est composé entre 1875 et 1876." },
  { titre: "Le Meilleur des mondes", texte: "Le Meilleur des mondes (titre original : Brave New World) est un roman d'anticipation dystopique, écrit en 1931 par Aldous Huxley. Il paraît en 1932. Huxley le rédige en quatre mois, à Sanary-sur-Mer (Var)." },
  { titre: "Le Monde", texte: "Le Monde est un journal français fondé par Hubert Beuve-Méry en 1944. Se voulant journal « de référence », il est régulièrement considéré comme tel, y compris à l'étranger." },
  { titre: "Le Monde de Narnia", texte: "Le Monde de Narnia (en anglais : The Chronicles of Narnia) est une œuvre littéraire en sept tomes de l'écrivain britannique C. S. Lewis. Elle est considérée comme un classique de la littérature anglophone pour enfants et est l'œuvre la plus connue de l'auteur." },
  { titre: "LeBron James", texte: "LeBron Raymone James, né le 30 décembre 1984 à Akron (Ohio), est un joueur professionnel américain de basket-ball évoluant actuellement aux 76ers de Philadelphie en National Basketball Association (NBA)." },
  { titre: "Léon Tolstoï", texte: "Léon Tolstoï, nom francisé de Lev Nikolaïevitch Tolstoï (en russe : Лев Никола́евич Толсто́й, ; orthographe russe avant 1918 Левъ Николаевичъ Толстой), né le 28 août 1828 (9 septembre 1828 dans le calendrier grégorien) à Iasnaïa Poliana, et mort le 7 novembre 1910 (20 novembre 1910 dans le calendrier grégorien) à" },
  { titre: "Léon Trotski", texte: "Léon Trotski, de son vrai nom Lev Davidovitch Bronstein, né le 26 octobre 1879 (7 novembre dans le calendrier grégorien) à Ianovka, une ville ukrainienne de l'Empire russe, et mort assassiné le 21 août 1940 à Mexico, est un idéologue, révolutionnaire bolchévique, théoricien politique communiste et homme politique" },
  { titre: "Léonard de Vinci", texte: "Léonard de Vinci (italien : Leonardo di ser Piero da Vinci, dit Leonardo da Vinci), né le 14 avril 1452 du calendrier actuel — le 15 avril 1452, date de l'époque — à Vinci (Toscane) et mort le 2 mai 1519 à Amboise (Touraine), est un peintre polymathe toscan de la Renaissance italienne, simultanément artiste," },
  { titre: "Léonid Brejnev", texte: "Léonid Ilitch Brejnev, né le 6 décembre 1906 (19 décembre dans le calendrier grégorien) à Kamenskoïe et mort le 10 novembre 1982 à Moscou, est un homme d'État soviétique d'origine ukrainienne, secrétaire général du Parti communiste de l'Union soviétique, et donc principal dirigeant de l'URSS de 1964 à 1982." },
  { titre: "Léopold II", texte: "Léopold II, de son nom Léopold Louis-Philippe Marie Victor de Saxe-Cobourg-Gotha, né le 9 avril 1835 au palais royal de Bruxelles (en Belgique) et mort le 17 décembre 1909 au château de Laeken (dans le même pays), est le deuxième roi des Belges (du 17 décembre 1865 au 17 décembre 1909), prince de Belgique, duc de" },
  { titre: "Léopold Sédar Senghor", texte: "Léopold Sédar Senghor, né le 9 octobre 1906 à Joal (Sénégal, AOF) et mort le 20 décembre 2001 à Verson, est un homme d'État sénégalais, poète, écrivain et premier président de la république du Sénégal." },
  { titre: "Les Simpson", texte: "Les Simpson (The Simpsons) sont une série télévisée d'animation américaine créée par Matt Groening et diffusée pour la première fois à partir du 17 décembre 1989 sur le réseau Fox. Depuis le 24 mars 2020, la série est disponible sur Disney+." },
  { titre: "Libertarianisme", texte: "Le libertarianisme ou libertarisme est une idéologie et philosophie politique développée aux États-Unis autour d'un « groupe de théories qui donnent une priorité stricte à la liberté et au droit naturel, mettant l'accent sur la liberté de choix, l'individualisme et l'association volontaire sur d'autres valeurs telles" },
  { titre: "Lièvre", texte: "Les Lièvres (Lepus) sont un genre de petits mammifères de la famille des Léporidés. Ce sont des animaux sauvages herbivores, proches des lapins. Il existe une trentaine d'espèces de lièvres dans le monde qui diffèrent entre elles par leur taille, leur coloris ou leur mode de vie." },
  { titre: "Linux", texte: "Linux (parfois nommé GNU/Linux) est un système d'exploitation open source de type Unix, basé sur le noyau Linux créé en 1991 par Linus Torvalds. De nombreuses distributions Linux ont depuis vu le jour et constituent un important vecteur de popularisation du mouvement du logiciel libre." },
  { titre: "Lion", texte: "Le Lion (Panthera leo) est une espèce de mammifères carnivores de la famille des Félidés. La femelle du lion est la lionne, son petit est le lionceau." },
  { titre: "Louis le Pieux", texte: "Louis Ier dit « le Pieux » ou « le Débonnaire », fils de Charlemagne et de Hildegarde de Vintzgau, né en 778 à Cassinogilum (localisation incertaine, soit Casseuil près de Bordeaux, Chasseneuil-du-Poitou dans la Vienne ou encore Casseneuil en Lot-et-Garonne) et mort le 20 juin 840 à Ingelheim, près de Mayence, est roi" },
  { titre: "Louis XI", texte: "Louis XI, né le 3 juillet 1423 à Bourges et mort le 30 août 1483 au château de Plessis-lèz-Tours, est roi de France de 1461 à sa mort, sixième roi de la branche dite de Valois (Valois directs) de la dynastie capétienne." },
  { titre: "Louis XIV", texte: "Louis XIV, dit « le Grand » ou « le Roi-Soleil », né le 5 septembre 1638 au château Neuf de Saint-Germain-en-Laye et mort le 1er septembre 1715 au château de Versailles, est un roi de France et de Navarre." },
  { titre: "Louis XV", texte: "Louis XV, dit « le Bien-Aimé », né le 15 février 1710 à Versailles et mort le 10 mai 1774 dans la même ville, est un roi de France et de Navarre. Membre de la maison de Bourbon, il règne sur le royaume de France du 1er septembre 1715 à sa mort." },
  { titre: "Louis XVI", texte: "Louis XVI, né le 23 août 1754 au château de Versailles sous le nom de Louis-Auguste de France et mort guillotiné le 21 janvier 1793 à Paris, est roi de France et de Navarre du 10 mai 1774 au 14 septembre 1791, puis roi des Français du 14 septembre 1791 au 21 septembre 1792." },
  { titre: "Ludwig van Beethoven", texte: "Ludwig van Beethoven est un compositeur, pianiste et chef d'orchestre allemand né le 15 ou le 16 décembre 1770 à Bonn et mort le 26 mars 1827 à Vienne." },
  { titre: "Ludwig Wittgenstein", texte: "Ludwig Josef Johann Wittgenstein, né à Vienne en Autriche le 26 avril 1889 et mort à Cambridge au Royaume-Uni le 29 avril 1951, est un philosophe, mathématicien, ingénieur, pédagogue et architecte de nationalité autrichienne, puis, à partir de 1939, britannique, ayant exploré de manière décisive certains domaines" },
  { titre: "Luis Buñuel", texte: "Luis Buñuel Portolés, né le 22 février 1900 à Calanda (Aragon, Espagne) et mort le 29 juillet 1983 à Mexico, est un réalisateur, scénariste et acteur espagnol naturalisé mexicain." },
  { titre: "Luxembourg", texte: "Le Luxembourg, en forme longue le Grand-Duché de Luxembourg ou grand-duché de Luxembourg (en luxembourgeois : Lëtzebuerg et Groussherzogtum Lëtzebuerg, en allemand : Luxemburg et Großherzogtum Luxemburg) est, comme la Suisse, un pays sans littoral de l'Europe de l'Ouest." },
  { titre: "Lyndon B. Johnson", texte: "Lyndon Baines Johnson, généralement appelé Lyndon B. Johnson et également connu sous ses initiales LBJ, né le 27 août 1908 à Stonewall (Texas) et mort le 22 janvier 1973 à Johnson City (Texas), était un homme d'État américain." },
  { titre: "Lyon", texte: "Lyon est une commune du centre-est de la France, au confluent du Rhône et de la Saône. Elle est, en 2023, la troisième commune de France la plus peuplée, derrière Marseille et la capitale Paris, mais son unité urbaine devance celle de Marseille." },
  { titre: "Macao", texte: "Macao, officiellement la région administrative spéciale de Macao de la république populaire de Chine, est une région administrative spéciale (RAS) de la république populaire de Chine depuis le 20 décembre 1999." },
  { titre: "Macédoine du Nord", texte: "La Macédoine du Nord (en macédonien : Северна Македонија (Severna Makedonija) ; en albanais : Maqedonia e Veriut), en forme longue la république de Macédoine du Nord (en macédonien : Република Северна Македонија (Republika Severna Makedonija) ; en albanais : Republika e Maqedonisë së Veriut), est un pays d'Europe du" },
  { titre: "Madagascar", texte: "Madagascar (en malgache : Madagasikara), en forme longue République de Madagascar (en malgache : Repoblikan'i Madagasikara), est un État insulaire situé dans l'océan Indien et géographiquement rattaché au continent africain, dont il est séparé par le canal du Mozambique." },
  { titre: "Madère", texte: "Madère (en portugais : Madeira) est un archipel volcanique portugais situé dans l'océan Atlantique à 800 km de l'extrême sud-ouest du continent européen, le cap de Sagres (pt), 973 km de la capitale du Portugal, Lisbonne, et à 640 km au nord-nord-ouest du cap Juby dans la province de Tarfaya au Maroc." },
  { titre: "Madrid", texte: "Madrid est la capitale et la plus grande ville d'Espagne. Située dans la partie centrale du royaume, elle est également la capitale et la ville la plus peuplée de la communauté de Madrid." },
  { titre: "Mah-jong", texte: "Le mah-jong est un jeu de société d'origine chinoise qui se joue à quatre, avec des pièces appelées tuiles dans les principales langues européennes, pái, « tablettes », en chinois." },
  { titre: "Maïs", texte: "Le maïs (Zea mays subsp. mays (autonyme)), couramment appelé blé d’Inde au Canada, est une plante herbacée tropicale annuelle de la famille des Poacées (graminées), largement cultivée comme céréale pour ses grains riches en amidon, mais aussi comme plante fourragère." },
  { titre: "Malaisie", texte: "La Malaisie (en malaisien : Malaysia) est un État d'Asie du Sud-Est, constitué de la Malaisie péninsulaire ou Malaisie occidentale (majeure partie de la péninsule Malaise) et de la Malaisie orientale (nord de Bornéo)." },
  { titre: "Malawi", texte: "Le Malawi, en forme longue la république du Malawi (en anglais Republic of Malawi, en chewa Malaŵi ; anciennement appelé Nyassaland jusqu'en 1964), est un État situé en Afrique australe, entre le Mozambique, la Zambie et la Tanzanie." },
  { titre: "Maldives", texte: "Les Maldives, en forme longue la république des Maldives (en maldivien : ދިވެހިރާއްޖޭގެ ޖުމްހޫރިއްޔާ, Dhivehi Raa'jeyge Jumhooriyya), sont un pays d'Asie du Sud composé de 1 199 îles, dont 202 habitées, situé au sud-ouest du sous-continent indien." },
  { titre: "Mali", texte: "Le Mali, en forme longue la république du Mali, est un État d'Afrique de l'Ouest, frontalier de la Mauritanie au nord-ouest, de l'Algérie au nord-est, du Niger à l'est, du Burkina Faso au sud-est, de la Côte d'Ivoire au sud, de la Guinée au sud-ouest et du Sénégal à l'ouest." },
  { titre: "Malte", texte: "Malte, en forme longue la république de Malte, est un État insulaire d'Europe du Sud situé en mer Méditerranée, entre la Sicile et la Tunisie en Afrique du Nord. Il est constitué d'un archipel situé à 80 kilomètres au sud de l'Italie, 284 kilomètres à l'est de la Tunisie et 333 kilomètres au nord de la Libye." },
  { titre: "Marathon", texte: "Le marathon est une épreuve sportive individuelle de course à pied qui se dispute généralement sur route sur une distance de 42,195 kilomètres." },
  { titre: "Marc Chagall", texte: "Marc Chagall, né Moïche Zakharovitch Chagalov, est un peintre et graveur né le 7 juillet 1887 à Liozna dans la voblast de Vitebsk en Biélorussie (alors Empire russe), naturalisé français en 1937 et mort le 28 mars 1985 à Saint-Paul-de-Vence où il est enterré." },
  { titre: "Marcel Duchamp", texte: "Marcel Duchamp, né le 28 juillet 1887 à Blainville-Crevon et mort le 2 octobre 1968 à Neuilly-sur-Seine, est un peintre, plasticien et homme de lettres français, naturalisé américain en 1955." },
  { titre: "Marcel Marceau", texte: "Marcel Marceau, dit le mime Marceau, nom de scène de Marcel Mangel, né le 22 mars 1923 à Strasbourg et mort le 22 septembre 2007 à Cahors, est un mime et acteur français. Il a connu une célébrité internationale avec son personnage silencieux de Bip, créé en 1947." },
  { titre: "Marcel Proust", texte: "Marcel Proust, né le 10 juillet 1871 à Paris et mort le 18 novembre 1922 dans la même ville, est un écrivain français, dont l'œuvre principale est la suite romanesque intitulée À la recherche du temps perdu, publiée entre 1913 et 1927." },
  { titre: "Marcello Mastroianni", texte: "Marcello Mastroianni, né le 28 septembre 1924 à Fontana Liri (Latium) et mort le 19 décembre 1996 à Paris 6e (Île-de-France), est un acteur italien." },
  { titre: "Marco Polo", texte: "Marco Polo ou Marc Pol (né le 15 septembre 1254 à Venise et mort probablement en janvier 1324 à Venise) est un célèbre marchand, explorateur, diplomate, ethnologue et écrivain vénitien, de la période des préludes des grandes découvertes, devenu mondialement célèbre pour une des plus anciennes descriptions qu'il a" },
  { titre: "Marée", texte: "La marée est la variation de la hauteur du niveau des mers et des océans, causée par la combinaison des forces gravitationnelles dues à la Lune et au Soleil et des forces d'inertie dues à la révolution de la Terre autour du centre de masse du couple Terre-Lune et de celui du couple Terre-Soleil, le tout conjugué à la" },
  { titre: "Margaret Atwood", texte: "Margaret Atwood, née le 18 novembre 1939 à Ottawa, est une romancière, poète et critique littéraire canadienne. Elle est l'une des écrivaines canadiennes les plus connues, en particulier pour son roman La Servante écarlate (The Handmaid's Tale)." },
  { titre: "Margaret Smith Court", texte: "Margaret Smith, née le 16 juillet 1942 à Albury (Nouvelle-Galles du Sud), également connue sous son nom de femme mariée Margaret Court ou Margaret Smith Court, est une joueuse de tennis australienne, considérée comme l'une des plus grandes de l'histoire de ce sport." },
  { titre: "Margaret Thatcher", texte: "Margaret Thatcher, baronne Thatcher, née Margaret Roberts le 13 octobre 1925 à Grantham (Lincolnshire) et morte le 8 avril 2013 à Londres, est une femme d'État britannique, Première ministre du Royaume-Uni du 4 mai 1979 au 28 novembre 1990." },
  { titre: "Maria Montessori", texte: "Maria Montessori, née le 31 août 1870 à Chiaravalle près d'Ancône (Italie) et décédée le 6 mai 1952 à Noordwijk aan Zee (Pays-Bas), est une médecin et pédagogue italienne." },
  { titre: "Mariage", texte: "Le mariage est une union conjugale contractuelle et/ou rituelle, à durée illimitée, déterminée ou indéterminée, reconnue et encadrée par une institution juridique ou religieuse qui en détermine les modalités." },
  { titre: "Marmotte", texte: "Les marmottes (Marmota) sont un genre de rongeurs fouisseurs, de la famille des Sciuridés (sous-famille des Xérinés, les écureuils terrestres)." },
  { titre: "Mars", texte: "Mars est la quatrième planète du Système solaire par ordre croissant de la distance au Soleil et la deuxième par ordre croissant de la taille et de la masse." },
  { titre: "Marsupialia", texte: "Les Marsupiaux (Marsupialia), du grec ancien μαρσίπιον / marsípion « petit sac »), sont une infra-classe de mammifères thériens caractérisés par le fait que leurs juvéniles se développent dans un état larvaire au sein de ce qu'on appelle un marsupium." },
  { titre: "Max Ernst", texte: "Maximilian Maria Ernst, dit Max Ernst, né le 2 avril 1891 à Brühl dans l'Empire allemand et mort le 1er avril 1976 à Paris, est un peintre et sculpteur germano-américano-français dont l'œuvre se rattache aux mouvements dadaïste et surréaliste." },
  { titre: "Max Weber", texte: "Max Weber, né le 21 avril 1864 à Erfurt, alors dans le royaume de Prusse, et mort le 14 juin 1920 à Munich, est un économiste et sociologue allemand originellement formé en droit." },
  { titre: "Maximilien de Robespierre", texte: "Maximilien de Robespierre, ou Maximilien Robespierre, est un avocat et homme politique français né le 6 mai 1758 à Arras (Artois, aujourd'hui Pas-de-Calais) et mort guillotiné le 28 juillet 1794 à Paris, place de la Révolution (actuelle place de la Concorde)." },
  { titre: "Maximilien Ier", texte: "Maximilien d'Autriche ou Maximilien Ier, né le 22 mars 1459 à Wiener Neustadt et mort le 12 janvier 1519 au château de Wels, est un membre de la maison de Habsbourg, fils de l'empereur Frédéric III." },
  { titre: "Mehmed II", texte: "Mehmed II, né le 30 mars 1432 à Edirne et mort assassiné le 3 mai 1481 à Tekfu Çayiri, près de Gebze, est le septième sultan de l'Empire ottoman, d'abord entre 1444 et 1446 puis de nouveau à partir de 1451, et l'un des plus célèbres." },
  { titre: "Mer Méditerranée", texte: "La mer Méditerranée est une mer intercontinentale presque entièrement fermée, bordée par les côtes d'Europe du Sud, d’Afrique du Nord et d’Asie de l'Ouest, depuis le détroit de Gibraltar à l'ouest, à l'entrée de la mer de Marmara (Dardanelles) à l'est et au canal de Suez au sud-est." },
  { titre: "Mer Noire", texte: "La mer Noire est située entre l’Europe, le Caucase et l’Anatolie. Principalement alimentée par le Danube, le Dniepr et le Don, elle est issue de la fermeture d’une mer océanique ancienne, l'océan ou mer Paratéthys." },
  { titre: "Mer Rouge", texte: "La mer Rouge est une mer intercontinentale bordière de l'océan Indien et située entre l'Afrique du Nord et l'Asie de l'Ouest. Elle a une superficie d'environ 450 000 km2." },
  { titre: "Métaphysique", texte: "La métaphysique est la branche de la philosophie qui étudie la nature fondamentale de la réalité. Elle s'intéresse à des concepts tels que l'être et l'identité, l'espace et le temps, la causalité, la nécessité et la possibilité." },
  { titre: "Miyamoto Musashi", texte: "Miyamoto Musashi, de son vrai nom Shinmen Musashi, né en 1584 dans la province de Mimasaka et mort le 19 mai 1645, est un maître bushi, calligraphe, peintre et philosophe japonais." },
  { titre: "Mobutu Sese Seko", texte: "Mobutu Sese Seko Kuku Ngbendu wa Za Banga, couramment abrégé en Mobutu Sese Seko, ou tout simplement Mobutu né Joseph-Désiré Mobutu le 14 octobre 1930 à Lisala (Congo belge) et mort le 7 septembre 1997 à Rabat (Maroc), est un homme d'État, militaire et dictateur zaïrois, ayant gouverné la république démocratique du" },
  { titre: "Moluques", texte: "Les Moluques, en indonésien Maluku, sont un archipel situé dans l'Est de l'Indonésie, d'une superficie terrestre de 74 500 km2 avec plus de 2 millions d'habitants." },
  { titre: "Monaco", texte: "Monaco, en forme longue la principauté de Monaco (en monégasque : Principatu de Mu̍negu), est un État d'Europe de l'Ouest constitué d'une unique commune du même nom, ce qui en fait une cité-État." },
  { titre: "Monarchie constitutionnelle", texte: "Une monarchie constitutionnelle est un type de régime politique qui reconnaît un monarque élu ou héréditaire comme chef de l'État, mais où une constitution limite ses pouvoirs." },
  { titre: "Mongolie", texte: "La Mongolie est un vaste pays d'Asie orientale qui est enclavé entre la Russie au nord et la république populaire de Chine (RPC) au sud. Sa capitale et plus grande ville est Oulan-Bator. La population totale s'élève à un peu plus de 3 450 000 habitants en 2022." },
  { titre: "Mont Fuji", texte: "Le mont Fuji /mɔ̃ fudʒi/ ou /mɔ̃ fuʒi/ est une montagne du centre du Japon qui se trouve sur la côte sud de l'île de Honshū, au sud-ouest de l'agglomération de Tokyo. Avec 3 776 mètres d'altitude, il est le point culminant du Japon." },
  { titre: "Musée d'Orsay", texte: "Le musée d'Orsay est un musée parisien situé dans le 7e arrondissement, le long de la rive gauche de la Seine, en surplomb de la promenade Édouard-Glissant. Il a le statut de musée national en France." },
  { titre: "Musée Guggenheim", texte: "Le musée Guggenheim de Bilbao est un musée d'art moderne et contemporain situé à Bilbao au Pays basque espagnol qui a ouvert au public en 1997." },
  { titre: "Mustelidae", texte: "Les Mustélidés (Mustelidae), du latin mustela signifiant belette, sont une famille de mammifères caniformes de l'ordre des Carnivora. Ce sont des prédateurs, de taille variée (de 20 cm à plus de 2 m), avec un corps allongé et des pattes courtes." },
  { titre: "Mythologie grecque", texte: "La mythologie grecque, c'est-à-dire l'ensemble organisé des mythes provenant de la Grèce antique, se développe au cours d'une très longue période allant de la civilisation mycénienne jusqu'à la domination romaine." },
  { titre: "Mythologie nordique", texte: "La mythologie nordique est l'ensemble des mythes originaires d'Europe du Nord (plus particulièrement de la Scandinavie) qui constituent la base du système religieux polythéiste pratiqué dans ces régions au haut Moyen Âge avant leur christianisation." },
  { titre: "Neil Armstrong", texte: "Neil Alden Armstrong, né le 5 août 1930 à Wapakoneta dans l'Ohio, aux États-Unis, et mort le 25 août 2012 à Cincinnati dans le même État, est un astronaute américain, pilote d'essai, aviateur de l'United States Navy et professeur." },
  { titre: "Nelson Mandela", texte: "Nelson Rolihlahla Mandela, dont le nom du clan tribal est « Madiba », né le 18 juillet 1918 à Mvezo (province du Cap) et mort le 5 décembre 2013 à Johannesburg (Gauteng), est un homme d'État sud-africain." },
  { titre: "Néolithique", texte: "Le Néolithique est une période de la Préhistoire, qui débute durant le réchauffement climatique de l'Holocène. Défini à l'origine comme un « âge de la pierre polie », il est principalement caractérisé actuellement par la domestication de certaines plantes et animaux, et le début de l’agriculture et de l’élevage." },
  { titre: "Népal", texte: "Le Népal, en forme longue la république démocratique fédérale du Népal, est un pays enclavé de l'Asie du Sud, bordé par la Chine (région autonome du Tibet) au nord et par l'Inde sur le reste de ses frontières." },
  { titre: "Nestor Makhno", texte: "Nestor Ivanovitch Makhno, né le 7 novembre 1888 (26 octobre 1888 dans le calendrier julien) à Gouliaï Polié (ou Houliaïpole) — ville de l'ouïezd d'Oleksandrivsk du gouvernement de Iekaterinoslav, alors située dans l'Empire russe — et mort le 25 juillet 1934 dans le 20e arrondissement de Paris (France), est un" },
  { titre: "Nicéphore Niépce", texte: "Joseph Niépce dit Nicéphore Niépce, né le 7 mars 1765 à Chalon-sur-Saône (actuelle Saône-et-Loire) et mort le 5 juillet 1833 à Saint-Loup-de-Varennes (Saône-et-Loire), est un ingénieur français, connu comme étant l'inventeur de la photographie, appelée alors « procédé héliographique »." },
  { titre: "Nicolae Ceaușescu", texte: "Nicolae Ceaușescu, né le 26 janvier 1918 à Scornicești et mort le 25 décembre 1989 à Târgoviște, est un homme d'État roumain, dirigeant central de la Roumanie communiste, entre 1974 et 1989." },
  { titre: "Nicolas Copernic", texte: "Nicolas Copernic est un astronome polonais, également chanoine, médecin et mathématicien, né le 19 février 1473 à Thorn (Toruń) en Prusse royale (royaume de Pologne), et mort le 24 mai 1543 à Frauenburg (Prusse royale, royaume de Pologne ; aujourd'hui Frombork)." },
  { titre: "Nicolas II", texte: "Nicolas II, né Nikolaï Alexandrovitch Romanov le 6 mai 1868 (18 mai dans le calendrier grégorien) au palais de Tsarskoïe Selo (Pouchkine, Empire Russe) et assassiné le 17 juillet 1918 à Iekaterinbourg (République soviétique de Russie), est un empereur de Russie de la dynastie des Romanov." },
  { titre: "Nicolas Machiavel", texte: "Nicolas Machiavel (en italien : Niccolò di Bernardo dei Machiavelli) est un humaniste italien de la Renaissance né le 3 mai 1469 à Florence et mort dans cette même ville le 21 juin 1527." },
  { titre: "Niger", texte: "Le Niger, en forme longue la république du Niger, est un pays d'Afrique de l'Ouest, situé entre la Libye au nord-est, le Tchad à l'est, le Nigeria au sud, le Bénin au sud-ouest, le Burkina Faso à l'ouest-sud-ouest, le Mali à l'ouest et l'Algérie au nord-ouest." },
  { titre: "Nigeria", texte: "Le Nigeria ou Nigéria, en forme longue la république fédérale du Nigeria ou république fédérale du Nigéria (en anglais : Federal Republic of Nigeria), est un pays d'Afrique de l'Ouest situé dans le golfe de Guinée." },
  { titre: "Nihilisme", texte: "Le nihilisme (du latin nihil, « rien ») est, selon Léo Strauss (1899-1973) la séparation entre les valeurs et les faits, et proclame l'impossibilité de hiérarchiser les valeurs. Cette position implique l'amoralisme, le matérialisme et le scepticisme moral." },
  { titre: "Niue", texte: "Niue, Nioué ou Niué /nju.e/ (en anglais Niue, en niuéen Niuē) est un pays insulaire de l'océan Pacifique sud, en Polynésie occidentale. Il est situé à 2 400 km au nord-est de la Nouvelle-Zélande, au centre d'un triangle formé par les îles Tonga, Samoa et Cook." },
  { titre: "Norvège", texte: "La Norvège, en forme longue le royaume de Norvège (en bokmål : Kongeriket Norge — en nynorsk : Kongeriket Noreg), est un pays d'Europe du Nord." },
  { titre: "Nouveau Testament", texte: "Le Nouveau Testament est l'ensemble des écrits relatifs à la vie de Jésus et à l'enseignement de ses premiers disciples, écrits reconnus comme « canoniques » par les autorités chrétiennes au terme d'un processus de plusieurs siècles." },
  { titre: "Nouvelle-Angleterre", texte: "La Nouvelle-Angleterre (en anglais : New England) est une région historique du Nord-Est des États-Unis. Elle est composée de six États : Maine, Massachusetts, New Hampshire, Vermont, Rhode Island et Connecticut, historiquement parmi les premiers fondés." },
  { titre: "Nouvelle-Guinée", texte: "La Nouvelle-Guinée, encore appelée Papouasie, est une île de l'Océanie proche, riveraine notamment de l'Ouest de l'océan Pacifique, de la mer de Corail et de la mer d'Arafura. Sa superficie est d'environ 775 210 km2, ce qui en fait la deuxième plus grande île du monde après le Groenland." },
  { titre: "Nouvelle-Zélande", texte: "La Nouvelle-Zélande (en anglais : New Zealand ; en maori : Aotearoa) est un pays insulaire d'Océanie situé dans l'Est de la mer de Tasman. Elle est constituée de deux îles principales : l'île du Nord et l'île du Sud, ainsi que de 700 plus petites îles." },
  { titre: "Nubie", texte: "La Nubie est une région s'étendant le long du Nil sur près de 1 400 km, entre la première cataracte (au sud d'Assouan) et la confluence du Nil Bleu et du Nil Blanc (à Khartoum)." },
  { titre: "Nuremberg", texte: "Nuremberg est une ville de Bavière, en Allemagne. Avec 542 544 habitants en octobre 2022, c'est la deuxième ville de Bavière après Munich. Elle est le centre économique du district de Moyenne-Franconie et l'un des principaux centres industriels d'Allemagne du Sud." },
  { titre: "Ordre du Temple", texte: "L'Ordre du Temple est un ordre religieux et militaire français issu de la chevalerie chrétienne du Moyen Âge, dont les membres sont appelés les Templiers." },
  { titre: "Ordre Teutonique", texte: "L'ordre Teutonique (en allemand : der Deutsche Orden, littéralement « l'ordre Allemand ») ou ordre des chevaliers Teutoniques (Der Deutsche Ritterorden), dont les dénominations officielles (en latin) ont été Domus Hospitalis Sancte Marie Theutonicorum Hierosolymitani (maison de l'hôpital de Sainte-Marie-des-Allemands" },
  { titre: "Organisation des Nations unies", texte: "L'Organisation des Nations unies (ONU) est une organisation internationale regroupant 193 États membres depuis le 14 juillet 2011. Elle a été instituée le 24 octobre 1945 par la ratification de la Charte des Nations unies signée le 26 juin 1945 par les représentants de 51 États." },
  { titre: "Orson Welles", texte: "George Orson Welles, simplement appelé Orson Welles, parfois crédité sous les noms de O. W. Jeeves ou G. O. Spelvin (né le 6 mai 1915 à Kenosha, dans le Wisconsin et mort le 10 octobre 1985 à Hollywood, en Californie) est un artiste américain, à la fois acteur, réalisateur, producteur et scénariste, mais également" },
  { titre: "Oscar Wilde", texte: "Oscar Wilde /ˈɒskə waɪld/, dont le nom complet est Oscar Fingal O'Flahertie Wills Wilde, né à Dublin le 16 octobre 1854 et mort à Paris le 30 novembre 1900, est un écrivain, romancier, dramaturge et poète irlandais." },
  { titre: "Otto von Bismarck", texte: "Otto von Bismarck /ˈɔto fɔn ˈbɪsmaʁk/, duc de Lauenburg et prince de Bismarck, né le 1er avril 1815 à Schönhausen et mort le 30 juillet 1898 à Friedrichsruh, est un homme d'État prussien puis allemand." },
  { titre: "Oum Kalthoum", texte: "Fatima Ibrahim as-Sayyid al-Beltagi, dite Oum Kalthoum, également orthographié Oum Kalsoum (ou Om-e Kalsūm en dialecte égyptien) ou parfois Umm Kulthum, et surnommée « Souma », est une chanteuse, musicienne et actrice égyptienne, née entre 1898 et 1906, plus probablement en 1904, à Ṭamāy al-Zahāyira (dans le district" },
  { titre: "Oussama ben Laden", texte: "Oussama ben Laden (en arabe : أسامة بن محمد بن عوض بن لادن (Usāma bin Muḥammad bin ‘Awaḍ bin Lādin)), né le 10 mars 1957 à Riyad (Arabie saoudite) et mort le 2 mai 2011 à Abbottabad (Pakistan) tué par les forces spéciales américaines, est un djihadiste saoudien puis apatride." },
  { titre: "Ovide", texte: "Ovide, en latin Publius Ovidius Naso, né en 43 av. J.-C. à Sulmone (en italien Sulmona) dans le centre de l'Italie et mort en 17 ou 18 ap. J.-C., en exil à Tomis (l'actuelle Constanţa en Roumanie), est un poète latin qui vécut durant la période de la naissance de l'Empire romain." },
  { titre: "Pablo Escobar", texte: "Pablo Emilio Escobar Gaviria, né le 1er décembre 1949 à Rionegro (Antioquia, Colombie) et mort le 2 décembre 1993 à Medellín (Antioquia, Colombie), est un trafiquant de cocaïne colombien." },
  { titre: "Pablo Neruda", texte: "Pablo Neruda, nom de plume de Ricardo Eliécer Neftalí Reyes Basoalto, né le 12 juillet 1904 à Parral (région du Maule) et mort le 23 septembre 1973 à Santiago, est un poète, écrivain, diplomate, homme politique et intellectuel chilien." },
  { titre: "Pablo Picasso", texte: "Pablo Ruiz Picasso, né le 25 octobre 1881 à Malaga (Andalousie, Espagne) et mort le 8 avril 1973 à Mougins (Alpes-Maritimes, France), est un peintre, dessinateur, sculpteur et graveur espagnol ayant passé l'essentiel de sa vie en France." },
  { titre: "Pakistan", texte: "Le Pakistan, en forme longue la république islamique du Pakistan (en ourdou : اسلامی جمہوریۂ پاکستان (Islāmī Jumhūriyah Pākistān)), est un pays d'Asie du Sud entouré par l'Iran, l'Afghanistan, la Chine, l'Inde et la mer d'Oman." },
  { titre: "Palaos", texte: "Les Palaos (/pa.la.o(s)/), en forme longue la république des Palaos (en paluan : Belau et Beluu er a Belau ; en anglais : Palau et Republic of Palau), sont un pays d'Océanie situé en Micronésie, à l'est de Mindanao (Philippines), au nord de la Nouvelle-Guinée occidentale (Indonésie), à l'ouest des États fédérés de" },
  { titre: "Palerme", texte: "Palerme est une ville du Sud de l'Italie, chef-lieu de la région autonome de Sicile et de la ville métropolitaine de Palerme, qui englobe son aire urbaine. Palerme est renommée pour son histoire, sa culture, ses monuments architecturaux, son climat méditerranéen et sa cuisine." },
  { titre: "Palestine", texte: "La Palestine, en forme longue l'État de Palestine, est un État souverain de jure (loi palestinienne, siège d'État observateur à l'ONU, large reconnaissance internationale) et un proto-État de facto (occupation israélienne, défaut de souveraineté territoriale, absence de monnaie)." },
  { titre: "Panama", texte: "Le Panama, en forme longue la république du Panama (en espagnol : Panamá et República de Panamá), est un pays de 75 420 km2 appartenant géographiquement à l'Amérique latine." },
  { titre: "Pancho Villa", texte: "José Doroteo Arango Arámbula, plus connu sous le pseudonyme de Francisco Villa, ainsi que sous l'hypocoristique mexicain de Francisco, Pancho, né le 5 juin 1878 à La Coyotada, municipalité de San Juan del Rio, Durango, et mort le 20 juillet 1923 à Parral, Chihuahua, est un hors-la-loi mexicain devenu chef de la" },
  { titre: "Pangée", texte: "La Pangée est un supercontinent formé au Carbonifère de la collision de la Laurussia et du Protogondwana et ayant regroupé presque toutes les terres émergées." },
  { titre: "Panthéon", texte: "Le Panthéon de Rome est un édifice religieux antique situé sur la piazza della Rotonda (Rome), bâti sur l'ordre d'Agrippa en 27 av. J.-C. À l’origine, le Panthéon est un temple consacré à toutes les divinités de la religion romaine." },
  { titre: "Papouasie-Nouvelle-Guinée", texte: "La Papouasie-Nouvelle-Guinée (en anglais : Papua New Guinea ; en tok pisin : Papua Niugini ; en hiri motu : Papua Niu Gini), en forme longue l'État indépendant de Papouasie-Nouvelle-Guinée (en anglais : Independent State of Papua New Guinea ; en tok pisin : Independen Stet bilong Papua Niugini ; en hiri motu :" },
  { titre: "Paraguay", texte: "Le Paraguay, en forme longue république du Paraguay depuis 1813, est un État souverain enclavé d'Amérique du Sud. Néanmoins, il dispose d'un accès à la mer via le rio Paraná qui se jette dans l'océan Atlantique." },
  { titre: "Parthénon", texte: "Le Parthénon — grec ancien : Ὁ Παρθενών / Parthenṓn, littéralement « la salle ou la demeure des vierges » — est un trésor grec, situé sur l'acropole d'Athènes, destiné à la conservation d'une sculpture de la déesse Athéna, que les Athéniens considéraient comme la protectrice de leur cité." },
  { titre: "Peter Pan", texte: "Peter Pan est un personnage de fiction britannique créé par J. M. Barrie. Il apparaît pour la première fois dans le roman Le Petit Oiseau blanc en 1902, puis dans la pièce de théâtre Peter et Wendy (1904), plus connue sous le titre Peter Pan, et ensuite publiée en roman en 1911." },
  { titre: "Pétra", texte: "Pétra (du grec ancien : πέτρα (pétra), « rocher » ; en arabe : الْبَتْرَاء) est une cité nabatéenne située au sud de l'actuelle Jordanie. C'est le pôle touristique majeur de ce pays." },
  { titre: "Philippe V", texte: "Philippe V, dit el Animoso en espagnol, c'est-à-dire « le Brave », né le 19 décembre 1683 au château de Versailles et mort le 9 juillet 1746 au palais du Buen Retiro à Madrid, est un prince issu de la maison de France (Capétiens), devenu roi d'Espagne et des Indes en 1700, à la mort de son grand-oncle Charles II de" },
  { titre: "Pierre", texte: "Pierre (saint Pierre pour l'Église catholique et le christianisme orthodoxe), Siméon Bar-Yonah (traduit par « Simon, fils de Jonas ») selon le témoignage des Évangiles, aussi appelé Kephas (le « roc » en araméen) ou Simon-Pierre, est un Juif de Galilée ou de Gaulanitide connu pour avoir été l'un des disciples de Jésus" },
  { titre: "Pierre Abélard", texte: "Abélard, Abailard, ou encore Abeilard (en latin : Abaelardus), Pierre (en latin : Petrus) en religion, né en 1079 au Pallet près de Nantes et mort le 21 avril 1142, au prieuré Saint-Marcel près de Chalon-sur-Saône, est un philosophe, dialecticien et théologien chrétien français, père de la scolastique, inventeur du" },
  { titre: "Pierre Corneille", texte: "Pierre Corneille, aussi appelé « le Grand Corneille » ou « Corneille l'aîné », né le 6 juin 1606 à Rouen et mort le 1er octobre 1684 à Paris (paroisse Saint-Roch), est un dramaturge et poète français du XVIIe siècle." },
  { titre: "Pierre Curie", texte: "Pierre Curie, né le 15 mai 1859 à Paris et mort le 19 avril 1906 dans la même ville, est un physicien français, connu pour ses travaux en radioactivité, en magnétisme et en piézoélectricité." },
  { titre: "Pierre de Coubertin", texte: "Pierre de Coubertin, né Charles Pierre Fredy de Coubertin le 1er janvier 1863 à Paris et mort le 2 septembre 1937 à Genève en Suisse, est le rénovateur des Jeux olympiques qu'il relance à la fin du XIXe siècle, devenant le père des Jeux modernes." },
  { titre: "Pierre Elliott Trudeau", texte: "Pierre Elliott Trudeau, né le 18 octobre 1919 à Outremont (Québec) et mort le 28 septembre 2000 à Montréal (Québec), est un homme d'État canadien, premier ministre du Canada du 20 avril 1968 au 4 juin 1979, puis du 3 mars 1980 au 30 juin 1984, sous la bannière du Parti libéral." },
  { titre: "Pierre Ier le Grand", texte: "Pierre Ier, plus connu sous le nom de Pierre le Grand, né le 30 mai 1672 (9 juin dans le calendrier grégorien) à Moscou et mort le 28 janvier 1725 (8 février dans le calendrier grégorien) à Saint-Pétersbourg, devient tsar de Russie en 1682 et reçoit le titre d'empereur de toutes les Russies en 1721." },
  { titre: "Pierre-Joseph Proudhon", texte: "Pierre-Joseph Proudhon, né le 15 janvier 1809 à Besançon et mort le 19 janvier 1865 à Paris (16e arrondissement), est un polémiste, journaliste, économiste, philosophe, homme politique et sociologue français." },
  { titre: "Piet Mondrian", texte: "Pieter Cornelis Mondriaan, appelé Piet Mondrian à partir de 1912, né le 7 mars 1872 à Amersfoort (Pays-Bas) et mort le 1er février 1944 à New York, est un peintre néerlandais reconnu comme l'un des pionniers de l'abstraction." },
  { titre: "Pieter Brueghel l'Ancien", texte: "Pieter Brueghel ou Bruegel dit l'Ancien, parfois francisé en Pierre Brueghel l'Ancien (en brabançon : Pieter Bruegel den Aauwe) est un peintre et graveur brabançon né vers 1525 et mort le 9 septembre 1569 à Bruxelles dans les Pays-Bas espagnols." },
  { titre: "Pink Floyd", texte: "Pink Floyd est un groupe britannique de rock originaire de Londres. Le groupe débute avec un premier album de musique psychédélique pour ensuite bifurquer vers le rock progressif. Formé en 1965, il est considéré comme un pionnier et représentant majeur de ces styles musicaux." },
  { titre: "Piotr Ilitch Tchaïkovski", texte: "Piotr Ilitch Tchaïkovski ou Tchaïkovsky est un compositeur russe de l’époque romantique né le 25 avril 1840 (7 mai dans le calendrier grégorien) à Votkinsk et mort le 25 octobre 1893 (6 novembre dans le calendrier grégorien) à Saint-Pétersbourg." },
  { titre: "Piraterie", texte: "La piraterie ou forbannerie est une forme de banditisme pratiquée sur mer par des marins appelés pirates ou forbans, mais aussi sur terre et par extension, sur Internet." },
  { titre: "Plácido Domingo", texte: "José Plácido Domingo Embil, plus connu sous le nom de Plácido Domingo, est un chanteur d'opéra (ténor lirico-spinto), chef d'orchestre et administrateur d'opéra espagnol, né le 21 janvier 1941 à Madrid en Espagne." },
  { titre: "Platon", texte: "Platon, né en 428 / 427 av. J.-C. et mort en 348 / 347 av. J.-C. à Athènes, est un philosophe antique de la Grèce classique, contemporain de la démocratie athénienne et des sophistes qu'il critiqua vigoureusement." },
  { titre: "Playboy", texte: "Playboy est un magazine de la presse masculine américain fondé à Chicago en 1953 par Hugh Hefner. Il est connu pour ses photographies érotiques et ses playmates, mais aussi pour certains de ses articles." },
  { titre: "Pléiades", texte: "L'amas des Pléiades, les Pléiades ou amas M45, est un amas ouvert d'étoiles qui s'observe depuis les deux hémisphères, dans la constellation du Taureau." },
  { titre: "Pline l'Ancien", texte: "Pline l’Ancien (en latin Caius Plinius Secundus) ou Pline Le Naturaliste, né en 23 apr. J.-C. à Côme dans le Nord de l'Italie et mort en 79 à Stabies, près de Naples, lors de l'éruption du Vésuve, est un écrivain et naturaliste romain du Ier siècle." },
  { titre: "Plutarque", texte: "Plutarque, de son nom de citoyen romain Lucius Mestrius Plutarchus, né vers 44 à Chéronée en Béotie et mort vers 125, est un philosophe, biographe, moraliste, polygraphe et penseur majeur de la Rome antique." },
  { titre: "Poaceae", texte: "Les Graminées ou Poacées (Poaceae) sont une famille de plantes monocotylédones de l'ordre des Poales, qui comprend environ 12 000 espèces groupées en 780 genres, à répartition cosmopolite. C'est, par le nombre d'espèces, la cinquième famille de plantes à fleurs, après les Asteraceae, Orchidaceae, Fabaceae et Rubiaceae." },
  { titre: "Pois chiche", texte: "Le pois chiche, Cicer arietinum, est une espèce de plantes à fleurs dicotylédones de la famille des Fabaceae (légumineuses), sous-famille des Faboideae, originaire du Sud-Est de la Turquie." },
  { titre: "Poisson-globe", texte: "Les poissons-globes (Tetraodontidae, en français Tétraodontidés ; du grec ancien tetra = quatre et odous = dent) ou poissons-ballons, sont une famille de poissons ayant la capacité de se gonfler." },
  { titre: "Pologne", texte: "La Pologne, en forme longue république de Pologne (en polonais : Polska ; Rzeczpospolita Polska ), est un État d'Europe centrale, frontalier avec l'Allemagne à l'ouest, la Tchéquie au sud-ouest, la Slovaquie au sud, l'Ukraine à l'est-sud-est et la Biélorussie à l'est-nord-est, et enfin l'enclave russe de Kaliningrad" },
  { titre: "Polynésie", texte: "La Polynésie, une des trois régions traditionnelles de l'Océanie selon Dumont d'Urville, est un large groupement d'îles situées dans l'océan Pacifique, principalement dans sa partie sud." },
  { titre: "Polynésie française", texte: "La Polynésie française (en tahitien : Pōrīnetia farāni) est une collectivité d'outre-mer (plus spécifiquement pays d'outre-mer ou POM) au sein de la République française (code 987), composée de cinq archipels regroupant 118 îles dont 76 sont habitées : l'archipel de la Société avec les îles du Vent et les îles" },
  { titre: "Port-au-Prince", texte: "Port-au-Prince (en créole haïtien : Pòtoprens) est la capitale et la ville plus peuplée des communes d'Haïti, dont l'aire urbaine compterait près de 2 754 812 habitants (2019) appelés Port-au-Princiens et Port-au-Princiennes." },
  { titre: "Programme Apollo", texte: "Le programme Apollo est le programme spatial de la NASA mené durant la période 1961-1972, qui a permis aux États-Unis d'envoyer pour la première fois des hommes sur la Lune." },
  { titre: "Psychopathie", texte: "La psychopathie, des mots grecs : psyche, ψυχή (« esprit, âme ») et pathos, πάθος (« souffrance, changement accidentel »), est un trouble de la personnalité, caractérisé par un comportement antisocial, un manque de remords et un manque de « comportements humains », généralement associé dans la culture populaire à un" },
  { titre: "Quartz", texte: "Le quartz est un minéral du groupe des silicates, sous-groupe des tectosilicates, composé de dioxyde de silicium, ou silice, de formule chimique SiO2, avec des traces de différents éléments tels que Al, Li, B, Fe, Mg, Ca, Ti, Rb, Na, OH." },
  { titre: "Rafael Nadal", texte: "Rafael Nadal Parera, plus simplement appelé Rafa Nadal, né le 3 juin 1986 à Manacor (Espagne), est un joueur de tennis espagnol, professionnel de 2001 à 2024." },
  { titre: "Rainer Maria Rilke", texte: "Rainer Maria Rilke, né le 4 décembre 1875 à Prague en Royaume de Bohême (Autriche-Hongrie) et mort le 29 décembre 1926 à Montreux, est un écrivain austro-hongrois et autrichien." },
  { titre: "Raj britannique", texte: "Le Raj britannique (en anglais : British Raj) ou Empire des Indes (Indian Empire) est un territoire de l'ancien Empire britannique, dont il est la possession la plus riche et la plus peuplée." },
  { titre: "Rat musqué", texte: "Le Rat musqué ou Ondatra (Ondatra zibethicus) est une espèce de rongeurs de la famille des Cricétidés, mesurant 30 à 40 cm de long et pesant jusqu'à 1,5 kg (sec)." },
  { titre: "Rate", texte: "La rate est un organe profond, situé dans l'hypocondre gauche en regard de la 10e côte (côte splénique), accolé à la face latérale de l'estomac, la grande courbure. Elle est donc en position thoraco-abdominale." },
  { titre: "Ratel", texte: "Le Ratel est un mammifère carnivore de la famille des mustélidés. Au sein de son genre Mellivora, il s’agit de la seule espèce actuelle : le Ratel du Cap (Mellivora capensis)." },
  { titre: "Rattus norvegicus", texte: "Rattus norvegicus, le rat brun, est une espèce de rat. C'est un rongeur trapu de la famille des Muridae. Il a un corps long d'environ 25 cm et une queue d'à peu près la même taille. Adulte, il pèse environ 300 g. Il est donc plus grand et plus lourd que son proche parent le rat noir (Rattus rattus)." },
  { titre: "Réchauffement climatique", texte: "Le changement climatique, également nommé réchauffement climatique voire dérèglement climatique, est l'effet de l'augmentation rapide de la température moyenne de la surface terrestre en cours aux XXe et XXIe siècles ainsi que, plus généralement, la modification des régimes météorologiques à grande échelle qui en" },
  { titre: "Reconquista", texte: "La Reconquista (mot espagnol et portugais, en français : « la Reconquête ») est une succession de conflits entre les royaumes chrétiens du Nord de l'Espagne et les territoires musulmans d'Al-Andalus. Ces conflits durent du VIIIe au XVe siècle." },
  { titre: "Région wallonne", texte: "La Région wallonne (en allemand : Wallonische Region ; en néerlandais : Waals Gewest), communément appelée Wallonie (en allemand : Wallonien ; en néerlandais : Wallonië), est l'une des trois régions belges." },
  { titre: "Renaissance", texte: "La Renaissance est un mouvement de l'histoire européenne associé à la remise à l'honneur de la littérature, de la philosophie et des arts de l'Antiquité gréco-romaine." },
  { titre: "Requin", texte: "Les requins, squales ou sélachimorphes forment un super-ordre des poissons cartilagineux, possédant cinq à sept fentes branchiales sur les côtés de la tête et les nageoires pectorales qui ne sont pas fusionnées à la tête." },
  { titre: "Requin-baleine", texte: "Le Requin-baleine (Rhincodon typus) est une espèce de poissons cartilagineux, seul membre du genre Rhincodon et seule espèce actuelle de la famille des Rhincodontidae." },
  { titre: "Révolte des Boxers", texte: "La révolte des Boxers, ou révolte des Boxeurs, ou guerre des Boxers, est un conflit armé ayant eu lieu en Chine entre 1899 et 1901. Elle est organisée par les Poings de la justice et de la concorde, société secrète dont le symbole est un poing fermé, d'où le surnom de Boxers donné à ses membres en Occident." },
  { titre: "Révolution américaine", texte: "La révolution américaine (19 avril 1765 – 3 septembre 1783) est une période de changements politiques après 1763 dans les treize colonies britanniques d'Amérique du Nord, qui ont donné lieu à la guerre d'indépendance des États-Unis contre la Grande-Bretagne (1775-1783), avec l'aide de la France." },
  { titre: "Révolution culturelle", texte: "La révolution culturelle, ou grande révolution culturelle prolétarienne, plus couramment la grande révolution culturelle, (1966-1976), représente l'un des événements marquants de l'histoire de la république populaire de Chine, dont le retentissement international est considérable." },
  { titre: "Révolution française", texte: "La Révolution française (1789-1799) est une période d'intenses bouleversements politiques et sociaux en France et dans ses colonies, ainsi qu'en Europe à la fin du XVIIIe siècle." },
  { titre: "Révolution haïtienne", texte: "La révolution haïtienne, aussi appelée guerre d'indépendance haïtienne ou guerre de Saint-Domingue, constitue la première révolte d'esclaves réussie du monde moderne. Les historiens situent traditionnellement son départ lors de la cérémonie vaudoue du Bois-Caïman, en août 1791." },
  { titre: "Révolution industrielle", texte: "La révolution industrielle est le processus historique du XIXe siècle qui fait basculer une société à dominante agraire et artisanale vers une société commerciale et industrielle. Cette transformation affecte profondément l'agriculture, l'économie, le droit, la politique, la société et l'environnement." },
  { titre: "Révolution iranienne", texte: "La révolution iranienne, également appelée révolution islamique est la révolution de 1979 qui a transformé l'Iran en république islamique, renversant l'État impérial d'Iran et la dynastie Pahlavi." },
  { titre: "Révolution mexicaine", texte: "La révolution mexicaine (en espagnol : Revolución mexicana) est la série de soulèvements armés, de coups d'État et de conflits militaires entre factions qui se produisent au Mexique entre 1910 et 1920." },
  { titre: "Révolution russe", texte: "La révolution russe est l’ensemble des événements ayant conduit en février 1917 au renversement spontané du régime tsariste de Russie, puis en octobre de la même année à la prise de pouvoir par les bolcheviks et à l’installation d’un régime léniniste (« communiste »)." },
  { titre: "Riyad", texte: "Riyad est la capitale du royaume d’Arabie saoudite et de la province de Riyad. Elle s’étend sur 1 554 km2, et comptait officiellement plus de six millions d'habitants lors du recensement en 2017, ce qui en fait la ville la plus peuplée d'Arabie saoudite et de la péninsule Arabique." },
  { titre: "Robert Ier", texte: "Robert Ier, également appelé Robert Bruce (Robert de Brus en anglo-normand, Roibert a Briuis en gaélique écossais, Robert the Bruce en anglais), est roi des Ecossais de 1306 à 1329." },
  { titre: "Robert Johnson", texte: "Robert Leroy Johnson, né le 8 mai 1911 à Hazlehurst, Mississippi, et mort le 16 août 1938 à Greenwood, Mississippi, est un guitariste et chanteur de blues américain, l'un des artistes les plus influents de l'histoire de cette musique." },
  { titre: "Robert Lee", texte: "Robert Edward Lee, né le 19 janvier 1807 à la plantation de Stratford Hall et mort le 12 octobre 1870 à Lexington, est un militaire américain. Diplômé de l'Académie militaire de West Point, il est officier du génie pendant plus de trente ans dans l'armée des États-Unis." },
  { titre: "Robert Louis Stevenson", texte: "Robert Louis Stevenson /ˈɹɒbət ˈluɪs ˈstiːvənsən/, né le 13 novembre 1850 à Édimbourg et mort le 3 décembre 1894 à Vailima (Samoa), est un écrivain écossais et un grand voyageur, connu dans le monde entier principalement pour deux de ses romans, L'Île au trésor (1883) et L'Étrange Cas du docteur Jekyll et de M. Hyde" },
  { titre: "Robert Oppenheimer", texte: "Julius Robert Oppenheimer, généralement appelé Robert Oppenheimer ou J. Robert Oppenheimer, est un physicien américain, né le 22 avril 1904 à New York et mort le 18 février 1967 à Princeton (New Jersey)." },
  { titre: "Romantisme", texte: "Le romantisme est un mouvement culturel apparu à la fin du XVIIIe siècle en Allemagne et en Angleterre et se diffusant dans l'Occident au cours du XIXe siècle jusqu’aux années 1850." },
  { titre: "Rome", texte: "Rome est la capitale de l'Italie. Située au centre ouest de la péninsule italienne, près de la mer Tyrrhénienne, elle est également la capitale de la région du Latium." },
  { titre: "Roméo et Juliette", texte: "Roméo et Juliette (Romeo and Juliet) est une tragédie de William Shakespeare. Écrite vers le début de sa carrière, elle raconte l'histoire de deux jeunes gens, Roméo Montaigu et Juliette Capulet, qui s'aiment malgré la haine que se vouent leurs familles et connaissent un destin funeste." },
  { titre: "Rosario", texte: "Rosario est une ville d'Argentine, le chef-lieu du département de même nom, la plus grande ville de la province de Santa Fe et la troisième ville d'Argentine derrière Buenos Aires et Córdoba." },
  { titre: "Roulette", texte: "La roulette est un jeu de hasard dans lequel chaque joueur parie sur le numéro qui sera tiré par le croupier. Le jeu de la roulette est l'un des plus connus du grand public, notamment en raison de sa simplicité." },
  { titre: "Roumanie", texte: "La Roumanie (en roumain : România) est un pays d'Europe de l'Est, partagé entre Europe centrale, orientale et du Sud-Est. C’est le sixième pays le plus peuplé de l'Union européenne et le huitième pays le plus grand pour sa superficie totale." },
  { titre: "Royaume-Uni", texte: "Le Royaume-Uni, en forme longue le Royaume-Uni de Grande-Bretagne et d'Irlande du Nord, est un pays d'Europe de l'Ouest ou, selon d'autres définitions, d'Europe du Nord, situé au nord-ouest de l'Europe continentale." },
  { titre: "Rubik's Cube", texte: "Le Rubik's Cube (ou cube de Rubik) est un casse-tête inventé par Ernő Rubik en 1974, et qui s'est rapidement répandu sur toute la planète au cours des années 1980. Au Canada francophone, il est nommé cube Rubik (sans le « de ») et l'appellation Rubik's Cube est considérée comme exclusivement anglophone." },
  { titre: "Rugby à XV", texte: "Le rugby à XV, aussi appelé rugby union dans les pays anglophones, qui se joue par équipes de quinze joueurs sur le terrain avec des remplaçants, est la variante la plus pratiquée du rugby, famille de sports collectifs, dont les spécificités sont les mêlées et les touches, mettant aux prises deux équipes qui se" },
  { titre: "Russie", texte: "La Russie, en forme longue la fédération de Russie, est un pays transcontinental, le plus vaste État de la planète, à cheval sur l'Asie du Nord (80 % de sa superficie) et sur l'Europe de l'Est (20 %)." },
  { titre: "Rwanda", texte: "Le Rwanda, en forme longue la république du Rwanda (en kinyarwanda : Repubulika y'u Rwanda, en anglais : Republic of Rwanda, en swahili : Jamhuri ya Rwanda), surnommé le « pays des mille collines », est un pays d'Afrique de l'Est." },
  { titre: "Sagrada Família", texte: "La Sagrada Família (nom complet en catalan : Temple Expiatori de la Sagrada Família ; en espagnol : Templo Expiatorio de la Sagrada Familia ; en français : « temple expiatoire de la Sainte Famille ») est une basilique de Barcelone dont la construction a commencé en 1882." },
  { titre: "Saint-Empire romain germanique", texte: "Le Saint-Empire romain germanique, selon la terminologie francophone usuelle, est un État d'Europe ayant existé de 962 (couronnement d'Otton Ier) à 1806 (abdication de François II)." },
  { titre: "Samoa", texte: "Les Samoa, en forme longue l'État indépendant des Samoa, en samoan Samoa et Malo Sa'oloto Tuto'atasi o Samoa, en anglais Samoa et Independent State of Samoa, ou le Samoa (forme longue : État indépendant du Samoa), sont un État indépendant de Polynésie occidentale, situé dans l'ouest de l'océan Pacifique sud, appelé" },
  { titre: "Samouraï", texte: "Les samouraïs appartenaient à la classe guerrière professionnelle du Japon préindustriel et servaient les seigneurs. Issus de familles de guerriers, ils étaient formés dès leur plus jeune âge aux arts martiaux par le biais d'un enseignement privé." },
  { titre: "San Antonio", texte: "La ville de San Antonio est le siège du comté de Bexar, dans le sud de l'État du Texas, aux États-Unis. Lors du recensement fédéral de 2020, sa population était de 1 434 625 habitants, ce qui en fait la septième ville du pays et la seconde du Texas." },
  { titre: "San Francisco", texte: "San Francisco, officiellement « ville et comté de San Francisco » (en anglais : « City and County of San Francisco »), est une ville des États-Unis et l'un des comtés de l'État de Californie." },
  { titre: "Sandro Botticelli", texte: "Alessandro di Mariano di Vanni Filipepi, dit Sandro Botticelli, est un peintre toscan, né à Florence le 1er mars 1445 et mort le 17 mai 1510 dans la même ville. Botticelli est l'un des peintres les plus importants de la Renaissance italienne et de l'histoire de l'art." },
  { titre: "Sanskrit", texte: "Le sanskrit ou sanscrit est une langue indo-européenne de la famille indo-aryenne, encore parlée dans le sous-continent indien bien que par une minorité. De nos jours, elle est encore parlée dans quelques villages et par certains érudits qui publient des œuvres universitaires ou tiennent des colloques en sanskrit." },
  { titre: "Sappho", texte: "Sappho ou encore Sapho, Psaphô, Psapha est une poétesse grecque de l’Antiquité qui a vécu aux VIIe et VIe siècles av. J.-C., à Mytilène sur l’île de Lesbos." },
  { titre: "Sarah Bernhardt", texte: "Sarah Bernhardt, née le 22 octobre 1844 à Paris et morte le 26 mars 1923 à Paris 17e, est une comédienne, peintre et sculptrice française. Elle est considérée comme une des plus importantes actrices françaises du XIXe et du début du XXe siècle." },
  { titre: "Sarrasin commun", texte: "Le sarrasin commun (Fagopyrum esculentum, Moench) est une espèce de plantes à fleurs, annuelles, de la famille des polygonacées, cultivée pour ses graines destinées à l'alimentation humaine comme animale." },
  { titre: "Sassanides", texte: "L'Empire sassanide, officiellement connu sous le nom d'empire des Iraniens (pehlevi : 𐭠𐭩𐭥𐭠𐭭𐭱𐭲𐭥𐭩 / Ērānshahr), est la dernière dynastie impériale perse avant la conquête musulmane au milieu du VIIe siècle." },
  { titre: "Sauge", texte: "Les sauges, Salvia en latin, sont un genre de plantes à fleurs de la famille des Lamiacées. Il comprend plus de 900 espèces, annuelles, bisannuelles, vivaces ou arbustives. Une dizaine de sauges sont indigènes en Europe, par exemple la sauge des prés." },
  { titre: "Scipion l'Africain", texte: "Scipion l'Africain (Publius Cornelius Scipio Africanus), dit aussi Scipion l'Ancien ou le Premier Africain pour le distinguer de son petit-fils adoptif Scipion Émilien, est un chef militaire et un homme d'État romain." },
  { titre: "Scoutisme", texte: "Le scoutisme (de l'anglais scout, mot signifiant, à l'origine, éclaireur, lui-même issu de l'ancien français « escoute » signifiant écoute) est un mouvement de jeunesse mondial créé par Robert Baden-Powell, un général protestant britannique à la retraite, en 1907, à Brownsea." },
  { titre: "Sean Connery", texte: "Sir Sean Connery, né le 25 août 1930 à Édimbourg (Écosse) et mort le 31 octobre 2020 à Nassau (Bahamas), est un acteur et producteur britannique." },
  { titre: "Seconde Guerre mondiale", texte: "La Seconde Guerre mondiale, ou Deuxième Guerre mondiale, est un conflit armé à l'échelle planétaire qui dure du 1er septembre 1939 au 2 septembre 1945. Ce conflit oppose schématiquement les Alliés et l'Axe." },
  { titre: "Sénèque", texte: "Sénèque (en latin Lucius Annaeus Seneca), parfois nommé Sénèque le Jeune, Sénèque le Philosophe ou Sénèque le Tragique, né vers l'an 4 av. J.-C. à Corduba et mort le 12 avril 65 à Rome, est un homme d'État romain, un philosophe et un dramaturge." },
  { titre: "Shabbat", texte: "Le shabbat ou chabbat est le jour de repos assigné au septième jour de la semaine biblique, qui commence dès la tombée de la nuit du vendredi soir jusqu'au samedi soir. Le shabbat est officiellement jour chômé en Israël et les magasins et les transports publics ne fonctionnent pas." },
  { titre: "Simón Bolívar", texte: "Simón Bolívar /siˈmon boˈliβaɾ/, de son nom complet Simón José Antonio de la Santísima Trinidad Bolívar y Palacios, surnommé El Libertador, né le 24 juillet 1783 à Caracas dans la vice-royauté de Nouvelle-Grenade (aujourd'hui au Venezuela), et mort le 17 décembre 1830 à Santa Marta en Grande Colombie, est un général" },
  { titre: "Sitting Bull", texte: "Sitting Bull, de son nom en dialecte lakota Tȟatȟáŋka Íyotake ou Tatanka Youtonga (aussi parfois traduit par Taureau-assis, Bœuf-assis ou Bison qui s’assoit), né vers 1831 dans l'actuel Dakota du Sud et tué le 15 décembre 1890 dans la réserve indienne de Standing Rock, est un chef de tribu et médecin des Lakotas" },
  { titre: "Slobodan Milošević", texte: "Slobodan Milošević, né le 20 août 1941 à Požarevac (Yougoslavie, aujourd'hui en Serbie) est mort en prison le 11 mars 2006 à La Haye (Pays-Bas), est un homme d'État yougoslave." },
  { titre: "Socrate", texte: "Socrate est un philosophe grec du Ve siècle av. J.-C., né vers -470/469 et mort empoisonné en -399 à Athènes. Il est connu comme l'un des « fondateurs » de la philosophie. Socrate n'a laissé aucun écrit, sa pensée et sa réputation se sont transmises par des témoignages indirects." },
  { titre: "Sophia Loren", texte: "Sofia Villani Scicolone, dite Sophia Loren, née le 20 septembre 1934 à Rome (Italie) est une actrice, chanteuse et mannequin italienne naturalisée française." },
  { titre: "Søren Kierkegaard", texte: "Søren Aabye Kierkegaard, né le 5 mai 1813 et mort le 11 novembre 1855 à Copenhague, est un théologien, philosophe, écrivain et poète danois protestant, dont l’œuvre est considérée comme une première forme de l'existentialisme chrétien." },
  { titre: "Sperme", texte: "Le sperme est un liquide biologique, composant de l'éjaculat, expulsé du corps lors de l'éjaculation et contenant les spermatozoïdes. Sécrétés par les organes sexuels mâles, les spermatozoïdes contenus dans le sperme peuvent fertiliser l'ovocyte femelle et ainsi entamer le processus de reproduction." },
  { titre: "Stockholm", texte: "Stockholm (prononciation en suédois : /²stɔkː(h)ɔlm/ ) est la plus grande ville et la capitale de la Suède. Elle est le siège du gouvernement et du parlement, ainsi que le lieu de résidence officielle du monarque suédois (actuellement Charles XVI Gustave)." },
  { titre: "Strasbourg", texte: "Strasbourg est une commune française située dans la collectivité européenne d'Alsace dont elle est le chef-lieu. Elle est la préfecture du Bas-Rhin et de la région Grand Est. Capitale de la région historique d'Alsace, elle est bordée par le Rhin et frontalière avec l'Allemagne." },
  { titre: "Stuttgart", texte: "Stuttgart est la capitale du Land de Bade-Wurtemberg, dans le Sud de l'Allemagne. Stuttgart est par sa population la sixième ville d'Allemagne." },
  { titre: "Suède", texte: "La Suède — en forme longue le royaume de Suède — est un pays d'Europe du Nord et de Scandinavie. Sa capitale est Stockholm, ses citoyens sont les Suédois et Suédoises et sa langue officielle et majoritaire est le suédois." },
  { titre: "Suisse", texte: "La Suisse, en forme longue la Confédération suisse, est un État fédéral d'Europe centrale et de l'Ouest, formé de 26 cantons, avec Berne pour capitale de facto." },
  { titre: "Suite de Fibonacci", texte: "En mathématiques, la suite de Fibonacci, tirant son nom du mathématicien italien Fibonacci, est une suite de nombres entiers dans laquelle chaque nombre est la somme des deux nombres qui le précèdent." },
  { titre: "Sumer", texte: "Sumer est une région antique, située à l'extrême sud de la Mésopotamie antique (actuel Irak), couvrant une vaste plaine parcourue par le Tigre et l'Euphrate, bordée, au sud-est, par le golfe Persique." },
  { titre: "Sumo", texte: "Le sumo est un sport de lutte japonais. Le combat sumo se caractérise par le gabarit des lutteurs ainsi que par les nombreux rites traditionnels qui entourent les combats, et consiste en deux règles simples : les lutteurs ne doivent pas sortir du cercle (dohyō), ni toucher le sol avec une autre partie du corps que la" },
  { titre: "Super Bowl", texte: "Le Super Bowl est la finale du championnat organisé par la National Football League (NFL), ligue américaine de football américain. Conclusion des séries éliminatoires, il oppose les vainqueurs des deux conférences de la ligue, l'American Football Conference (AFC) et la National Football Conference (NFC)." },
  { titre: "Suriname", texte: "Le Suriname (parfois également orthographié Surinam), en forme longue la république du Suriname (en néerlandais : Suriname et Republiek Suriname), est un pays d'Amérique du Sud (appelé Guyane néerlandaise jusqu'à son indépendance en 1975)." },
  { titre: "Svalbard", texte: "Le Svalbard est un archipel norvégien situé en mer du Groenland, dans l'océan Arctique, en mer de Barents et en mer de Norvège, entre le Groenland à l'ouest, la terre François-Joseph à l'est et l'Europe continentale au sud." },
  { titre: "Swahili", texte: "Le swahili, ou plus précisément les langues swahilies ou parfois souahélies, est un groupe de langues bantoues aux fortes origines et apports sémitiques, notamment de l'arabe parlé en Afrique de l'Est." },
  { titre: "Sydney", texte: "Sydney est la ville la plus peuplée d'Australie et du continent océanien, ainsi que la capitale de l'État de Nouvelle-Galles du Sud (mais n'est cependant pas la capitale de l'Australie, qui est Canberra)." },
  { titre: "Syracuse", texte: "Syracuse est une ville italienne de Sicile, chef-lieu du libre consortium municipal de Syracuse et l'un des cœurs culturels du monde méditerranéen depuis les temps de la Grèce antique." },
  { titre: "Syrie", texte: "La Syrie, en forme longue la République arabe syrienne, est un pays d'Asie de l'Ouest. Située sur la côte orientale de la mer Méditerranée, elle possède des frontières terrestres avec la Turquie, l'Irak, la Jordanie, Israël, le Liban et une frontière maritime avec Chypre." },
  { titre: "Talmud", texte: "La Bible est la clé de voûte du judaïsme, mais le Talmud en est le pilier central qui, s'élançant des fondations, en soutient l'édifice intellectuel et spirituel. Pivot de la créativité et de la vie nationales, le talmud est, à bien des égards, l'ouvrage le plus important de la culture juive." },
  { titre: "Tanakh", texte: "Le Tanakh est l'ensemble des livres de la Bible hébraïque. Le mot est un acronyme de l'hébreu כתובים-נביאים-תּוֹרָה (« Torah-Nevi'im-Ketouvim »), formé à partir de la syllabe initiale de chacun des titres des trois parties constitutives :" },
  { titre: "Tantrisme", texte: "« Tantrisme », terme inventé au XIXe siècle en Occident et dérivé du mot tantra, désigne un ensemble de textes, de doctrines, de rituels et de méthodes initiatiques qui ont pénétré de façon diffuse la plupart des branches de l'hindouisme (ainsi que dans le jaïnisme)." },
  { titre: "Taoïsme", texte: "Le taoïsme est un des trois piliers de la pensée chinoise avec le confucianisme et le bouddhisme, et se fonde sur l'existence d'un principe à l’origine de toute chose, appelé « tao »." },
  { titre: "Tardigrada", texte: "Les tardigrades (Tardigrada), parfois surnommés oursons d'eau, forment un phylum du règne animal, regroupé avec les arthropodes et les onychophores au sein du clade des panarthropodes. Ils ont été décrits en premier par Johann August Ephraim Goeze en 1773." },
  { titre: "Taupe", texte: "Taupe est un nom vernaculaire ambigu en français, pouvant désigner plusieurs espèces différentes de petits mammifères fouisseurs vivant dans des galeries souterraines creusées dans la couche meuble de terre arable du sol, et dont la présence est signalée par les petits monticules de terre déblayée constituant les" },
  { titre: "Tchécoslovaquie", texte: "La Tchécoslovaquie est un État souverain essentiellement constitué des actuelles Tchéquie et Slovaquie, qui exista en Europe centrale durant 68 ans, sous plusieurs formes constitutionnelles successives, du 28 octobre 1918 au 15 mars 1939 et du 5 avril 1945 au 31 décembre 1992 ; entre ces deux périodes, pendant la" },
  { titre: "Téléphone mobile", texte: "Un téléphone mobile, téléphone portable ou téléphone cellulaire est un appareil électronique de télécommunication, normalement portatif, offrant une fonction de téléphonie mobile et pouvant être utilisé sur de grandes distances sous réserve d'une couverture réseau." },
  { titre: "Télévision", texte: "La télévision, également appelée télé dans le langage courant (par apocope) ou désignée par le sigle TV, est un ensemble de techniques destinées à émettre et recevoir des séquences audiovisuelles, appelées programme télévisé : émissions, films et éventuellement de séquences publicitaires ou séries." },
  { titre: "Terre", texte: "La Terre est la troisième planète par ordre d'éloignement au Soleil et la cinquième plus grande du Système solaire aussi bien par la masse que par le diamètre. Par ailleurs, elle est le seul objet céleste connu pour abriter la vie." },
  { titre: "Texas", texte: "Le Texas (prononcé : /tɛɡzɑ(s)/ ou /teksas/ ; en anglais : /ˈtɛksəs/ ; en espagnol : Texas ou Tejas /ˈtexas/ ) est un État du Sud des États-Unis, le deuxième plus vaste du pays (696 241 km2) après l'Alaska et deuxième plus peuplé après la Californie." },
  { titre: "Thaïlande", texte: "La Thaïlande, en forme longue le royaume de Thaïlande (en thaï : ประเทศไทย, Prathet Thai et ราชอาณาจักรไทย, Ratcha Anachak Thai), est un pays d’Asie du Sud-Est, appelé royaume de Siam jusqu'en 1939." },
  { titre: "Théorie du complot", texte: "Une théorie du complot, complotiste, conspirationniste ou conjurationniste est une théorie qui explique un événement comme résultant majoritairement d'un complot, c'est-à-dire d'une action planifiée et dissimulée d'une ou plusieurs personnes en vue de nuire à une ou plusieurs autres personnes." },
  { titre: "Thérèse d'Avila", texte: "Thérèse d'Avila (en espagnol Teresa de Ávila), en religion Thérèse de Jésus (en espagnol Teresa de Jesús), née le 28 mars 1515 à Ávila en Vieille-Castille et morte dans la nuit du 4 au 15 octobre 1582 (qui correspond au passage du calendrier julien au calendrier grégorien) à Alba de Tormes, est une religieuse" },
  { titre: "Thomas d'Aquin", texte: "Thomas d'Aquin, né en 1225 ou 1226 au château de Roccasecca près d'Aquino, dans la partie péninsulaire du royaume de Sicile (Latium), et mort le 7 mars 1274 à l'abbaye de Fossanova près de Priverno dans les États pontificaux (dans le Latium également), est un religieux italien de l'ordre dominicain, célèbre pour son" },
  { titre: "Thomas Sankara", texte: "Thomas Sankara, né le 21 décembre 1949 à Yako (Haute-Volta) et mort assassiné le 15 octobre 1987 à Ouagadougou (Burkina Faso), est un militaire et homme d'État voltaïque, puis burkinabè, chef de l’État de la république de Haute-Volta, rebaptisée Burkina Faso, de 1983 à 1987." },
  { titre: "Thriller", texte: "Thriller est le sixième album studio du chanteur et auteur-compositeur américain Michael Jackson et son deuxième chez Epic Records. Coproduit par Quincy Jones, qui avait déjà collaboré avec Jackson sur l’album Off the Wall en 1979, il sort le 29 novembre 1982." },
  { titre: "Tibère", texte: "Tibère (latin : Tiberius Cæsar Divi Augusti Filius Augustus), né à Rome le 16 novembre 42 av. J.-C. et mort à Misène le 16 mars 37 ap. J.-C., est le deuxième empereur romain de 14 à 37. Il appartient à la dynastie julio-claudienne." },
  { titre: "Tibet", texte: "Le Tibet, ou anciennement Thibet, est une région de plateau située au nord de l'Himalaya en Asie, habitée traditionnellement par les Tibétains et d'autres groupes ethniques (Monbas, Qiang et Lhobas) et comportant également une population importante de Hans et de Huis." },
  { titre: "Tombouctou", texte: "Tombouctou (en berbère : ⵜⵉⵏ ⴱⵓⵇⵜ Tin Buqt, littéralement : « la lointaine ») est une ville et une commune urbaine malienne, chef-lieu du cercle de Tombouctou et de la région de Tombouctou. Elle se situe à une douzaine de kilomètres au nord du fleuve Niger." },
  { titre: "Turbine à vapeur", texte: "Une turbine à vapeur est une machine qui extrait l'énergie thermique de la vapeur sous pression et l'utilise pour produire un travail mécanique de rotation de l'arbre de sortie. La version moderne fut inventée par Sir Charles Parsons en 1884." },
  { titre: "Univers", texte: "L'Univers, au sens cosmologique, est l'ensemble de tout ce qui existe, décrit à partir d'observations scientifiques et régi par des lois physiques." },
  { titre: "Uranus", texte: "Uranus est la septième planète du Système solaire par ordre d'éloignement du Soleil. Elle orbite autour de celui-ci à une distance d'environ 19,2 unités astronomiques (2,87 milliards de kilomètres), avec une période de révolution de 84,05 années terrestres." },
  { titre: "Ursula K. Le Guin", texte: "Ursula K. Le Guin ou Ursula Kroeber Le Guin /ˈɝsələ ˈkɹoʊbɚ lə ˈɡwɪn/, née Ursula Kroeber le 21 octobre 1929 à Berkeley en Californie et morte le 22 janvier 2018 à Portland en Oregon, est une écrivaine américaine, surtout connue pour ses récits de littératures de l'imaginaire, notamment les œuvres de science-fiction" },
  { titre: "Usain Bolt", texte: "Usain Bolt est un athlète jamaïcain spécialiste des épreuves de sprint, né le 21 août 1986 dans la paroisse de Trelawny (Jamaïque). Il est généralement considéré comme le plus grand sprinteur de tous les temps." },
  { titre: "Valentina Terechkova", texte: "Valentina Vladimirovna Terechkova, surnommée la Mouette, née le 6 mars 1937 à Maslennikovo (raïon de Toutaïev dans l'oblast de Iaroslavl), est une cosmonaute et est la première femme à être allée dans l'espace à l'âge de 26 ans." },
  { titre: "Vasco de Gama", texte: "Vasco de Gama (en portugais : Vasco da Gama) né vers 1460 ou 1469 à Sines (Portugal) et mort le 24 décembre 1524 à Cochin aux Indes orientales, est un grand navigateur portugais, considéré comme le premier Européen à atteindre les Indes orientales par la route des Indes maritime, vers l'océan Indien, en contournant en" },
  { titre: "Vassily Kandinsky", texte: "Vassily Kandinsky, né le 4 décembre 1866 à Moscou et mort le 13 décembre 1944 à Neuilly-sur-Seine, est un peintre russe, naturalisé allemand puis français. Il est considéré comme l'un des pionniers de l'art abstrait." },
  { titre: "Venise", texte: "Venise est une ville côtière du Nord-Est de l'Italie, sur les rives de la mer Adriatique. Elle s'étend sur la Terraferma veneziana ainsi que sur un ensemble de 121 petites îles séparées par un réseau de canaux et reliées par 435 ponts." },
  { titre: "Vercingétorix", texte: "Vercingétorix, né aux environs de 82 av. J.-C. sur le territoire arverne, l'actuelle Auvergne, et mort à l'automne 46 av. J.-C. dans une prison de Rome, est le chef et le roi du peuple celte des Arvernes." },
  { titre: "Victor Hugo", texte: "Victor Hugo, né le 7 ventôse an X (26 février 1802) à Besançon et mort le 22 mai 1885 à Paris, est un poète, dramaturge, romancier et dessinateur français associé au romantisme. Il est considéré comme l'un des écrivains de la langue française et de la littérature mondiale les plus importants." },
  { titre: "Victoria", texte: "Victoria, née Alexandrina Victoria le 24 mai 1819 au palais de Kensington à Londres et morte le 22 janvier 1901 à Osborne House sur l'île de Wight, est reine du Royaume-Uni de Grande-Bretagne et d'Irlande du 20 juin 1837 jusqu'à sa mort." },
  { titre: "Vienne", texte: "Vienne est la capitale et la plus grande ville de l'Autriche ; elle est aussi l'un des neuf Länder (État fédéré) du pays (en allemand : Bundesland Wien)." },
  { titre: "Vigogne", texte: "La vigogne (Vicugna vicugna) est une espèce de mammifères d'Amérique du Sud qui vit sur les hauts plateaux de la cordillère des Andes. Tout comme l'alpaga, la vigogne appartient au genre Vicugna, au sein de la famille des camélidés." },
  { titre: "Vilnius", texte: "Vilnius, anciennement Wilno puis Vilna, fondée par le grand-duc Ghédimin, est la capitale de la Lituanie. Avec plus de 574 000 habitants, c'est la ville la plus peuplée du pays." },
  { titre: "Viol", texte: "Le viol est un acte sexuel sans le consentement de l'ensemble des personnes impliquées et consistant donc en une violence sexuelle. En fonction des juridictions, le terme de viol peut être seulement applicable à un abus sexuel jugé plus grave qu'une autre agression sexuelle." },
  { titre: "Volkswagen", texte: "Volkswagen est un constructeur automobile allemand. La société est créée à l'initiative de l'organisation nazie Front allemand du travail. La marque Volkswagen appartient au Groupe Volkswagen AG qui est en 2018, le premier constructeur mondial de véhicules devant Toyota avec 10,8 millions d'unités vendues." },
  { titre: "Walmart", texte: "Walmart Inc. est une multinationale américaine spécialisée dans la grande distribution, fondée par Sam Walton. Lancée en 1962, l'entreprise s'est développée en Arkansas, avant de dominer le marché américain et commencer à s'internationaliser en 1991." },
  { titre: "Warren Buffett", texte: "Warren Buffett, né le 30 août 1930 à Omaha, est un homme d'affaires, investisseur et philanthrope américain. Grâce à des investissements en bourse, il devient milliardaire dans les années 1980. Il est le directeur général de Berkshire Hathaway de 1970 à 2025." },
  { titre: "Wayne Gretzky", texte: "Wayne Gretzky, O.C. (né le 26 janvier 1961 à Brantford, ville de l'Ontario au Canada), est un joueur professionnel canadien de hockey sur glace qui possède aussi la nationalité américaine." },
  { titre: "Werner Heisenberg", texte: "Werner Heisenberg, né le 5 décembre 1901 à Wurtzbourg (Empire allemand) et mort le 1er février 1976 à Munich (Allemagne de l'Ouest), est un physicien allemand qui est l'un des fondateurs de la mécanique quantique, notamment en mettant en évidence le principe d'incertitude et en développant la formulation probabiliste" },
  { titre: "Wernher von Braun", texte: "Wernher Magnus Maximilian Freiherr von Braun, né le 23 mars 1912 à Wirsitz (Posnanie) et mort le 16 juin 1977 à Alexandria (Virginie), est un ingénieur allemand puis américain, connu pour son rôle dans le développement de la fusée." },
  { titre: "Whisky", texte: "Whisky ou whiskey est le nom générique d'un ensemble d'eaux-de-vie fabriquées par distillation de céréales maltées ou non maltées. L'origine du whisky est encore aujourd'hui sujette à controverses entre Écossais et Irlandais, chacun y allant de sa preuve la plus ancienne." },
  { titre: "Wikipédia", texte: "Wikipédia est une encyclopédie en ligne collaborative et multilingue créée par Jimmy Wales et Larry Sanger le 15 janvier 2001. Il s'agit d'une œuvre libre, c'est-à-dire que chacun peut la rediffuser gratuitement, telle quelle ou amendée, sous quelques conditions décrites par une licence libre." },
  { titre: "Xerxès Ier", texte: "Xerxès Ier, né vers 519 et mort en 465 av. J.-C., est un grand roi perse, membre de la dynastie des Achéménides et fils de Darius Ier, qui a régné de 486 à 465 av. J.-C. Manéthon l’appelle Xerxès le Grand." },
  { titre: "Yasser Arafat", texte: "Yasser Arafat, né le 24 août 1929 au Caire (Égypte) et mort le 11 novembre 2004 à Clamart (France), de son vrai nom Mohamed Abdel Raouf Arafat al-Qoudwa al-Husseini et connu aussi sous son surnom (kounya) d'Abou Ammar, est un activiste et homme d'État palestinien." },
  { titre: "Yiddish", texte: "Le yiddish, également orthographié en français yidich, d'après les recommandations de linguistes, mais aussi yidish, jiddisch, jidisch, yiddisch, idiche ou yidiche, est une langue germanique dérivée du haut allemand, avec un apport considérable de vocabulaire hébreu et slave, et des apports plus mineurs d’araméen et" },
  { titre: "Yoruba", texte: "Les Yorubas ou Yoroubas (Yorùbá) sont des habitants de l'Afrique de l'Ouest, locuteurs du yoruba, surtout présents au Nigeria, sur la rive droite du fleuve Niger, mais également au Bénin, au Ghana, au Togo, au Burkina Faso et en Côte d'Ivoire où ils sont appelés Anango." },
  { titre: "Youri Gagarine", texte: "Youri Alekseïevitch Gagarine, né le 9 mars 1934 et mort le 27 mars 1968, est un pilote et cosmonaute soviétique, premier être humain à avoir effectué un vol dans l'espace au cours de la mission Vostok 1, le 12 avril 1961, dans le cadre du programme spatial soviétique." },
  { titre: "YouTube", texte: "YouTube est un site web de type plateforme de vidéos en ligne et média social, sur lequel les utilisateurs peuvent regarder, envoyer (hébergement de fichiers vidéos), commenter, évaluer et partager des vidéos visionnables en streaming." },
  { titre: "Yukio Mishima", texte: "Yukio Mishima, nom de plume de Kimitake Hiraoka, né le 14 janvier 1925 et décédé le 25 novembre 1970, est un écrivain japonais. Auteur d'une quarantaine de romans, d'une cinquantaine de pièces de théâtre et de plus de cent-cinquante nouvelles, il est brièvement acteur et mannequin." },
  { titre: "Yves Saint Laurent", texte: "Yves Mathieu-Saint-Laurent, dit Yves Saint Laurent ou YSL (né le 1er août 1936 à Oran, et décédé le 1er juin 2008 à Paris), est un grand couturier français, créateur de collections de haute couture qui ont marqué l'histoire de la mode au XXe siècle." },
  { titre: "Zaha Hadid", texte: "Zaha Hadid, née le 31 octobre 1950 à Bagdad (Irak) et morte le 31 mars 2016 à Miami (États-Unis), est une architecte et urbaniste irako-britannique. Figure importante du courant déconstructiviste, elle est l'une des femmes architectes les plus récompensées par la profession." },
];

export const ARTICLES_DIFFICILES: Article[] = [
  { titre: "100 mètres", texte: "Le 100 mètres est une épreuve d'athlétisme consistant à parcourir, en ligne droite, un sprint sur une distance de 100 mètres. Au niveau professionnel, il est couru en moins de 10 secondes chez les hommes ainsi qu'en moins de 11 secondes chez les femmes." },
  { titre: "Abat", texte: "Les abats, souvent dénommés globalement triperie ou produits tripiers, correspondent à la partie comestible du cinquième quartier (qui comprend également des produits utilisés après transformation industrielle : issues, glandes valorisées en opothérapie, déchets divers et contenu du tube digestif) séparée de la" },
  { titre: "Abbas Kiarostami", texte: "Abbas Kiarostami, né le 22 juin 1940 à Téhéran en Iran et mort le 4 juillet 2016 à Paris en France, est un réalisateur, scénariste et producteur de cinéma iranien." },
  { titre: "Abdelaziz ibn Saoud", texte: "Abdelaziz ben Abderrahmane Al Saoud, dit Ibn Séoud ou Ibn Saoud, né le 15 janvier 1876 ou le 24 novembre 1880 à Riyad et mort le 9 novembre 1953 à Taëf, est le fondateur du troisième État saoudien, l'actuelle Arabie saoudite." },
  { titre: "Abdomen", texte: "L'abdomen (du latin, de même sens) est une partie du corps humain ou du corps d'un animal. Chez l'être humain, il est également appelé ventre." },
  { titre: "Abdülhamid II", texte: "Abdülhamid II, né le 21 septembre 1842 à Constantinople et mort le 10 février 1918 dans la même ville, est sultan ottoman et calife de l'islam de 1876 à sa déposition en 1909." },
  { titre: "Abel", texte: "Abel est un personnage de la Genèse (premier livre de la Bible), et du Coran (qui ne le cite pas nommément). Il est le deuxième fils d'Adam et Ève. Son frère aîné, Caïn, le tue par envie (différent de la jalousie) car Dieu a préféré l'offrande de son cadet à la sienne." },
  { titre: "Abricot", texte: "L'abricot est le fruit d'un arbre généralement de petite taille appelé abricotier, de la famille des Rosaceae. Le nom scientifique de l'abricotier est Prunus armeniaca (prune d'Arménie). Il appartient au sous-genre des Prunus, section Armeniaca avec les quatre autres abricotiers du monde." },
  { titre: "Absolutisme", texte: "L'absolutisme est un concept lié aux réactions de régimes politiques centraux, généralement monarchiques, visant à l'affranchissement des contrepoids (parlementaires, traditionnels ou constitutionnels) liés aux premières formes de séparation des pouvoirs qui ont suivi les formes consultatives (droit de remontrance et" },
  { titre: "Abuja", texte: "Abuja est la capitale fédérale du Nigeria depuis 1991. Située dans le Territoire de la capitale fédérale, cette ville planifiée de 713,5 km2 est au centre du pays afin d'équilibrer les pouvoirs ethniques et religieux." },
  { titre: "Acajou", texte: "L'acajou est un nom vernaculaire ambigu qui désigne un ensemble d'arbres tropicaux de la famille des Méliacées, dont la caractéristique principale est d'avoir un bois de couleur rose pâle à rouge, odorant, durable et facile à travailler." },
  { titre: "Accélérateur de particules", texte: "Un accélérateur de particules est un instrument qui utilise des champs électriques et/ou magnétiques pour amener des particules chargées électriquement à des vitesses élevées. En d'autres termes, il communique de l'énergie aux particules." },
  { titre: "Accident de la route", texte: "Un accident de la route (ou accident sur la voie publique : AVP, ou en France accident de la circulation) est une collision non intentionnelle, qui a lieu sur le réseau routier entre un engin roulant (notamment automobile, camion, moto, vélo) et tout autre véhicule ou personne ou animal, se déplaçant ou non, qui" },
  { titre: "Accordéon", texte: "L'accordéon est un instrument de musique à vent de la famille des instruments à anches libres. Le nom d'accordéon regroupe une famille d'instruments à clavier, polyphonique, utilisant des anches libres excitées par un vent variable fourni par le soufflet actionné par le musicien." },
  { titre: "Accouchement", texte: "L'accouchement est l'action de mettre un enfant au monde. Il existe deux types d'accouchements : l'accouchement par voie basse et l'accouchement par césarienne." },
  { titre: "Accra", texte: "Accra est la capitale du Ghana. En plus d'être la plus grande ville du pays, en termes d'habitants (1 658 937 habitants en 2000, 2 263 785 en 2009 et 2,721,000 en 2024), Accra est le centre politique, administratif, économique et financier du Ghana." },
  { titre: "Acide", texte: "Un acide est un composé chimique minéral ou organique accepteur, au sens large, de doublets électroniques. Il est généralement défini par des réactions-types dans différents solvants, en particulier en libérant l'ion hydronium dans l'eau." },
  { titre: "Acide acétique", texte: "L'acide éthanoïque ou acide acétique est un acide carboxylique avec une chaîne carbonée théorique en C2, analogue à l'éthane, de formule semi-développée CH3-CO-OH ou courte AcOH, où Ac signifie « CH3CO », du groupe acétyle." },
  { titre: "Acide borique", texte: "L'acide borique, aussi appelé acide boracique ou acide orthoborique, est un composé chimique de formule brute H3BO3 ou structurelle B(OH)3, nommé autrefois sassoline en Italie centrale, où il jaillit à l'état naturel dans les fumerolles brûlantes et se dépose avec les autres vapeurs condensées dans les lagoni de" },
  { titre: "Acide citrique", texte: "L'acide citrique est un acide tricarboxylique α-hydroxylé présent en abondance dans le citron, d'où son nom. Il s'agit d'un acide faible qui joue un rôle important en biochimie comme métabolite du cycle de Krebs, une voie métabolique majeure chez tous les organismes aérobies." },
  { titre: "Acide lactique", texte: "Les acides lactiques (acides hydroxypropanoïques) sont des acides organiques dont la chaîne est composée de trois atomes de carbone. Les ions lactate sont les bases conjuguées de ces acides (autrement dit, la forme ionisée des acides lactiques)." },
  { titre: "Acide nitrique", texte: "L’acide nitrique est un composé chimique de formule HNO3. Liquide incolore lorsqu'il est pur, cet acide minéral fort (de pKa = −1,37) est en pratique utilisé en solution aqueuse concentrée." },
  { titre: "Acide phosphorique", texte: "L’acide phosphorique (ou acide orthophosphorique) est un composé chimique de formule H3PO4. C'est un oxoacide trifonctionnel (triacide) important en chimie minérale et fondamental en biochimie. Il s'agit d'un acide minéral obtenu par traitement de roches phosphatées ou par combustion du phosphore." },
  { titre: "Acide ribonucléique", texte: "L'acide ribonucléique ou ARN est un acide nucléique présent chez pratiquement tous les êtres vivants, et aussi chez certains virus. L'ARN est très proche chimiquement de l'ADN et il est d'ailleurs en général synthétisé dans les cellules à partir d'un segment d'ADN matrice dont il est une copie." },
  { titre: "Acide sulfurique", texte: "L’acide sulfurique, appelé jadis huile de vitriol ou vitriol fumant, est un composé chimique de formule H2SO4. C'est un acide minéral dont la force (pKa = –3,0) est seulement dépassée par les superacides." },
  { titre: "Aconcagua", texte: "L'Aconcagua est un sommet d'Argentine situé à treize kilomètres de la frontière chilienne et s'élevant à 6 962 mètres d'altitude. Surnommé le « colosse de l'Amérique », il constitue le point culminant de la cordillère des Andes, du continent, de l'hémisphère austral et la plus haute montagne en dehors de l'Asie." },
  { titre: "Acre", texte: "L'acre (nom féminin : une acre) est une unité de mesure de superficie utilisée en Grande-Bretagne, en Irlande et anciennement dans le nord-ouest de la France, plus particulièrement en Normandie. Sa valeur a varié suivant l'époque et les régions." },
  { titre: "Acupuncture", texte: "L’acupuncture ou acuponcture (du latin médical du XVIIe siècle « acupunctura » formé de acus, « aiguille », et punctura, « piqûre ») est une pseudo-médecine dont les origines historiques sont liées à la tradition médicale chinoise." },
  { titre: "Adansonia", texte: "Adansonia, l'Adansonie, est un genre de plantes à fleurs de la famille des Bombacaceae selon l'ancienne classification classique, ou de celle des Malvaceae selon la classification phylogénétique, communément appelés Baobabs, ou parfois Arbres bouteilles." },
  { titre: "Addiction", texte: "L'addiction, dépendance, ou assuétude, est l'envie répétée et irrépressible de faire ou de consommer quelque chose en dépit de la motivation et des efforts du sujet pour s'y soustraire." },
  { titre: "Addis-Abeba", texte: "Addis-Abeba est la capitale de l'Éthiopie. Cette ville d'une superficie de 526,47 km2, peuplée de plus de trois millions d'habitants, accueille, depuis 1963, le siège de l'Union africaine." },
  { titre: "Adélaïde", texte: "Adélaïde est la capitale de l'Australie-Méridionale. Avec une agglomération de 1 304 600 habitants en 2014, elle est la cinquième ville d'Australie." },
  { titre: "Aden", texte: "Aden est une ville du Yémen, située à 170 km à l'est du détroit Bab-el-Mandeb. Elle est peuplée d'environ 990 000 habitants. C'est aussi un port naturel, construit sur un ancien site volcanique, déjà utilisé par le royaume antique d'Awsân entre les VIIe et Ve siècles av. J.-C.." },
  { titre: "Adrénaline", texte: "L’adrénaline est un neurotransmetteur et une hormone appartenant à la famille des catécholamines. Cette molécule porte aussi le nom d’épinéphrine." },
  { titre: "Adulte", texte: "Dans son sens le plus général, un adulte (du latin ădultus, a, um, « crû, grandi, développé », participe passé d'ădŏlēscĕre dont le présent est ădŏlēscēns, -centĭa) est un individu biologiquement stable qui, ayant acquis sa maturité sexuelle, est susceptible de se reproduire." },
  { titre: "Adultère", texte: "L'adultère (nom masculin) est « le fait pour un époux ou une épouse de violer son serment de fidélité, de partage, et d'avoir des relations sexuelles avec une personne autre que son conjoint envers qui il a affirmé ce serment »." },
  { titre: "Adventice", texte: "Une adventice (du latin adventicius, « qui vient de l'extérieur ») désigne pour les agriculteurs et les jardiniers, une plante qui pousse dans un milieu aménagé (champ, massif, etc.) sans y avoir été intentionnellement introduite." },
  { titre: "Afrique centrale", texte: "L'Afrique centrale est une région d'Afrique comprenant le Sud du Sahara, l'Est du bouclier ouest-africain et l'Ouest de la vallée du Grand Rift." },
  { titre: "Aïd el-Fitr", texte: "Aïd el-Fitr est la fête musulmane marquant la rupture du jeûne du mois de ramadan. Elle est célébrée le premier jour du mois de chawwal. Elle est aussi parfois appelée aïd as-Seghir, « la petite fête », par opposition à l'aïd al-Kebir, « la grande fête »." },
  { titre: "Akkadien", texte: "L'akkadien (akkadū(m) en akkadien) est une langue chamito-sémitique éteinte, de la famille des langues sémitiques, fortement influencée par le sumérien. Elle est parlée en Mésopotamie au moins du début du IIIe jusqu'au Ier millénaire av. J.-C." },
  { titre: "Al-Hussein ibn Ali", texte: "Al-Hussein ibn Ali, dit aussi Sayyid al-Chouhada ((ar) سَيِّد الشُهَداء, prince des martyrs), né le 1er mars 625 à Médine et mort le 10 octobre 680 lors de la bataille de Kerbala, est le fils d'Ali ibn Abi Talib et de Fatima Zahra ; par celle-ci il est aussi le petit-fils de Mahomet." },
  { titre: "Al-Khwârizmî", texte: "Muḥammad ibn Mūsā al-Khwārizmī, généralement appelé Al-Khwârizmî, latinisé en Algoritmi ou Algorizmi, né dans les années 780, probablement à Khiva dans la région du Khwarezm (d'où il prend son nom), dans l'actuel Ouzbékistan, mort vers 850 à Bagdad, est un mathématicien, géographe, astrologue et astronome, membre de" },
  { titre: "Alains", texte: "Les Alains sont un ancien peuple de culture guerrière, nomades puis sédentarisés, largement établis en Ciscaucasie centrale (correspondant aux territoires des républiques caucasiennes du Nord)." },
  { titre: "Alcaloïde", texte: "Les alcaloïdes sont des molécules à bases azotées, le plus souvent hétérocycliques, très majoritairement d'origine végétale. Ils peuvent se présenter sous forme de molécules organiques hétérocycliques azotées basiques." },
  { titre: "Alcool", texte: "En chimie organique, un alcool est un composé organique dont l'un des atomes de carbone (celui-ci étant tétraédrique) est lié à un groupe hydroxyle (-OH). Il existe de nombreux alcools différents, allant des plus simples comme l'éthanol et le méthanol, aux plus complexes, comme le cholestérol." },
  { titre: "Alcoolisme", texte: "L'alcoolisme, alcoolodépendance, éthylisme ou troubles liés à l'usage de l'alcool (abrégé en TUA), est l'addiction à l'éthanol (alcool éthylique) contenu dans les boissons alcoolisées." },
  { titre: "Alep", texte: "Alep est une ville de Syrie, chef-lieu du gouvernorat d'Alep, le gouvernorat de Syrie le plus peuplé, situé dans le nord-ouest du pays. Pendant des siècles, Alep a été la ville la plus grande de la région syrienne et la troisième plus grande ville de l'Empire ottoman (après Constantinople et Le Caire)." },
  { titre: "Alexandre II", texte: "Alexandre II (Moscou, 29 avril 1818 – Saint-Pétersbourg, 13 mars 1881), empereur de Russie (3 mars 1855 – 13 mars 1881), dit « le Libérateur », est également grand-duc de Finlande et roi de Pologne jusqu'en 1867, date à laquelle la Pologne est formellement annexée par l'Empire russe." },
  { titre: "Alexandre Nevski", texte: "Alexandre Nevski, né le 30 mai 1220 à Pereslavl-Zalesski et mort le 14 novembre 1263 à Gorodets, est un prince de Novgorod puis Grand-prince de Vladimir-Souzdal célèbre pour ses victoires militaires." },
  { titre: "Algèbre", texte: "L'algèbre est une branche des mathématiques qui permet d'exprimer les propriétés des opérations et le traitement des équations. Selon l’époque et le niveau d’études considérés, elle peut être décrite comme :" },
  { titre: "Algèbre de Boole", texte: "L'algèbre de Boole, ou calcul booléen, est la partie des mathématiques qui s'intéresse à une approche algébrique de la logique, vue en termes de variables, d'opérateurs et de fonctions sur les variables logiques, ce qui permet d'utiliser des techniques algébriques pour traiter les expressions à deux valeurs du calcul" },
  { titre: "Algue", texte: "Les algues /alg/ sont des organismes vivants capables de produire de la photosynthèse oxygénique et dont le cycle de vie se déroule généralement en milieu aquatique. Elles constituent une part très importante de la biodiversité et la base principale des chaînes alimentaires des eaux douces, saumâtres et marines." },
  { titre: "Alibaba Group", texte: "Alibaba Group est une société chinoise cotée en bourse qui tire principalement ses revenus de ses activités sur Internet, dont un marché public destiné à faciliter les échanges entre entreprises (qu'ils soient internationaux ou chinois), des plateformes de paiements et de ventes au détail, un moteur de recherche pour" },
  { titre: "Alizé", texte: "L'alizé est un vent régulier des régions intertropicales (entre 23°27 nord et 23°27 sud), soufflant d'est en ouest de façon régulière des hautes pressions subtropicales (crête subtropicale) vers les basses pressions équatoriales (zone de convergence intertropicale)." },
  { titre: "Allen Ginsberg", texte: "Irwin Allen Ginsberg, né le 3 juin 1926 à Newark et mort le 5 avril 1997 à New York, est un poète américain, membre fondateur de la Beat Generation, du mouvement hippie et de la contre-culture américaine." },
  { titre: "Alliage", texte: "En métallurgie, un alliage est un mélange de plusieurs éléments chimiques, dont le principal constituant est un métal, et dont les caractéristiques sont celles d'un matériau métallique." },
  { titre: "Alligator", texte: "Les alligators forment un genre de crocodiliens de la famille des Alligatoridae. Ce terme constitue à la fois un nom vernaculaire et un nom scientifique." },
  { titre: "Allosaurus", texte: "Allosaurus, également francisé allosaure, est un genre fossile de grands dinosaures théropodes ayant vécu durant les étages Kimméridgien et Tithonien du Jurassique supérieur, il y a entre 155 et 145 millions d’années, dans ce qui sont actuellement l'Amérique du Nord et l'Europe." },
  { titre: "Almaty", texte: "Almaty, nommée succesivement Vernoye (1854–1867), Verny (1867–1921), Alma-Ata (1921–1993) et Almaty depuis 1993. est la principale ville du Kazakhstan et son ancienne capitale, de 1929 à 1997." },
  { titre: "Aloès", texte: "Aloe est un genre de plantes succulentes, les aloès, originaires d'Afrique, de Madagascar et les îles Mascareines, de la péninsule arabique et Socotra." },
  { titre: "Alpaga", texte: "L'alpaga, ou encore alpaca (Vicugna pacos), est un mammifère domestique de la famille des camélidés, surtout présent en Amérique du Sud, particulièrement au Pérou, et originaire de la Cordillère des Andes." },
  { titre: "Alphabet phénicien", texte: "L'alphabet phénicien (appelé par convention alphabet protocananéen pour les inscriptions antérieures à 1200 av. J.-C.) est un ancien abjad, un alphabet consonantique non pictographique." },
  { titre: "Alphonse Ier", texte: "Alphonse Ier, aussi connu sous le nom d'Alphonse Henriques (Afonso Henriques), signifiant « Alphonse, fils d'Henri », surnommé « le Conquérant », « le Fondateur » ou « le Grand », né le 25 juillet 1109 à Viseu ou Guimaraes, mort le 6 décembre 1185 à Coimbra, est comte régnant de 1128 à 1139 puis premier roi de" },
  { titre: "Alto", texte: "L'alto est un instrument à cordes frottées, plus grave, plus grand et plus épais que le violon, plus aigu, plus petit et plus fin que le violoncelle. Muni de quatre cordes (do, sol, ré et la), sa gamme de fréquences fondamentales va de 128 à 2 600 Hz." },
  { titre: "Amaterasu", texte: "Amaterasu est, dans le shintoïsme, la déesse du Soleil, et la plus importante divinité de cette religion. Selon la mythologie, elle a donné naissance à la lignée de tous les empereurs japonais. Elle aurait introduit la riziculture, la culture du blé et les vers à soie." },
  { titre: "Ambroise de Milan", texte: "Ambroise de Milan ou saint Ambroise, dont le nom romain en latin est Aurelius Ambrosius, né en 339 à Trèves dans l'Empire romain d'Occident (aujourd'hui en Allemagne) et mort le 4 avril 397 à Milan, évêque de Milan de 374 à sa mort, docteur de l'Église, est l'un des quatre pères de l'Église d'Occident, avec Augustin" },
  { titre: "Amon", texte: "Amon est l’une des principales divinités du panthéon égyptien, dieu de Thèbes. Son nom Imen, « le Caché » ou « l’Inconnaissable », traduit l’impossibilité de connaître sa « vraie » forme, car il se révèle sous de nombreux aspects." },
  { titre: "Ancien Empire", texte: "L'Ancien Empire égyptien est une période de l'histoire de l'Égypte antique qui couvre approximativement la moitié du troisième millénaire (d'environ 2700 à 2200) avant notre ère." },
  { titre: "André Vésale", texte: "André Vésale, de son nom latin Andreas Vesalius, de son nom de naissance Andreas Wytinck van Wesel (né le 31 décembre 1514 à Bruxelles et mort à Zante en Grèce le 15 octobre 1564) est un anatomiste et médecin brabançon." },
  { titre: "André-Marie Ampère", texte: "André-Marie Ampère (Lyon, 20 janvier 1775 – Marseille, 10 juin 1836) est un mathématicien, physicien, chimiste et philosophe français. Il a été membre de l'Académie des sciences, ainsi que professeur à l'École polytechnique et au Collège de France." },
  { titre: "Andrew Carnegie", texte: "Andrew Carnegie, né le 25 novembre 1835 à Dunfermline en Écosse (Royaume-Uni) et mort le 11 août 1919 à Lenox (dans sa propriété de Shadow Brook) dans le Massachusetts (États-Unis) d'une pneumonie, est un industriel et philanthrope écossais naturalisé américain." },
  { titre: "Anévrisme", texte: "Un anévrisme ou anévrysme est une dilatation localisée de la paroi d'une artère aboutissant à la formation d'une poche de taille variable, communiquant avec l'artère au moyen d'une zone rétrécie que l'on nomme le « collet »." },
  { titre: "Angkor Vat", texte: "Angkor Vat ou Angkor Wat (en khmer : ប្រាសាទអង្គរវត្ត, Prasat Angkor Vat) est le plus grand temple du complexe monumental d'Angkor, au Cambodge, réparti sur un site de 162,6 hectares." },
  { titre: "Anglo-Saxons", texte: "Les Anglo-Saxons sont un peuple d'origine germanique qui s'installe en Grande-Bretagne à partir du Ve siècle. La période anglo-saxonne de l'histoire de l'Angleterre s'étend traditionnellement jusqu'à la conquête normande, en 1066." },
  { titre: "Animation", texte: "L'animation, dans le domaine de l'audiovisuel, est un ensemble de techniques qui ont été mises au point à partir du XIXe siècle, d'abord par la reprise du principe de la bande dessinée et l'utilisation de procédés optiques et mécaniques ne dépassant pas deux secondes dans leur représentation (jouet optique," },
  { titre: "Ankara", texte: "Ankara — anciennement appelée Angora et Ancyre durant l'Antiquité — est la capitale de la Turquie depuis le 13 octobre 1923 et, par sa population, la deuxième ville du pays, après Istanbul. Elle est située en Région de l'Anatolie centrale." },
  { titre: "Anna Akhmatova", texte: "Anna Akhmatova, nom de plume d'Anna Andreïevna Gorenko (en russe : Анна Андреевна Горенко, /ˈanːə ɐnˈdrʲe(j)ɪvnə ɡɐˈrʲɛnkə/ ), née le 11 juin 1889 (23 juin dans le calendrier grégorien) à Odessa et morte le 5 mars 1966 à Moscou, est une des plus importantes poétesses russes du XXe siècle." },
  { titre: "Anna Freud", texte: "Anna Freud, née le 3 décembre 1895 à Vienne et morte le 9 octobre 1982 à Londres, est une psychanalyste, née en Autriche, puis exilée en Angleterre en 1938, et naturalisée britannique. Elle est la fille du psychanalyste Sigmund Freud." },
  { titre: "Anna Pavlova", texte: "Anna Pavlovna Pavlova, simplement dite Anna Pavlova, est une ballerine russe, née Anna Matveïevna Pavlova le 12 février 1881 (31 janvier dans le calendrier julien) à Saint-Pétersbourg (Russie) et morte le 23 janvier 1931 à La Haye (Pays-Bas)." },
  { titre: "Antalya", texte: "Antalya est une ville portuaire, ancienne, développée, très peuplée, du Sud-Ouest de la Turquie, dans la préfecture de la province du même nom, sur la Riviera turque (Côte Turquoise), au sud de l'Anatolie." },
  { titre: "Ante Pavelić", texte: "Ante Pavelić est un homme d'État croate, né le 14 juillet 1889 à Bradina (village de Bosnie-Herzégovine, alors en Autriche-Hongrie) et mort le 28 décembre 1959 à Madrid (Espagne)." },
  { titre: "Anticléricalisme", texte: "L'anticléricalisme est un système opposé aux tendances du clergé. D'après Françoise Marcard, l'anticléricalisme s'oppose au cléricalisme, « sachant qu'il y a présomption de cléricalisme chaque fois que le fait religieux transgresse les frontières du terrain dit temporel »." },
  { titre: "Anticyclone", texte: "Un anticyclone est une zone fermée de pressions atmosphériques élevées relativement à celles du voisinage. C'est le système inverse d'un cyclone, d'où son nom." },
  { titre: "Antimatière", texte: "En physique des particules, l'antimatière est l'ensemble des antiparticules qui possèdent la même masse et le même spin que les particules ordinaires, mais des charges, des nombres baryoniques et des nombres leptoniques opposés." },
  { titre: "Antiquité tardive", texte: "L’Antiquité tardive est une période de l’histoire européenne et méditerranéenne qui commence à la fin du IIIe siècle mais dont le terme est flou." },
  { titre: "Apennins", texte: "Les Apennins (ou l'Apennin ; en italien Appennino) sont une chaîne de montagnes de la ceinture alpine qui parcourent l'Italie et Saint-Marin sur mille kilomètres du nord au sud, à travers quinze des vingt régions italiennes." },
  { titre: "Apiaceae", texte: "Les Apiaceae, en français Apiacées, anciennement Umbelliferae, les Ombellifères, sont une famille de plantes dicotylédones de l'ordre des Apiales. Les espèces présentent quatre caractéristiques :" },
  { titre: "Apis mellifera", texte: "L'Abeille européenne, Avette ou Mouche à miel (Apis mellifera) est une abeille à miel originaire d'Europe. Elle est considérée comme semi-domestique. C'est une des abeilles élevées à grande échelle en apiculture pour produire du miel et pour la pollinisation." },
  { titre: "Apoptose", texte: "L'apoptose (du grec : apo, « au loin » et ptosis, « chute ») (ou mort cellulaire programmée) est le processus par lequel des cellules déclenchent leur autodestruction en réponse à un signal." },
  { titre: "Appareil urinaire", texte: "L’appareil urinaire du système excréteur est l’appareil permettant l’évacuation des produits du catabolisme d'un vertébré sous une forme liquide, l'urine, et assure par conséquent l'épuration du sang ainsi que le maintien de l'homéostasie au sein de l'organisme." },
  { titre: "Aquarelle", texte: "L'aquarelle est une peinture à l'eau sur papier, dont le liant est à base de gomme arabique. Le même mot s'emploie pour la matière et pour l'ouvrage peint." },
  { titre: "Aqueduc", texte: "Un aqueduc est un canal artificiel, cheminant en souterrain, à même le sol ou en aérien, ouvert ou fermé, destiné au transport de l’eau pour l’approvisionnement d’une population, l’irrigation ou autres usages, industriels notamment." },
  { titre: "Arabe", texte: "L'Arabe est une race de chevaux de selle originaire du Moyen-Orient, caractérisée par sa tête au profil concave et son port de queue relevé. L'évolution de cette race peut être retracée sur plus de 2 000 ans grâce à des documents iconographiques et des trouvailles archéologiques." },
  { titre: "Arabie", texte: "L'Arabie ou péninsule Arabique (شبه الجزيرة العربية (shibh al-jazīra al-ʿarabiya) « la presqu'île arabe » ou جزيرة العرب (jazīratu Al-ʿArab) « la presqu'île des Arabes »), est une vaste péninsule située au sud-ouest de l'Asie, à la jonction entre ce continent et l'Afrique." },
  { titre: "Arachnida", texte: "Les Arachnides (Arachnida) sont une classe d'arthropodes chélicérés, terrestres ou aquatiques, souvent insectivores. C'est le groupe qui comprend, entre autres, les ordres des Araignées, des Scorpions, des Acariens et des Opilions." },
  { titre: "Arapaima gigas", texte: "Arapaima gigas, communément appelé Arapaïma, Pirarucu ou Paiche, est une espèce de poissons d'eau douce de la famille des Arapaimidae, vivant en Amazonie. C'est le plus gros poisson d'eau douce d'Amérique du Sud et c'est un des dix plus gros poissons d'eau douce de la planète." },
  { titre: "Arbalète", texte: "L'arbalète (du latin arcuballista) est une arme de trait, constituée d'un arc monté sur un fût et lançant des projectiles appelés « carreaux ». Sa puissance et sa précision sont supérieures à celles d'un arc classique, mais la durée nettement plus longue de son rechargement la pénalise." },
  { titre: "Arbre", texte: "Un arbre (du latin arbor) est une plante ligneuse terrestre comportant un tronc sur lequel s'insèrent des branches ramifiées portant le feuillage dont l'ensemble forme le houppier, appelé aussi couronne." },
  { titre: "Archaea", texte: "Les Archaea ou Archées, du grec ancien ἀρχαῖος / arkhaîos (« originel, primitif »), anciennement archéobactéries, sont des micro-organismes unicellulaires procaryotes, c'est-à-dire des organismes constitués, comme les bactéries, d'une cellule unique qui ne comprend ni noyau ni organites, à la différence des eucaryotes." },
  { titre: "Archaeopteryx", texte: "Archaeopteryx (« aile antique », en français archæoptéryx ou archéoptéryx) est un genre fossile de dinosaures à plumes disparus. Ces dinosaures aviens, d’une longueur inférieure à 60 cm, ont vécu à la fin du Jurassique, il y a 156 à 150 Ma dans un environnement alors insulaire, qui se situe actuellement en Allemagne." },
  { titre: "Archéologie", texte: "L'archéologie est une discipline scientifique dont l'objectif est d'étudier l'être humain à travers l'ensemble des vestiges matériels (artéfacts et faits archéologiques) ayant subsisté au cours des siècles." },
  { titre: "Archipel", texte: "Un archipel est un ensemble d'îles relativement proches les unes des autres. La proximité se double le plus souvent d'une origine géologique commune, en général volcanique." },
  { titre: "Architecture", texte: "L'architecture est l'art majeur de concevoir des espaces et de bâtir des édifices, en respectant des règles de construction empiriques ou scientifiques, ainsi que des concepts esthétiques, classiques ou nouveaux, de forme et d'agencement d'espace, en y incluant les aspects sociaux et environnementaux liés à la" },
  { titre: "Ardoise", texte: "L’ardoise, appelée parfois phyllade, est une roche métamorphique issue d'une argile ayant subi un métamorphisme général faible. Elle appartient à la famille des schistes, à l'intérieur de laquelle elle se distingue par sa résistance, la qualité de son grain (très fin et homogène), son aspect satiné et sa fissilité." },
  { titre: "Arequipa", texte: "Arequipa est une ville du sud du Pérou et la capitale de la province d'Arequipa et du département d'Arequipa. Avec une population projetée de 1 195 700 habitants en 2025, elle est la deuxième ville la plus peuplée du pays après Lima." },
  { titre: "Argon", texte: "L'argon est l'élément chimique de numéro atomique 18 et de symbole Ar. Il appartient au groupe 18 du tableau périodique et fait partie de la famille des gaz nobles, également appelés « gaz rares », qui regroupe également l'hélium, le néon, le krypton, le xénon et le radon." },
  { titre: "Arme à feu", texte: "Une arme à feu est une arme visant originellement à toucher une cible via des projectiles à haute vélocité, au moyen de gaz produits par une déflagration, combustion rapide et confinée d'un composé chimique détonant." },
  { titre: "Arsenic", texte: "L'arsenic est l'élément chimique de numéro atomique 33, noté par le symbole As. Son corps simple se présente sous la forme d'un solide cristallin argenté." },
  { titre: "Art martial", texte: "Un art martial est un style ou une école dont l’enseignement porte principalement sur des techniques de combat, à mains nues ou avec une arme." },
  { titre: "Art roman", texte: "En histoire de l'art, la période de l'art roman est celle qui s'étend du début du XIe siècle au XIIIe siècle, entre l'art préroman et l'art gothique, en Europe. L'expression « art roman » est forgée en 1818 par l'archéologue français Charles de Gerville et passe dans l'usage courant à partir de 1835." },
  { titre: "Arthrite", texte: "L’arthrite (du grec arthron : « articulation ») est une inflammation aiguë ou chronique des articulations. Elle ne désigne pas la pathologie répertoriée sous le nom d’arthrose, mais un signe clinique associé à de nombreuses maladies articulaires." },
  { titre: "Artillerie", texte: "L'artillerie est l'ensemble des armes collectives ou lourdes — ou des troupes qui mettent en œuvre ces armes — servant à envoyer, à courte, moyenne ou grande distance, sur l'ennemi ou sur ses positions et ses équipements, divers projectiles de moyen ou gros calibre : obus, boulet, roquette, missile, pour appuyer ses" },
  { titre: "Artiste", texte: "Un artiste est un individu faisant une œuvre, cultivant ou maîtrisant un art, un savoir-faire, une technique, et dont on remarque entre autres la créativité, l'inventivité, l'originalité de sa production, de ses actes, de ses gestes." },
  { titre: "Arts", texte: "Les arts représentent une forme de l'expression du vivant, généralement influencée par la culture et entraînée par une impulsion créatrice. Un art est un moyen de transmettre un contenu intellectuel ou ayant un impact émotionnel grâce à certains procédés techniques qui varient selon les arts." },
  { titre: "Ascenseur", texte: "Un ascenseur est un dispositif de déplacement vertical, situé dans un édifice, permettant le transport sécurisé de personnes. Plus globalement on parle de monte-charge ou d'élévateur. Sa conception, sa construction, son contrôle à l'usage, sa maintenance sont réglementés." },
  { titre: "Asie centrale", texte: "L'Asie centrale est une sous-région du continent asiatique qui s'étend de la mer Caspienne à l'ouest à la Mongolie à l'est, et de la Russie au nord à l'Iran et l'Afghanistan au sud." },
  { titre: "Asie de l'Est", texte: "L'Asie de l'Est (ou Asie orientale) est une région d'Asie, comprenant : la Chine, la Corée (Corée du Nord et Corée du Sud), le Japon, la Mongolie (parfois rattachée à l'Asie centrale), Taïwan, éventuellement le Viêt Nam et Singapour, pour des raisons culturelles (ces pays sont plus généralement rattachés à l'Asie du" },
  { titre: "Assembleur", texte: "Un langage d'assemblage ou langage assembleur est, en programmation informatique, le langage de plus bas niveau qui représente le langage machine sous une forme lisible par un humain. Les combinaisons de bits du langage machine sont représentées par des symboles dits « mnémoniques », c'est-à-dire faciles à retenir." },
  { titre: "Assurbanipal", texte: "Assurbanipal (aussi Aššurbanipal, Assourbanipal) en akkadien : Aššur-bāni-apli ce qui signifie « Le dieu Assur a fait un fils » ou « Assur est le créateur d'un héritier », en français connu sous le nom de Sardanapale, fut roi d'Assyrie de 669 av. J.-C. à 631 av. J.-C. ou 627 av. J.-C. Il était le fils du roi" },
  { titre: "Astéroïde", texte: "Un astéroïde est une planète mineure composée de roches, de métaux et de glaces, et dont les dimensions varient de l'ordre du mètre (limite actuelle de détection) à plusieurs centaines de kilomètres." },
  { titre: "Astor Piazzolla", texte: "Ástor Piazzolla, né le 11 mars 1921 à Mar del Plata et mort le 4 juillet 1992 à Buenos Aires, est un compositeur et bandonéoniste argentin. Il est considéré comme le musicien le plus important de la seconde moitié du XXe siècle pour la musique de tango." },
  { titre: "Astrid Lindgren", texte: "Astrid Lindgren, née Ericsson le 14 novembre 1907 à Vimmerby et morte le 28 janvier 2002 à Stockholm, est une romancière et scénariste suédoise. Autrice d'ouvrages pour enfants, elle est notamment connue à travers le monde pour avoir créé les personnages Fifi Brindacier et Zozo la tornade." },
  { titre: "Astronaute", texte: "Un astronaute est une personne qui effectue ou a effectué un vol spatial, autant qu'une personne dont c'est la profession. L'activité d'envoyer des êtres humains dans l'espace constitue le vol spatial habité, principalement à l'initiative des États." },
  { titre: "Athanase d'Alexandrie", texte: "Athanase d'Alexandrie, né vers 296/298 et mort le 2 mai 373, dit le Grand, est évêque (patriarche) d'Alexandrie du 8 juin 328 à sa mort. Sa personne est au cœur des controverses entre Orient et Occident." },
  { titre: "Athlétisme", texte: "L’athlétisme est un ensemble d’épreuves sportives codifiées comprenant les courses, sauts, lancers, épreuves combinées et marche. Il s’agit de l’art de dépasser la performance des adversaires en vitesse ou en endurance, en distance ou en hauteur." },
  { titre: "Attirance sexuelle", texte: "L'attirance sexuelle (ou attraction sexuelle) est l'attirance, entre deux individus d'une espèce utilisant la reproduction sexuée, qui les pousse à réaliser la copulation ou des activités érotiques." },
  { titre: "Au cœur des ténèbres", texte: "Au cœur des ténèbres (Heart of Darkness) est un roman court de l'auteur écrivain polonais et britannique Joseph Conrad, paru dans la revue Blackwood's Magazine en 1899. En 1902, il est publié dans un recueil de trois récits, Youth : A Narrative, and Two Other Stories (Jeunesse)." },
  { titre: "Auguste Comte", texte: "Auguste Comte, né Isidore Marie Auguste François Xavier Comte le 19 janvier 1798 (30 nivôse an VI) à Montpellier et mort le 5 septembre 1857 à Paris, est un philosophe et sociologue français, fondateur du positivisme." },
  { titre: "Autobus", texte: "Un autobus est un véhicule de transport routier de voyageurs en milieu urbain/périurbain et suburbain. C'est l'un des principaux types de véhicules employés dans les transports en commun." },
  { titre: "Autoroute", texte: "Une autoroute est une voie de communication routière à chaussées séparées, réservée à la circulation à vitesse élevée des véhicules motorisés (automobiles, motos, camions et autocars)." },
  { titre: "Avars", texte: "Les Avars ou Avares étaient une alliance de plusieurs groupes de nomades eurasiens, parfois qualifiés de « turco-mongols », et issus de la confédération des Ruanruan qui menaçait la Chine au IIIe siècle." },
  { titre: "Avion de chasse", texte: "Un avion de chasse (aussi appelé chasseur ou avion de suprématie aérienne) est un avion militaire conçu pour intercepter les avions adverses et ainsi assurer la maîtrise du ciel." },
  { titre: "Aviron", texte: "L'aviron fait partie de la famille des sports nautiques. C'est un sport olympique depuis la création des Jeux olympiques modernes en 1896 sous l'impulsion du baron Pierre de Coubertin." },
  { titre: "Avocat", texte: "En droit, l'avocat est un juriste dont les fonctions traditionnelles sont de conseiller, représenter, d'assister et de défendre ses clients, personnes physiques ou morales, en justice, en plaidant pour faire valoir leurs droits." },
  { titre: "Ayurveda", texte: "L'ayurveda est une forme de médecine traditionnelle non conventionnelle originaire de l'Inde mais également pratiquée dans d'autres parties du monde, notamment en Occident, les institutions académiques indiennes liées aux médecines traditionnelles ayant contribué à lui donner une visibilité internationale." },
  { titre: "Babouin", texte: "Le Papion (Papio), plus communément désigné sous le nom de Babouin, est un genre de singes de la famille des cercopithécidés répandus en Afrique subsaharienne et au sud de la péninsule Arabique." },
  { titre: "Bacillariophyta", texte: "Les Bacillariophyta, ou Diatomées, sont un embranchement d'eucaryotes unicellulaires (de deux micromètres à un millimètre) présents dans tous les milieux aquatiques et majoritaires dans certains biofilms (avec une préférence pour les eaux froides) et enveloppés par un squelette externe siliceux nommé frustule." },
  { titre: "Bactriane", texte: "La Bactriane ou Bactrie est une région historique d'Asie centrale située entre les montagnes de l'Hindou Kouch et le fleuve Amou-Daria, aujourd'hui partagée entre l'Afghanistan, le Tadjikistan, l'Ouzbékistan et le nord-ouest du Pakistan." },
  { titre: "Badminton", texte: "Le badminton est un sport de raquette nommé d'après le château anglais de Badminton House où il a été codifié à la fin du XIXe siècle, sur la base de pratiques plus anciennes en Europe et en Asie." },
  { titre: "Baiser", texte: "Le baiser (ou bisou dans le langage enfantin) est un mouvement qui consiste à toucher une personne avec ses lèvres grâce aux muscles orbiculaires des lèvres. Il peut s’agir d’un comportement social (le baise-main ou la bise), affectueux ou amoureux." },
  { titre: "Bali", texte: "Bali, en indonésien Provinsi Bali (Province de Bali), est l'une des 38 provinces d'Indonésie. Située dans l'archipel des petites îles de la Sonde, elle inclut Bali et 84 autres petites îles voisines. En 2023, sa population est de 4 344 554 habitants." },
  { titre: "Ballet", texte: "Le ballet est un genre dramatique dont l'action est figurée par des pantomimes et des danses. Ses origines remontent à la Renaissance italienne (XVe siècle). Primitivement développé dans les cours d'Italie, le ballet a reçu ses lettres de noblesse en France, puis en Russie, en tant que danse-spectacle." },
  { titre: "Banlieue", texte: "La banlieue, parfois aussi appelée première couronne, est la ceinture urbaine qui entoure une ville-centre. Elle est principalement résidentielle bien qu'elle puisse également inclure des espaces commerciaux." },
  { titre: "Barranquilla", texte: "Barranquilla est une ville du nord de la Colombie et la capitale du département d'Atlántico. Elle se situe sur la rive occidentale du río Magdalena, le fleuve le plus important de Colombie, à 7,5 km de son embouchure sur la mer des Caraïbes, ou mer des Antilles, dépendance de l'océan Atlantique." },
  { titre: "Basques", texte: "Les Basques constituent un peuple autochtone implanté principalement dans le Pays basque, à cheval sur le sud-ouest de la France et le nord de l'Espagne. Une forte émigration historique a engendré une diaspora basque, principalement établie en Amérique du Sud." },
  { titre: "Bassorah", texte: "Bassorah est la deuxième ville d’Irak, après Bagdad, la capitale, avec une population estimée en 2008 à environ 2 300 000 habitants. C'est la capitale de la province d'Al-Basra." },
  { titre: "Bataille d'Angleterre", texte: "La bataille d'Angleterre (nom français pour l'anglais : Battle of Britain), qui s'est déroulée de juillet 1940 à octobre 1940, suivie par le blitz jusqu'à mai 1941, opposa principalement les Britanniques aux Allemands au moyen de l'aviation et marqua une étape décisive dans le cours de la Seconde Guerre mondiale," },
  { titre: "Bataille de l'Atlantique", texte: "L'expression « bataille de l'Atlantique » désigne l'ensemble des combats qui ont eu lieu dans l'Atlantique nord, pendant la Seconde Guerre mondiale. La paternité de l'expression est attribuée à Winston Churchill." },
  { titre: "Baybars", texte: "Baybars, de son nom complet Al-Malik az-Zâhir Rukn ad-Dîn Baybars al-Bunduqdari, né le 19 juillet 1223 dans les steppes situées au nord de la mer Noire et mort le 1er juillet 1277 à Damas, d'origine turque kiptchake, est le quatrième sultan d'Égypte et de Syrie de la dynastie des Mamelouks Bahrites." },
  { titre: "Béla Bartók", texte: "Béla Bartók (prononciation : /ˈbeːlɒ ˈbɒrtoːk/, né le 25 mars 1881 à Nagyszentmiklós en Autriche-Hongrie (désormais Saint-Nicolas-le-Grand en Roumanie) et mort le 26 septembre 1945 à New York (États-Unis) est un compositeur et pianiste hongrois." },
  { titre: "Bénarès", texte: "Bénarès ou Varanasi, située dans l'État indien de l'Uttar Pradesh est la ville la plus sacrée de l'hindouisme et du jaïnisme. Située sur la rive gauche du Gange, la plus sainte des sept rivières sacrées de l'Inde, la ville est considérée comme l'une des plus anciennement habitées du monde." },
  { titre: "Benazir Bhutto", texte: "Benazir Bhutto, née le 21 juin 1953 à Karachi et morte assassinée le 27 décembre 2007 à Rawalpindi, est une femme d'État pakistanaise. Elle est Première ministre de 1988 à 1990 et de 1993 à 1996." },
  { titre: "Bengali", texte: "Le bengali ou bangla (বাংলা (bangla), /ˈbaŋ.la/) est une langue indo-iranienne (sous-branche indo-aryenne) de la famille des langues indo-européennes. Avec l'assamais, il s'agit de la plus orientale des langues indo-européennes." },
  { titre: "Benjamin Britten", texte: "Edward Benjamin Britten, né le 22 novembre 1913 à Lowestoft dans le Suffolk, et mort le 4 décembre 1976 à Aldeburgh, est un compositeur, chef d'orchestre, altiste et pianiste britannique." },
  { titre: "Benjamin Disraeli", texte: "Benjamin Disraeli, né le 21 décembre 1804 et mort le 19 avril 1881 à Londres, est un homme d'État et écrivain britannique, Premier ministre du Royaume-Uni à deux reprises. Il joue un rôle central dans la création du Parti conservateur moderne dont il formalise la doctrine." },
  { titre: "Berceau de la civilisation", texte: "Le berceau de la civilisation est une expression faisant référence à des régions du monde où l'on considère que les premières civilisations humaines virent le jour. Il n'y eut pas un unique berceau, mais plusieurs civilisations se sont développées de manière indépendante." },
  { titre: "Béton de ciment", texte: "Le béton de ciment, couramment appelé béton, est un matériau de construction composite fait de granulats minéraux ou végétaux, de sables et d'eau agglomérés par un liant hydraulique (par exemple le ciment) qui se durcit avec le temps." },
  { titre: "Biais de confirmation", texte: "Le biais de confirmation, également dénommé biais de confirmation d'hypothèse, est un mécanisme cognitif qui consiste à privilégier les informations confirmant ses idées préconçues ou ses hypothèses, ou à accorder moins de poids aux hypothèses et informations jouant en défaveur de ses conceptions, ce qui se traduit" },
  { titre: "Biathlon", texte: "Le biathlon, du latin bis, « deux fois » (d'où bi-, « deux »), et du grec ἆθλον (áthlon), « combat, lutte », est une épreuve sportive combinant deux disciplines. Par coutume, quand on parle du biathlon, on évoque ce sport d'hiver qui associe le ski de fond au tir à la carabine." },
  { titre: "Bing Crosby", texte: "Bing Crosby, de son vrai nom Harry Lillis Crosby Jr., né le 3 mai 1903 à Tacoma (État de Washington) et mort le 14 octobre 1977 à Alcobendas près de Madrid, est un chanteur et acteur américain. Il est l'une des icônes culturelles majeures du XXe siècle." },
  { titre: "Bloc de l'Est", texte: "Le bloc de l’Est est l’ensemble des régimes marxistes-léninistes instaurés après la Seconde Guerre mondiale dans les pays d’Europe placés sous le contrôle plus ou moins direct de l’Union soviétique et situés à l’Est du rideau de fer." },
  { titre: "Boisson alcoolisée", texte: "Une boisson alcoolisée, ou boisson alcoolique, ou un alcool, est une boisson contenant de l'éthanol. Le vin, la bière et l'eau-de-vie sont des exemples de boissons alcoolisées." },
  { titre: "Bos taurus", texte: "Le Bœuf domestique (Bos taurus) est une espèce de bovins de l'Ancien Monde issu de l'aurochs sauvage. La femelle adulte est nommée vache et le mâle taureau. Il s'agit d'un mammifère artiodactyle de grande taille (120 à 150 cm pour 600 à 800 kg) appartenant au sous-ordre des Ruminants." },
  { titre: "Boson", texte: "En mécanique quantique, un boson est une particule de spin entier, qui obéit à la statistique de Bose-Einstein. Le théorème spin-statistique différencie les bosons des fermions, qui ont un spin demi-entier." },
  { titre: "Botanique", texte: "La botanique, nommée auparavant phytologie, ou encore biologie végétale, est la science qui a pour objet l'étude des végétaux. Elle présente plusieurs facettes qui la rattachent aux autres sciences du vivant." },
  { titre: "Botulisme", texte: "Le botulisme (dérivé du latin impérial botulus, « boudin », d'après les premiers aliments mis en cause) est une maladie paralytique rare mais grave, le plus souvent d'origine alimentaire, touchant les humains et les animaux." },
  { titre: "Boulingrin", texte: "Le boulingrin (de l'anglais bowling green, appelé aujourd'hui lawn bowling, par allusion au terrain gazonné sur lequel ce jeu se pratique) est un jeu de boules originaire d’Angleterre." },
  { titre: "Bousier", texte: "Les bousiers sont des insectes coléoptères coprophages. La plupart de ces espèces appartiennent aux sous-familles des Scarabaeinae et des Aphodiinae de la famille des Scarabaeidae. Ils se nourrissent presque exclusivement d'excréments et de résidus de parturitions." },
  { titre: "Bovidae", texte: "Les Bovidés (Bovidae) sont une famille de mammifères artiodactyles du sous-ordre des Ruminants, qui regroupe notamment les bovins, les caprins, les ovins et les antilopes. Ils présentent la caractéristique principale de posséder de vraies cornes permanentes et non ramifiées." },
  { titre: "Boyard", texte: "Un boyard, ou boïar est un aristocrate des pays orthodoxes non grecs d'Europe de l'Est : Ukraine, Biélorussie, Moldavie, Valachie, Transylvanie, Russie, Serbie, Bulgarie. Étymologiquement, le terme boyard prend son origine du terme boi qui signifie combat." },
  { titre: "Bronze", texte: "Le bronze est un nom générique qui était donné autrefois à tous les alliages de cuivre. Aujourd'hui, son sens est le plus souvent restreint aux alliages de cuivre ayant l'étain comme principal élément d'alliage." },
  { titre: "Buddy Holly", texte: "Buddy Holly, nom de scène de Charles Hardin Holley, né le 7 septembre 1936 à Lubbock au Texas et mort le 3 février 1959 à Clear Lake dans l'Iowa, est un chanteur, guitariste et compositeur américain de rock 'n' roll." },
  { titre: "Bursa", texte: "Bursa, parfois Brousse (ou Pruse) en français, du grec ancien Προῦσα / Proūsa, est une ville du Nord-Ouest de l'Anatolie en Turquie, capitale de la province du même nom. Bursa fut la seconde capitale de l'Empire ottoman, de 1326 à 1366." },
  { titre: "Cachemire", texte: "Le Cachemire (variante orthographique rare : Kashmir) est une région montagneuse du sous-continent indien. Ce vocable désigne, depuis la partition des Indes et la disparition de l'État princier du Jammu-et-Cachemire, l'ensemble du territoire qui constituait ce dernier." },
  { titre: "Cadran solaire", texte: "Un cadran solaire est un instrument de mesure qui indique le temps solaire par le déplacement de l'ombre d'un style sur une surface, la table du cadran, sur laquelle est tracé un ensemble de graduations (lignes horaires principalement)." },
  { titre: "Cahokia", texte: "Cahokia fut l'une des plus grandes cités amérindiennes d'Amérique du Nord : elle est située dans le sud-ouest de l'État de l'Illinois, proche de l'actuelle ville de Saint-Louis dans l'État voisin du Missouri." },
  { titre: "Calcutta", texte: "Calcutta ou Kolkata depuis 2001 est une ville de l'Est de l'Inde. Capitale du Bengale-Occidental, située sur la rive gauche du fleuve Hooghly, Calcutta compte 6 386 000 habitants et son agglomération 19 936 000 en 2024, ce qui en fait la troisième agglomération du pays, après Delhi et Bombay, et la seizième du monde." },
  { titre: "Calendrier chinois", texte: "Le calendrier chinois ou chinois agricole est un calendrier luni-solaire, les mois y sont lunaires, c'est-à-dire que le premier jour de chaque mois (de 29 ou 30 jours) coïncide avec la nouvelle lune (et le 15e jour avec la pleine lune) ; comme 12 mois lunaires ne forment pas une année solaire (il manque 11 jours, ou" },
  { titre: "Calgary", texte: "Calgary est une ville de l'Ouest du Canada, située dans la province de l'Alberta. En 2023, la ville comptait une population de 1 470 148 habitants et une agglomération de 1 640 000 habitants, ce qui en fait la troisième" },
  { titre: "Califat de Cordoue", texte: "Le califat omeyyade de Cordoue est un califat d'Ibérie musulmane gouverné par la dynastie des Omeyyades de Cordoue et qui dominait aussi une partie de l'Afrique du Nord. Succédant en 929 à l'émirat de Cordoue (créé en 756) avec la ville de Cordoue toujours comme capitale, il dure jusqu'en 1031." },
  { titre: "Califat fatimide", texte: "Le Califat fatimide était un califat islamique chiite ismaélien, mené par la dynastie des fatimides, qui régna depuis l'Ifriqiya (entre 909 et 969) puis depuis l'Égypte (entre 969 et 1171)." },
  { titre: "Califat omeyyade", texte: "Le Califat omeyyade (en arabe : الخلافة الأموية (al-Ḫilāfah al-ʾumawiyyah)) est un califat fondé par la dynastie arabe des Omeyyades, qui gouverne le monde musulman de 661 à 750. Les Omeyyades sont originaires de la tribu de Quraych, qui domine la Mecque au temps du prophète Mahomet." },
  { titre: "Camion", texte: "Un camion est un véhicule automobile destiné au transport routier de marchandises. Autrefois, il pouvait s'agir d'un véhicule à bras tracté par des hommes ou des animaux." },
  { titre: "Canberra", texte: "Canberra est la capitale de l'Australie et du Territoire de la capitale australienne. La ville est située à l'extrémité nord du territoire de la capitale, à 280 kilomètres au sud-ouest de Sydney et à 680 kilomètres au nord-est de Melbourne." },
  { titre: "Canne à sucre", texte: "La canne à sucre est une plante à fleurs du genre Saccharum, de la famille des Poaceae (ou graminées), sous-famille des Panicoideae. C'est une plante cultivée principalement pour la production du sucre (sucre de canne complet ou raffiné) extrait des tiges (ou chaumes)." },
  { titre: "Célèbes", texte: "Célèbes (en indonésien : Sulawesi) est une île du Nord de l'Indonésie située à environ 240 km à l'est de Bornéo, à 430 km au sud de Mindanao (Philippines), à 360 km à l'ouest de l'île de Buru (archipel indonésien des Moluques), à 290 km au nord de Florès et à 600 km à l'est-nord-est de Java." },
  { titre: "Champ électrique", texte: "En physique, le champ électrique est le champ vectoriel créé par des particules électriquement chargées. Plus précisément, des particules chargées modifient les propriétés locales de l'espace, ce que traduit justement la notion de champ." },
  { titre: "Chant", texte: "Le chant est l'ensemble de la production de sons musicaux produite par la voix humaine. La personne qui génère le chant est appelée chanteur, chanteuse, ou vocaliste." },
  { titre: "Chant grégorien", texte: "Le chant grégorien est le chant liturgique officiel et ordinaire de l'Église catholique. Issu du chant vieux-romain et du chant gallican, il reste pratiqué de nos jours dans un certain nombre d'églises paroissiales, de monastères ainsi que par des musiciens professionnels." },
  { titre: "Charge électrique", texte: "La charge électrique est une propriété fondamentale de la matière qui lui permet d'interagir par le biais de champs électromagnétiques. Il s'agit d'une grandeur scalaire, qui joue pour l'interaction électromagnétique le même rôle que la masse pour l'interaction gravitationnelle." },
  { titre: "Charles III le Gros", texte: "Charles III dit « le Gros », né en 839 à Neudingen, près de Donaueschingen, où il est mort le 12 janvier 888, est un prince et souverain carolingien." },
  { titre: "Charles IV", texte: "Charles IV (en allemand : Karl IV, en tchèque : Karel IV), né le 14 mai 1316 à Prague où il est mort le 29 novembre 1378, est comte de Luxembourg, roi de Bohême et empereur." },
  { titre: "Charles XII", texte: "Charles XII (en suédois : Karl XII), appelé en latin Carolus Rex et en turc Demirbaş Şarl (« Charles Tête de Fer »), né le 17 juin 1682 (27 juin dans le calendrier grégorien) et mort le 30 novembre 1718 (11 décembre dans le calendrier grégorien), membre de la branche suédoise de la dynastie de Palatinat-Deux-Ponts, a" },
  { titre: "Charlie Parker", texte: "Charlie Parker (Charles Christopher Parker, Jr.) surnommé Bird (l'oiseau) ou Yardbird, né le 29 août 1920 à Kansas City et mort le 12 mars 1955 à New York, est un saxophoniste alto emblématique du jazz américain." },
  { titre: "Charlotte", texte: "Charlotte est la plus grande ville de l'État de Caroline du Nord, aux États-Unis. Selon les estimations du Bureau du recensement des États-Unis, la commune compte 897 720 habitants en 2022 (la dix-septième du pays), au sein d'une agglomération de 2 660 329 habitants (33e)." },
  { titre: "Chat de gouttière", texte: "Un chat de gouttière ou de gouttières ou bien chat de maison ou chat commun est un chat domestique qui n’a pas de race précise. Le chat de gouttière est l'équivalent du chien bâtard." },
  { titre: "Chengdu", texte: "Chengdu, également appelée métaphoriquement Róngchéng, « la ville des hibiscus », est une ville chinoise, capitale de la province du Sichuan. Elle se trouve dans le Xinan, près de la limite avec le Tibet." },
  { titre: "Cherokees", texte: "Les Cherokees (en cherokee : ᎠᏂᏴᏫᏯ (a-ni-yv-wi-ya)), sont un peuple autochtone d’Amérique du Nord qui habitait dans l’Est et le Sud-Est des États-Unis avant d’être forcé à se déplacer vers le plateau d’Ozark." },
  { titre: "Chiang Mai", texte: "Chiang Mai, Chiangmai, Chiang Maï ou Chiengmai, surnommée la « Rose du Nord », est par son nombre d'habitants la deuxième ville de Thaïlande. Ce centre culturel et économique du Nord du pays a aussi le rang de capitale de la province de Chiang Mai." },
  { titre: "Chilopoda", texte: "Les Chilopoda (Chilopodes ou Centipèdes en français) sont une classe d'arthropodes myriapodes communément appelés « mille-pattes » (tout comme les diplopodes)." },
  { titre: "Chimie", texte: "La chimie est une science de la nature qui étudie la composition de la matière et ses transformations, plus précisément les atomes, par leurs assemblages nommés molécules, les réactions chimiques qui changent ces dernières en conservant les premiers, en produisant ou non de la chaleur ou de la lumière, sans oublier" },
  { titre: "Christine de Pizan", texte: "Christine de Pizan (en italien : Cristina da Pizzano) ou de Pisan, née en 1364 à Venise et morte vers 1430 au monastère de Poissy, est une philosophe, chroniqueuse et poétesse française de naissance vénitienne, notamment célèbre pour ses écrits rédigés en français." },
  { titre: "Cnidaria", texte: "Les Cnidaires (Cnidaria) sont un embranchement d'animaux aquatiques (marins à 99 %, 1 % de dulcicoles seulement), possédant une symétrie radiale et des nématocystes (organites capables de lancer un harpon urticant pour attraper des proies)." },
  { titre: "Cobra", texte: "Le nom cobra désigne plusieurs espèces de serpents venimeux de la famille des Elapidae, notamment l'ensemble des espèces du genre Naja, qui ont la particularité d'étendre une coiffe lorsqu'ils sont en posture de combat." },
  { titre: "Code-barres", texte: "Un code-barres, ou code à barres (CAB), est la représentation d'une donnée numérique ou alphanumérique sous forme d'un symbole constitué de barres et d'espaces dont l'épaisseur varie en fonction de la symbologie utilisée et des données ainsi codées." },
  { titre: "Colchique", texte: "Colchicum (les colchiques) est un genre de plantes herbacées vivaces de la famille des Liliaceae selon la classification classique de Cronquist (1981) ou des Colchicaceae selon la classification phylogénétique." },
  { titre: "Collembola", texte: "Les Collemboles (Collembola) sont une classe de petits Arthropodes pancrustacés, souvent sauteurs. Ils étaient encore dans les années 1970 considérés comme des Insectes aptérygotes, mais forment aujourd'hui une classe à part, dans le sous-embranchement des Hexapodes appartenant au clade des Pancrustacea." },
  { titre: "Colocasia esculenta", texte: "Le taro ou oreille d'éléphant (Colocasia esculenta) est une espèce de plantes à fleurs monocotylédones de la famille des Araceae, sous-famille des Aroideae, originaire du sous-continent indien et d'Asie du Sud-Est, à répartition pantropicale." },
  { titre: "Comète", texte: "Une comète (stylisée en symbole astronomique, Unicode ☄) est, en astronomie, un petit corps céleste constitué d'un noyau, mélange de glace et de poussière." },
  { titre: "Concubinage", texte: "Le terme de concubinage désigne la situation juridique d'un couple de fait formé de deux personnes adultes qui vivent ensemble de façon durable et notoire sans avoir célébré leur union de façon officielle." },
  { titre: "Cône Sud", texte: "Le Cône Sud (en espagnol : Cono Sur ; en portugais : Cone Sul) est une expression apparue dans les années 1960 et qui désigne la zone d'Amérique du Sud la plus australe du continent. Située au sud du tropique du Capricorne, elle forme un grand triangle, quasiment comme une grande péninsule." },
  { titre: "Confédération germanique", texte: "La Confédération germanique (en allemand : Deutscher Bund ; nom officiel en français, langue du congrès de Vienne) est une confédération européenne ayant existé de 1815 à 1866. Elle est formée lors du congrès de Vienne, en remplacement de la confédération du Rhin sous protectorat de Napoléon Ier." },
  { titre: "Conflit israélo-arabe", texte: "Le conflit israélo-arabe est le nom donné aux relations tendues entre l'État d'Israël et les États arabes environnants, depuis la création d'Israël le 14 mai 1948." },
  { titre: "Confucianisme", texte: "Le confucianisme, Rújiā « école des lettrés » puis Rúxué « enseignement des lettrés », est l'une des plus grandes écoles philosophiques, morales, politiques et dans une moindre mesure religieuse de Chine." },
  { titre: "Conjecture de Poincaré", texte: "La conjecture de Poincaré est une conjecture mathématique du domaine de la topologie algébrique portant sur la caractérisation d'une variété particulière, la sphère de dimension trois ; elle fut démontrée en 2002 par le Russe Grigori Perelman." },
  { titre: "Consanguinité", texte: "En génétique des populations, la consanguinité est définie comme étant le résultat d'une reproduction sexuée entre deux individus apparentés (c'est-à-dire ayant un ou plusieurs ancêtres communs). Pour un descendant donné, elle est d'autant plus importante que le lien de parenté entre les géniteurs est étroit." },
  { titre: "Conservatisme", texte: "Le conservatisme est une philosophie politique qui est en faveur des valeurs traditionnelles et affirme le primat des structures sociales et de la culture sur la raison humaine." },
  { titre: "Console de jeux vidéo", texte: "Une console de jeu vidéo (ou console de jeux vidéo) est un appareil informatique qui émet un signal vidéo ou une image pour afficher un jeu vidéo auquel on peut généralement jouer à l'aide d'un contrôleur de jeu." },
  { titre: "Consonne", texte: "Une consonne est un type de son que l'on trouve dans les langues naturelles orales. Le mot peut également renvoyer à la lettre qui sert à noter un son consonne." },
  { titre: "Constantin Brâncuși", texte: "Constantin Brâncuși, souvent désigné en français par son seul patronyme, Brancusi, né le 19 février 1876 à Hobița (ro), dans la commune de Peștișani, dans le județ de Gorj, en principauté de Roumanie, et mort le 16 mars 1957 à Paris (France), est un sculpteur roumain naturalisé français (le 15 juin 1952), qui est l'un" },
  { titre: "Constitution", texte: "Une constitution est une loi fondamentale qui fixe l'organisation et le fonctionnement d'un organisme, généralement d'un État ou d'un ensemble d'États." },
  { titre: "Contre-Réforme", texte: "La Contre-Réforme (ou, plus rarement, Réforme catholique) est le mouvement par lequel l'Église catholique réagit, dans le courant du XVIe siècle, face à la Réforme protestante. L'expression « Contre-Réforme » provient de l'historiographie allemande du XIXe siècle, dans un esprit initialement polémique." },
  { titre: "Córdoba", texte: "Córdoba (fondée sous le nom de Córdoba de la Nueva Andalucía) est une ville du centre-nord de l’Argentine. C'est la capitale de la province de Córdoba. Deuxième ville d'Argentine par son nombre d'habitants, c'est également un important centre culturel, économique, financier, et compte une forte population étudiante." },
  { titre: "Cosmétique", texte: "Les cosmétiques englobent une vaste gamme de produits destinés à embellir, protéger ou modifier l'apparence des parties superficielles du corps humain, tels que la peau, les cheveux, les ongles et les lèvres, sans en altérer la nature intrinsèque." },
  { titre: "Coumans", texte: "Les Coumans, Kipchaks ou Polovtses (appelés aussi Cumans, Comans, Kaptchaks, Quiptchaques ou Koumans, Kumanlar en turc, Kunok en hongrois, Cumani en roumain, Половці (Polovts) en ukrainien, Половцы (Polovtsy) en russe, Кумани (Kumani) en bulgare, Қыпшақ (Qīpshaq) en kazakh), sont un peuple turcophone nomade," },
  { titre: "Courants de l'islam", texte: "Les courants de l'islam sont les différents mouvements, rites et écoles philosophiques qui sont progressivement apparus au cours de l'histoire de l'islam, à la suite de questions qui sont apparues autour de thèmes comme l'organisation du pouvoir politique, celle de la société, du culte." },
  { titre: "Croissant fertile", texte: "Le Croissant fertile est une expression désignant une région (non officielle) biogéographique du Proche et Moyen-Orient formant une bande de terres cultivables grâce à un climat suffisamment pluvieux, délimitée au sud par le désert de Syrie (qui forme la partie nord du désert d'Arabie), à l'ouest par la mer" },
  { titre: "Cuzco", texte: "Cuzco, Cusco (en espagnol péruvien), Qosqo ou Qusqu (en quechua) est une ville du sud-est du Pérou au milieu de la cordillère des Andes. C'est la capitale de la province (provincia) de Cuzco et de la Région (departamento) de Cuzco." },
  { titre: "Da Nang", texte: "Đà Nẵng ou Da Nang (anciennement connue en Occident sous le nom de Tourane) est une municipalité dans la région de Côte centrale du Sud et Montagnes centrales du Vietnam. Elle fait partie des 34 provinces et villes du pays." },
  { titre: "Danse", texte: "La danse est une forme d'art vivant. C'est un mode d'expression éphémère constitué de séquences de mouvements de corps dans l'espace souvent accompagnés par de la musique. Les mouvements sont à dessein, intentionnellement rythmiques et façonnés culturellement." },
  { titre: "Déclaration Balfour de 1917", texte: "La déclaration Balfour de 1917 est une lettre ouverte, datée du 2 novembre 1917 et signée par Arthur Balfour, secrétaire d'État britannique aux Affaires étrangères (Foreign Secretary) dans le gouvernement de David Lloyd George." },
  { titre: "Décolonisation", texte: "La décolonisation est un processus d'émancipation des territoires coloniaux vis-à-vis des métropoles colonisatrices. Elle conduit le plus souvent à l'indépendance des pays colonisés." },
  { titre: "Désert du Taklamakan", texte: "Le Taklamakan est un désert continental d'Asie centrale, dont la grande majorité de la surface se trouve dans la région autonome ouïgoure du Xinjiang en République populaire de Chine." },
  { titre: "Détroit de Béring", texte: "Le détroit de Béring, ou détroit de Behring, est un passage maritime séparant la péninsule Tchouktche, dans le district autonome de Tchoukotka, de la péninsule Seward, en Alaska." },
  { titre: "Diffraction", texte: "La diffraction est le comportement des ondes lorsqu'elles rencontrent un obstacle ou une ouverture ; le phénomène peut être interprété par la diffusion d’une onde par les points de l'objet. La diffraction se manifeste par des phénomènes d'interférence." },
  { titre: "Dmitri Mendeleïev", texte: "Dmitri Ivanovitch Mendeleïev, né le 27 janvier 1834 (8 février dans le calendrier grégorien) à Tobolsk et mort le 20 janvier 1907 (2 février dans le calendrier grégorien) à Saint-Pétersbourg, est un chimiste russe." },
  { titre: "Documentaire", texte: "Le film documentaire ou le documentaire est un genre cinématographique, audiovisuel, télévisuel et radiophonique qui se différencie de la fiction." },
  { titre: "Doris Day", texte: "Mary Ann Kappelhoff, dite Doris Day est une actrice, chanteuse et productrice américaine, née le 3 avril 1922 à Cincinnati dans l'Ohio et morte le 13 mai 2019 à Carmel-by-the-Sea en Californie." },
  { titre: "Drogue", texte: "Une drogue est un composé chimique, biochimique ou naturel, capable d'altérer une ou plusieurs activités neuronales et/ou de perturber les communications neuronales." },
  { titre: "Droit", texte: "Le Droit, ou droit objectif, est défini comme « l'ensemble des règles qui régissent la conduite de l'homme en société, les rapports sociaux », ou de façon plus complète « l'ensemble des règles imposées aux membres d'une société pour que leurs rapports sociaux échappent à l'arbitraire et à la violence des individus et" },
  { titre: "Dynamite", texte: "La dynamite est un explosif solide à base de nitroglycérine. Inventée par Alfred Nobel en 1866, la dynamite est le premier explosif détonant à s'être diffusé largement." },
  { titre: "Dynastie Yuan", texte: "La dynastie Yuan, officiellement le Grand Yuan, est une dynastie mongole fondée suivant la tradition chinoise en 1271 par Kubilai Khan, le petit-fils de Gengis Khan, et qui règne sur la Chine jusqu'en 1368." },
  { titre: "Église orthodoxe éthiopienne", texte: "L'Église orthodoxe tewahedo éthiopienne (amharique : የኢትዮጵያ ኦርቶዶክስ ተዋሕዶ ቤተ ክርስቲያን (yäItyop'ya ortodoks tewahedo bétä krestiyan) ) est une dénomination établie en Éthiopie, autocéphale depuis 1951, qui fait partie de l'ensemble formé par les Églises des trois conciles." },
  { titre: "Électronvolt", texte: "En physique et en chimie, l'électronvolt ou électron-volt (au pluriel électronvolts ou électrons-volts), de symbole eV, est une unité d'énergie et par ellipse, dans certaines branches de la physique, d'autres grandeurs physiques comme la masse et la température." },
  { titre: "Élément chimique", texte: "Un élément chimique est une classe d'atomes dont le noyau compte un même nombre de protons. Ce nombre, noté Z, est le numéro atomique de l'élément, qui détermine la configuration électronique des atomes correspondants, et donc leurs propriétés physicochimiques." },
  { titre: "Elia Kazan", texte: "Elia Kazanjoglous, dit Elia Kazan, né Elias Kazantzoglou, né le 7 septembre 1909 à Constantinople (Empire ottoman) et mort le 28 septembre 2003 à New York (États-Unis), est un réalisateur, metteur en scène de théâtre et écrivain américain d'origine grecque, décrit par le The New York Times comme « l'un des" },
  { titre: "Elie Wiesel", texte: "Eliezer Wiesel, dit Elie Wiesel (var. Élie), est un écrivain, philosophe et professeur d'université américain d'origine roumaine, né le 30 septembre 1928 à Sighetu Marmației, en Roumanie, et mort le 2 juillet 2016 à New York." },
  { titre: "Ellen Johnson Sirleaf", texte: "Ellen Johnson Sirleaf, née le 29 octobre 1938 à Monrovia (Liberia), est une femme d'État libérienne, présidente de la République du 16 janvier 2006 au 22 janvier 2018." },
  { titre: "Émeraude", texte: "L’émeraude est un minéral, du groupe des silicates, sous-groupe des cyclosilicates, variété de béryl, dont la couleur verte provient de traces de chrome, de vanadium et parfois de fer. L'émeraude est, avec le diamant, le saphir et le rubis, l'une des quatre gemmes qualifiées de pierres précieuses." },
  { titre: "Emil Zátopek", texte: "Emil Zátopek, né le 19 septembre 1922 à Kopřivnice et mort le 22 novembre 2000 à Prague, est un athlète tchécoslovaque spécialiste des courses de fond, du 5 000 mètres au marathon." },
  { titre: "Empire d'Akkad", texte: "L’empire d'Akkad, parfois appelé Empire akkadien ou plus simplement Akkad (on trouve aussi Agadé), est un État fondé par Sargon d'Akkad et qui domina la Mésopotamie de la fin du XXIVe au début du XXIIe siècle av. J.-C., selon la chronologie la plus couramment retenue, même s'il est possible qu'il se soit épanoui" },
  { titre: "Enfant", texte: "Un enfant est un jeune être humain immature qui dépend d'adultes pour son bon développement. En principe, les adultes responsables de l'enfant sont ses tuteurs et traditionnellement sa famille, en particulier ses parents qu'ils soient génétiques ou adoptifs, voire d'accueil." },
  { titre: "Escalade", texte: "L’escalade, également appelée grimpe ou parfois varappe (désuet), est une pratique et un sport consistant à progresser le long d'une paroi pour atteindre le haut d'un relief ou d'une structure artificielle par un cheminement appelé voie ou itinéraire, avec ou sans l'aide de matériel." },
  { titre: "Escrime", texte: "L’escrime est un sport de combat. Il s’agit de l’art de toucher un adversaire avec la pointe ou le tranchant (estoc et taille) d’une arme blanche sur les parties valables sans être touché." },
  { titre: "Ethnologie", texte: "L'ethnologie est l'étude comparative et explicative de l'ensemble des caractères culturels « les plus manifestes comme les moins avous » des groupes humains." },
  { titre: "Euphémisme", texte: "Un euphémisme, du grec ancien εὐφημισμός / euphēmismos, de φημί / phēmĩ, « dire, parler » avec le préfixe εὖ- / -eū, « bien »), est une figure de style qui consiste à atténuer l'expression de faits ou d'idées considérés comme désagréables dans le but d'adoucir la réalité." },
  { titre: "Exocoetidae", texte: "Les Exocoetidae ou exocets, appelés usuellement poissons volants sont une famille de poissons marins comprenant 70 espèces regroupées dans 7 à 9 genres." },
  { titre: "Extinction Crétacé-Paléogène", texte: "L'extinction Crétacé-Paléogène ou extinction K-Pg, antérieurement dénommée extinction Crétacé-Tertiaire ou extinction K-T, est une extinction massive et à grande échelle d'espèces animales et végétales qui s'est produite sur une courte période de temps (à l'échelle géologique) il y a 66 millions d'années." },
  { titre: "Extinction Permien-Trias", texte: "L'extinction Permien-Trias ou extinction permienne est une extinction massive survenue il y a environ 252 millions d'années (Ma). Elle délimite les périodes géologiques du Permien et du Trias, donc la limite entre le Paléozoïque (l'ère primaire) et le Mésozoïque (l'ère secondaire)." },
  { titre: "Ezra Pound", texte: "Ezra Weston Loomis Pound, né à Hailey, alors dans le territoire de l'Idaho, le 30 octobre 1885 et mort le 1er novembre 1972 à Venise, est un poète, musicien et critique américain qui a fait partie du mouvement moderniste du début des années 1920 et qui est souvent rattaché à la Génération perdue." },
  { titre: "Famille", texte: "Une famille (latin : familia) est un groupement humain formé de personnes liées par consanguinité (par naissance reconnue) ou par affinité (par mariage ou autre relation) qui vivent généralement sous le même toit." },
  { titre: "Famille Brontë", texte: "La famille Brontë est une famille littéraire britannique du XIXe siècle, dont la notoriété, qui s'étend à tous ses membres, est essentiellement due aux trois sœurs, poétesses et romancières, Charlotte (1816-1855), Emily (1818-1848) et Anne (1820-1849)." },
  { titre: "Famille de langues", texte: "Une famille de langues est un ensemble de langues apparentées qui ont évolué par transmission de génération en génération de locuteurs à partir d'une langue ancestrale commune." },
  { titre: "Fatima Zahra", texte: "Fatima Zahra ou Fatima bint Muhammad, née entre 604 et 615 à La Mecque et morte en 632 ou 633 à Médine, est une personnalité religieuse et morale de l'islam primitif." },
  { titre: "Fela Kuti", texte: "Fela Kuti, également connu sous le nom de Fela Anikulapo Kuti, ou simplement Fela, est un chanteur, saxophoniste, chef d'orchestre, cryptarque et homme politique nigérian, né le 15 octobre 1938 à Abeokuta et mort le 2 août 1997 à Lagos." },
  { titre: "Féodalité", texte: "La féodalité est un système politique, ayant notamment existé en Occident chrétien (actuelle Europe) entre les Xe et XIIe siècles, dans lequel l'autorité centrale s'associe avec les seigneurs locaux et ceux-ci avec leur population, selon un système complet d'obligations et de services reposant sur le droit féodal." },
  { titre: "Ferdinand de Saussure", texte: "Ferdinand de Saussure, né à Genève le 26 novembre 1857 et mort à Vufflens-le-Château le 22 février 1913, est un linguiste suisse. Reconnu comme le précurseur du structuralisme en linguistique, il s'est aussi distingué par ses travaux sur les langues indo-européennes." },
  { titre: "Ferdinand Ier", texte: "Ferdinand Ier, né le 10 mars 1503 à Alcalá de Henares ( près de Madrid) et mort le 25 juillet 1564 à Vienne (Archiduché d'Autriche), est un membre de la maison de Habsbourg. Il devient souverain des territoires héréditaires des Habsbourg en 1521, en tant qu'archiduc d'Autriche." },
  { titre: "Finance", texte: "La finance renvoie à un domaine d'activité — celui du financement —, aujourd'hui mondialisé, qui consiste à fournir ou trouver l'argent ou les « produits financiers » nécessaire à la réalisation d'une opération économique." },
  { titre: "Flûte", texte: "Flûte (ou flute) est un terme générique désignant un instrument de musique à vent dont le son est créé par l'oscillation d'un jet d’air autour d'un biseau droit, en encoche ou en anneau." },
  { titre: "Flûte traversière", texte: "La flûte traversière est un instrument à vent de la famille des bois. Jusqu'au XIXe siècle, elle était effectivement en bois, lequel a été peu à peu remplacé par le métal en Europe. Le terme traversière provient du jeu latéral du musicien par rapport à l'instrument." },
  { titre: "Fontaine", texte: "Fontaine (en anglais : Fountain) est un ready-made de Marcel Duchamp consistant en un urinoir en porcelaine renversé signé « R. Mutt » et daté 1917. L'œuvre apparaît dans le catalogue raisonné d'Arturo Schwarz sous le no 345." },
  { titre: "Four à micro-ondes", texte: "Un four à micro-ondes, ou plus simplement un micro-ondes ou même un microonde, est un appareil électroménager utilisé principalement pour le chauffage et la cuisson rapide d'aliments, par l'agitation des molécules d'eau qu'ils contiennent, sous l'effet d'un rayonnement micro-onde." },
  { titre: "François Xavier", texte: "François Xavier (en espagnol Francisco Javier, en basque Frantzisko Xabierkoa), né Francisco de Jasso y Azpilicueta le 7 avril 1506 à Javier, près de Pampelune en Navarre, et mort le 3 décembre 1552 sur l'île de Shangchuan (ancien nom européen : Sancian), au large de Canton en Chine, est un missionnaire jésuite" },
  { titre: "Frederick Douglass", texte: "Frederick Douglass, né Frederick Augustus Washington Bailey en 1817 ou 1818, et mort le 20 février 1895 à Washington, est un orateur, abolitionniste, éditeur et fonctionnaire américain. Esclave depuis sa naissance, il réussit à s'instruire et s'enfuit à l'âge de 20 ans." },
  { titre: "Funk", texte: "Le funk est un genre musical apparu au milieu des années 1960 aux États-Unis dans la lignée du mouvement hard bop et qui s'est développé au cours des années 1960 et 1970." },
  { titre: "Futurisme", texte: "Le futurisme est un mouvement littéraire et artistique européen du début du XXe siècle (de 1910 à 1920), qui rejette la tradition esthétique et exalte le monde moderne, en particulier la civilisation urbaine, les machines et la vitesse." },
  { titre: "Galliformes", texte: "Les Galliformes (communément appelés « gallinacés ») sont un ordre d'oiseaux comprenant entre autres les dindes, les poules, les pintades, les cailles et les faisans." },
  { titre: "Gallus gallus domesticus", texte: "Gallus gallus domesticus, la Poule domestique (femelle) et le coq domestique (mâle), est une sous-espèce de Gallus gallus, une espèce de la famille des Phasianidés (ordre des Galliformes)." },
  { titre: "Ganesh", texte: "Dans l'hindouisme, Ganesh (IAST : Gaṇeśa), également appelé Vināyaka (« qui-conduit-à-travers (les difficultés) », « qui fait surmonter les difficultés »), Gaṇapati (« le maître des troupes de divinités » ou plutôt « le seigneur des catégories ») ou Pillaiyar dans l'extrême-sud de l'Inde, est le dieu qui écarte les" },
  { titre: "Gange", texte: "Le Gange est un fleuve de la plaine indo-gangétique, au nord de l'Inde. Sa longueur varie suivant les sources de 2 500 à 3 000 km, son bassin recouvre 907 000 km2 et son delta est commun avec celui du Brahmapoutre." },
  { titre: "Gangrène", texte: "La gangrène est une nécrose des tissus, causée par une obstruction artérielle par embolie, choc, infection ou par l’exposition à un froid intense. Son origine est le plus souvent liée à l’interruption prolongée ou au ralentissement extrême de l’irrigation sanguine." },
  { titre: "Garuda", texte: "Garuda est un homme-oiseau fabuleux de la mythologie hindouiste puis bouddhiste, fils de Kashyapa et de Vinatâ et frère d'Aruna, le conducteur du char du dieu Sûrya. C'est le vâhana, ou monture, du dieu Vishnu." },
  { titre: "Gizeh", texte: "Gizeh (ou Gizèh, Giza, Gîza, Guizèh), en arabe الجيزة (al-Gizah), est une ville d'Égypte, située sur la rive gauche du Nil, face à la vieille ville du Caire." },
  { titre: "Goryeo", texte: "Le royaume de Goryeo, parfois translittéré en Koryo, est l'État qui a occupé toute la superficie de la péninsule de Corée du début du Xe siècle à la fin du XIVe siècle (918–1392). Pendant deux siècles, les arts et le commerce font la richesse de la Corée et le bouddhisme prend une très grande place." },
  { titre: "Goths", texte: "Les Goths ou Gots sont un peuple germanique qui prend une importance historique pendant la période des grandes invasions de la fin de l'Antiquité pour disparaître historiquement au VIIIe siècle." },
  { titre: "Grand Bond en avant", texte: "Le Grand Bond en avant est le nom donné à une politique économique lancée par Mao Zedong et mise en œuvre de 1958 à 1960. Constatant les difficultés à suivre le modèle soviétique, Mao entend avancer vers le socialisme en Chine en s'appuyant sur la paysannerie davantage que sur la population urbaine." },
  { titre: "Grégoire Ier", texte: "Grégoire Ier dit Grégoire le Grand, né vers 540 à Rome et mort dans la même ville le 12 mars 604, est un magistrat et ecclésiastique romain qui est élu évêque de Rome le 3 septembre 590 après en avoir été l'un des derniers préfets de Rome." },
  { titre: "Gregor Mendel", texte: "Johann Gregor Mendel, né le 20 juillet 1822 à Hynčice (Bohême (Empire austro-hongrois)) et mort le 6 janvier 1884 à Brno (margraviat de Moravie), est un moine catholique, puis abbé mitré de l'abbaye Saint-Thomas de Brno, généticien et botaniste germanophone de nationalité autrichienne, communément reconnu comme le" },
  { titre: "Grenadier commun", texte: "Le grenadier commun ou grenadier (Punica granatum) est une espèce de plantes à fleurs de la famille des Lythracées. C'est un arbre fruitier, cultivé depuis la plus haute Antiquité pour ses fruits comestibles (les grenades) et pour les qualités ornementales de ses grandes fleurs." },
  { titre: "Grigori Potemkine", texte: "Grigori Aleksandrovitch Potemkine ou Potiomkine, né le 11 octobre 1739 à Tchijovo et mort le 16 octobre 1791 durant un voyage de Iași à Nikolaïev, est un militaire et homme d'État russe du XVIIIe siècle." },
  { titre: "Grossesse", texte: "La grossesse, appelée aussi gestation humaine, est l'état d'une femme enceinte, c'est-à-dire portant un embryon ou un fœtus humain, en principe au sein de l'utérus, qui est dit gravide." },
  { titre: "Groupe sanguin", texte: "Un groupe sanguin est une classification reposant sur la présence ou l'absence de substances antigéniques héritées à la surface des globules rouges (hématies)." },
  { titre: "Guangdong", texte: "Le Guangdong est une province de la république populaire de Chine, située dans la région sud du pays, dont le chef-lieu est Canton (Guangzhou)." },
  { titre: "Guayaquil", texte: "Guayaquil, officiellement Santiago de Guayaquil, surnommée la « Perle du Pacifique » est la plus grande ville de l'Équateur et également la capitale économique et le principal port du pays de la côte ouest de l'Amérique latine." },
  { titre: "Guerre du Biafra", texte: "La guerre du Biafra est une guerre civile au Nigeria qui s'est déroulée du 6 juillet 1967 au 15 janvier 1970. Elle a été déclenchée par la sécession de la région orientale du Nigeria, qui s'autoproclame république du Biafra sous la direction du colonel Odumegwu Emeka Ojukwu avec pour capitale Enugu." },
  { titre: "Guerre du Viêt Nam", texte: "La guerre du Vietnam — également appelée deuxième guerre d'Indochine ou guerre civile vietnamienne, ou encore guerre des Dix Mille Jours par les Vietnamiens, qui ne la considèrent pas comme un conflit indépendant de la guerre d'Indochine — est une guerre qui se déroule au Vietnam et oppose, de 1955 à 1975, d'une part" },
  { titre: "Guglielmo Marconi", texte: "Guglielmo Marconi, né le 25 avril 1874 à Bologne et mort le 20 juillet 1937 à Rome, est un physicien, inventeur et homme d'affaires italien. Il est considéré comme l’un des inventeurs de la radio et de la télégraphie sans fil." },
  { titre: "Gujarat", texte: "Le Gujarat est l'un des vingt-huit États de l'Inde. Il se situe dans l’ouest du pays. Sa capitale est Gandhinagar. Il est bordé au nord par le Pakistan et l'État du Rajasthan, à l'est par le Madhya Pradesh et au sud par le Maharashtra, enclavant aussi le territoire de l'union de Dadra-et-Nagar-Haveli et Daman-et-Diu." },
  { titre: "Hans Holbein le Jeune", texte: "Hans Holbein le Jeune, né à Augsbourg, en Bavière, vers 1497 et mort à Londres en 1543, entre le 8 octobre et le 29 novembre, est un peintre et graveur de la Renaissance nordique, d'abord sujet du Saint-Empire romain germanique, puis citoyen de Bâle (ancienne Confédération suisse)." },
  { titre: "Haoussa", texte: "Le haoussa ou hausa (autonyme : harshen Hausa) est une langue tchadique (une des branches de la famille des langues afro-asiatiques) parlée dans une grande partie du continent africain, principalement au Nigéria et au Niger, mais également au Cameroun, Soudan, Tchad, Bénin, Ghana, Togo, Centrafrique, Gabon et Burkina" },
  { titre: "Herbert von Karajan", texte: "Herbert von Karajan, né le 5 avril 1908 à Salzbourg et mort le 16 juillet 1989 à Anif, près de Salzbourg, est un chef d'orchestre autrichien." },
  { titre: "Herman Melville", texte: "Herman Melville, né le 1er août 1819 à Pearl Street, dans le sud-est de Manhattan (New York) et mort le 28 septembre 1891 à New York, est un romancier, essayiste et poète américain." },
  { titre: "Hétérosexualité", texte: "L'hétérosexualité (terme forgé au XIXe siècle) est une attirance romantique, une attirance sexuelle ou un comportement sexuel entre des personnes de sexes ou de genres opposés." },
  { titre: "Heure d'été", texte: "L’heure d'été est un système consistant à ajuster l'heure locale officielle, en ajoutant une heure à l'heure normale (appelée alors « heure d'hiver ») pour une période allant généralement du début du printemps au milieu de l'automne, ce qui a pour effet de retarder l'heure à laquelle le Soleil se lève et se couche." },
  { titre: "Hindi", texte: "Le hindi (aussi, l'hindi) est une langue indo-européenne, issue d'une standardisation de la langue hindoustanie, utilisant abondamment du vocabulaire sanskritisant." },
  { titre: "Histoire de l'Allemagne", texte: "L'histoire de l'Allemagne est complexe et varie selon les limites géographiques et historiques dans lesquelles on considère le territoire et l'ethnogenèse du peuple allemand." },
  { titre: "Histoire de l'Australie", texte: "L'Histoire de l'Australie remonte aux premières migrations vers le continent australien, qui débutèrent dans le nord vers 60 000 ans avant notre ère (62 000 ans avant le présent)." },
  { titre: "Histoire de l'Espagne", texte: "L'histoire de l'Espagne, pays du sud-ouest de l'Europe qui occupe la plus grande partie de la péninsule Ibérique, se caractérise par plusieurs périodes et événements marquants, depuis la période ibérique en passant par l'époque romaine, la période wisigoth, la conquête musulmane, la reconquête puis le Siècle d'or, à" },
  { titre: "Holi", texte: "La Holi (होली (holī)), parfois appelée fête des couleurs ou Phalguna, est une fête hindoue originaire de l'Inde célébrée vers l'équinoxe de printemps. Elle trouve son origine dans la Vasantotsava, à la fois un sacre du printemps et célébration de la fertilité." },
  { titre: "Homicide", texte: "Un homicide est l'action de tuer un être humain, qu’elle soit volontaire ou non. Lorsque l'acte est dans l'intention de tuer ou dans l'intention de causer des lésions corporelles qui entraînent la mort, il est généralement qualifié de meurtre, et d’assassinat (ou meurtre au premier degré) s'il est de plus prémédité." },
  { titre: "Hominoidea", texte: "Les Hominoïdes (Hominoidea), plus communément désignés sous l’appellation de grands singes, ou encore de singes sans queue, forment l'une des deux super-familles de singes de l'Ancien Monde ou Catarrhiniens." },
  { titre: "Homo erectus", texte: "Homo erectus est une espèce fossile du genre Homo dont la définition est controversée. Son périmètre morphologique, géographique et temporel varie fortement selon les auteurs." },
  { titre: "Homo habilis", texte: "Homo habilis (littéralement « homme habile ») est une espèce fossile du genre Homo qui, d'après les fossiles connus, aurait vécu en Afrique de l'Est il y a entre environ 2,3 et 1,4 millions d’années." },
  { titre: "Homophobie", texte: "L'homophobie est l'attitude de rejet, d'hostilité systématique ou d'aversion envers des personnes, des pratiques ou des représentations homosexuelles ou supposées l'être." },
  { titre: "Hongrois", texte: "Le hongrois ou la langue hongroise est une langue de la branche ougrienne des langues finno-ougriennes, au sein de la famille des langues ouraliennes." },
  { titre: "Horloge", texte: "Une horloge est un instrument de mesure du temps qui généralement indique l'heure en continu. Le mot vient du latin horologium, « qui dit l’heure », lui-même dérivé du grec ὡρολόγιον." },
  { titre: "Horloge atomique", texte: "Une horloge atomique est une horloge qui utilise la pérennité et l'immuabilité de la fréquence du rayonnement électromagnétique émis par un électron lors du passage d'un niveau d'énergie à un autre pour assurer l'exactitude et la stabilité du signal oscillant qu'elle produit." },
  { titre: "Hormone", texte: "Parmi les animaux, une hormone est une substance produite de façon naturelle par un organe du corps, qui est transportée par le sang et agit sur d’autres organes." },
  { titre: "Hubble", texte: "Hubble (en anglais : Hubble Space Telescope, en abrégé HST ou, rarement en français, TSH) est un télescope spatial conçu par la NASA avec une participation de l'Agence spatiale européenne, opérationnel depuis 1990, et orbitant à 515 km d'altitude environ." },
  { titre: "Huile végétale", texte: "Une huile végétale est un corps gras liquide à température ambiante, extrait d'une plante oléagineuse, c'est-à-dire une plante dont les graines, noix, amandes ou fruits contiennent des lipides. Attention à ne pas confondre « huile végétale » avec « macérat huileux »." },
  { titre: "Huître", texte: "La dénomination vernaculaire huître désigne les mollusques marins bivalves de la famille des Ostreidae et plus largement de la super-famille des Ostreoidea. Les huîtres ne vivent que dans l'eau salée ou saumâtre et se trouvent dans toutes les mers." },
  { titre: "Hybride", texte: "En génétique, un hybride est un organisme issu du croisement de deux individus de deux variétés, sous-espèces (croisement intraspécifique), espèces (croisement interspécifique) ou genres (croisement intergénérique) différents." },
  { titre: "Hypertext Markup Language", texte: "Le HyperText Markup Language, généralement abrégé HTML ou, dans sa dernière version, HTML5, est le langage de balisage conçu pour écrire les pages web. Il s'agit d'un format ouvert très utilisé en informatique." },
  { titre: "Hypertext Transfer Protocol", texte: "L’Hypertext Transfer Protocol, généralement abrégé HTTP, littéralement « protocole de transfert hypertexte », est un protocole de communication client-serveur développé pour le World Wide Web. HTTPS (avec S pour secure, soit « sécurisé ») est la variante sécurisée par le chiffrement et l'authentification." },
  { titre: "Ibn Arabi", texte: "Ibn ‘Arabī, né le 26 juillet 1165, à Murcie, et mort le 16 novembre 1240, à Damas est un ouléma, théologien, juriste (faqīh), poète, soufi, métaphysicien et philosophe (faylasûf) arabo-berbère-andalou, auteur d'environ 850 ouvrages." },
  { titre: "Ibn Taymiyya", texte: "Taqî ad-Dîn Ahmad ibn Taymiyya, né le 22 janvier 1263 à Harran (Sultanat mamelouk d'Égypte) et mort le 26 septembre 1328 à Damas, est un théologien et juriconsulte (faqîh) musulman hanbalite traditionaliste." },
  { titre: "Ieoh Ming Pei", texte: "Ieoh Ming Pei, communément appelé I. M. Pei, est un architecte américain d'origine chinoise né le 26 avril 1917 à Canton et mort le 16 mai 2019 à New York." },
  { titre: "Ignace Philippe Semmelweis", texte: "Ignaz Philipp Semmelweis (en hongrois : Semmelweis Ignác Fülöp), né le 1er juillet 1818 à Buda (qui fait aujourd'hui partie de Budapest en Hongrie) et mort le 13 août 1865 à Döbling près de Vienne, est un médecin obstétricien hongrois qui œuvra pour l'hygiène des mains." },
  { titre: "Indus", texte: "L’Indus est un fleuve d'Asie. Il coule depuis le Tibet et l’Himalaya en direction du sud-ouest et se jette dans la mer d'Arabie. L’Indus fait partie des sept rivières sacrées de l'Inde. Il passe par la Chine, l'Inde et dans sa majeure partie le Pakistan, où il constitue le seul grand fleuve du pays." },
  { titre: "Inflammation", texte: "L'inflammation est la réaction stéréotypée du système immunitaire, face à une agression externe (infection, trauma, brûlure, allergie, etc.) ou interne (cellules cancéreuses) des tissus." },
  { titre: "Inquisition espagnole", texte: "L'Inquisition espagnole, officiellement tribunal du Saint-Office de l'Inquisition (en espagnol : Tribunal del Santo Oficio de la Inquisición) est une juridiction religieuse sous contrôle du pouvoir royal établie en 1478 par une bulle du pape Sixte IV, à la demande de la reine de Castille Isabelle Ire et du roi" },
  { titre: "Insuline", texte: "L'insuline (du latin : insula « île ») est une hormone protéique sécrétée par les cellules β des îlots de Langerhans dans le pancréas, ainsi que dans les corps de Brockmann de certains poissons téléostéens." },
  { titre: "Intelligence", texte: "L'intelligence est l'ensemble des processus trouvés dans des systèmes, plus ou moins complexes, vivants ou non, qui permettent d'apprendre, de comprendre ou de s'adapter à des situations nouvelles." },
  { titre: "Intestin grêle", texte: "L'intestin grêle est la partie de l'appareil digestif humain située entre l'estomac et le gros intestin (côlon). Il comprend un segment fixe, le duodénum, suivi de deux segments mobiles intrapéritonéaux, le jéjunum puis l'iléon." },
  { titre: "Islamisme", texte: "L'islamisme est une doctrine prônant l'islam comme une idéologie politique. Elle consiste à mobiliser les musulmans autour d’un projet socio-politique fondé sur les normes et les lois religieuses (charia)." },
  { titre: "Jack Kirby", texte: "Jack Kirby, né Jacob Kurtzberg le 28 août 1917 dans le Lower East Side à New York et mort le 6 février 1994 à Thousand Oaks en Californie, est un dessinateur de bande dessinée et l'un des artistes les plus influents, célèbres et prolifiques de la bande dessinée américaine." },
  { titre: "Jackie Robinson", texte: "Jack Roosevelt Robinson, dit Jackie Robinson, né le 31 janvier 1919 à Cairo en Géorgie et mort le 24 octobre 1972 à Stamford dans le Connecticut, est un joueur américain de baseball ayant évolué dans la Ligue majeure de 1947 à 1956." },
  { titre: "Jackson Pollock", texte: "Jackson Pollock, né le 28 janvier 1912 à Cody dans le Wyoming et mort le 11 août 1956 à Springs dans l'État de New York, est un peintre américain de l'expressionnisme abstrait, mondialement connu de son vivant." },
  { titre: "Jalousie", texte: "La jalousie est une émotion secondaire qui représente des pensées et sentiments d'insécurité, de peur et d'anxiété concernant la perte anticipée ou pas d'un statut, d'un objet ou d'un lien affectif ayant une importante valeur personnelle." },
  { titre: "Jambon", texte: "Le jambon est l'appellation charcutière désignant la cuisse ou l'épaule entière du cochon (le plus souvent) destinée à être préparée crue (après salaison, séchage et parfois fumage) ou cuite (rôtie, grillée, braisée ou, comme le jambon blanc, bouillie)." },
  { titre: "Japonais", texte: "Le japonais est la langue du Japon, parlée par le peuple japonais. Néanmoins, aucune loi ne lui donne le statut de langue officielle, même si elle est la langue des documents officiels et de l'éducation." },
  { titre: "Jean Chrysostome", texte: "Jean Chrysostome, né à Antioche (aujourd'hui Antakya en Turquie) entre 344 et 349, et mort en 407 près de Comana, a été archevêque de Constantinople. Il est considéré comme un des pères de l'Église." },
  { titre: "Jean Le Rond d'Alembert", texte: "Jean Le Rond d'Alembert, connu sous le nom D'Alembert, et dont le nom est parfois écrit « Jean le Rond D'Alembert » ou « Dalembert », voire « Dalambert », est un mathématicien, physicien, philosophe et encyclopédiste français, né le 16 novembre 1717 à Paris où il est mort le 29 octobre 1783." },
  { titre: "Jeu de billes", texte: "Le jeu de billes est un jeu très courant dans les écoles. La façon la plus classique d'y jouer consiste à lancer sa bille sur celle de l'adversaire afin de l'obtenir. La collection et la recherche de billes rares jouent un rôle important dans le jeu." },
  { titre: "Jeu de société", texte: "Un jeu de société est une activité sociale ludique, structurée par des règles, qui se pratique à plusieurs. Certains jeux sont spécifiquement conçus pour encourager la coopération ou la compétition, favorisant l'interaction entre les joueurs." },
  { titre: "Jeunes-Turcs", texte: "Les Jeunes-Turcs (en turc : Jön Türk au singulier et Jön Türkler au pluriel) sont un mouvement politique nationaliste, moderniste et réformateur ottoman, officiellement connu sous le nom de Comité union et progrès (CUP, en turc İttihat ve Terakki Cemiyeti), dont les chefs ont mené une rébellion contre le sultan" },
  { titre: "Joseph Fourier", texte: "Jean Baptiste Joseph Fourier est un mathématicien et physicien français, né le 21 mars 1768 à Auxerre (Yonne) et mort le 17 mai 1830 à Paris." },
  { titre: "Joseph Haydn", texte: "Franz Joseph Haydn — il n'utilisait jamais son premier prénom —, né le 31 mars 1732 à Rohrau sur la Leitha en Basse-Autriche et mort le 31 mai 1809 à Vienne, est un compositeur autrichien." },
  { titre: "Joseph II", texte: "Joseph de Habsbourg-Lorraine, puis Joseph II, né le 13 mars 1741 à Vienne et mort le 20 février 1790 dans la même ville, est empereur du Saint-Empire romain germanique de 1765 à 1790." },
  { titre: "Jour", texte: "Le jour ou la journée est l'intervalle de temps qui sépare le lever du coucher du Soleil. Le matin, le plein jour est précédé par l'aube (aussi appelée « petit jour »), puis par l'aurore à la lumière plus vive." },
  { titre: "Julio-Claudiens", texte: "Les Julio-Claudiens ou dynastie julio-claudienne sont les membres de la famille impériale formant la première dynastie impériale romaine régnant sur l'Empire romain entre 27 av. J.-C. et 68 apr. J.-C., entre Auguste et Néron." },
  { titre: "Kabuki", texte: "Le kabuki est la forme épique du théâtre japonais traditionnel. Centré sur un jeu d'acteur à la fois spectaculaire et codifié, il se distingue par le maquillage élaboré des acteurs et l'abondance de dispositifs scéniques destinés à souligner les paroxysmes et les retournements de la pièce." },
  { titre: "Karachi", texte: "Karachi est la plus grande ville du Pakistan et la capitale économique et financière du pays. Avec une population de près de 19 millions d'habitants en 2023 pour une superficie de 3 527 km2, Karachi est l'une des villes les plus peuplées au monde." },
  { titre: "Karst", texte: "Le karst est une structure géomorphologique résultant de l'érosion hydrochimique et hydraulique de toutes roches solubles, principalement de roches carbonatées dont essentiellement des calcaires. Des structures karstiques se rencontrent en outre dans des chlorures évaporitiques." },
  { titre: "Katmandou", texte: "Katmandou (en népalais : काठमाडौं (kāṭhamāḍauṁ), काठमान्डु (kāṭhamānḍu), en nepalbhasha : येंदेय्‌ (yēndēy)), très rarement orthographiée Kathmandou, Kathmandu ou Katmandu, parfois appelée Kantipur du nom de l'ancienne cité-État, ou encore Yen — notamment par les Newars —, est la capitale politique et religieuse du" },
  { titre: "Kelvin", texte: "Le kelvin, du nom de William Thomson, dit Lord Kelvin, de symbole K, est l'unité de base de température thermodynamique dans le Système international." },
  { titre: "Kharkiv", texte: "Kharkiv, également Kharkov en français, est la capitale administrative de l’oblast de Kharkiv. Sa population s’élevait à 1 421 125 habitants le 1er janvier 2022 et la classait au deuxième rang des villes d'Ukraine." },
  { titre: "Khartoum", texte: "Khartoum, en arabe : الخرطوم (al-Khurṭūm), est la capitale du Soudan. Elle est située au confluent du Nil Blanc (venant du Soudan du Sud) et du Nil Bleu (venant d'Éthiopie)." },
  { titre: "Kigali", texte: "Kigali est la capitale du Rwanda, centre économique et administratif du pays. Sa population s'élevait à 1 745 555 habitants au recensement du 22 août 2022. La ville s'étend sur plusieurs collines." },
  { titre: "Kingston", texte: "Kingston est la capitale de la Jamaïque. Administrativement, elle forme la paroisse de Kingston, entièrement urbaine, qui relève du comté de Surrey, dans le sud-est du pays. Dans les" },
  { titre: "Lac Ontario", texte: "Le lac Ontario (en anglais : Lake Ontario) est l'un des cinq Grands Lacs d'Amérique du Nord. Il est bordé au nord, à l'ouest et au sud-ouest par la province canadienne de l'Ontario, et au sud et à l'est par l'État américain de New York." },
  { titre: "Lac Supérieur", texte: "Le lac Supérieur (en anglais : Lake Superior) est un lac situé au centre de l'Amérique du Nord. Il est le plus grand, le plus septentrional, le plus occidental et le plus élevé des Grands Lacs." },
  { titre: "Lac Tanganyika", texte: "Le lac Tanganyika, ou Tanganika, est l'un des Grands Lacs d'Afrique, deuxième lac africain par la surface après le lac Victoria, le troisième au monde par le volume après la mer Caspienne et le lac Baïkal, le deuxième au monde par la profondeur après le lac Baïkal, et le plus long lac d'eau douce du monde (677 km)." },
  { titre: "Lac Tchad", texte: "Le lac Tchad est un grand lac endoréique d'eau douce situé à la frontière entre le Niger (au nord-ouest), le Nigeria (au sud-ouest), le Cameroun (au sud) et le Tchad (à l'est)." },
  { titre: "Langues turciques", texte: "Les langues turciques, pour les distinguer du turc moderne de Turquie, ou langues turques, forment une famille d'une trentaine de langues réparties dans une vaste région allant de l'Europe de l'Est à l'ouest de la Chine et de Chypre à la Sibérie." },
  { titre: "Lave-linge", texte: "Un lave-linge ou une machine à laver (le linge), aussi appelé laveuse au Canada francophone et lessiveuse en Belgique, est un appareil électroménager conçu pour nettoyer les vêtements et le linge de maison." },
  { titre: "Le Bernin", texte: "Gian Lorenzo Bernini, dit le Bernin ou Cavalier Bernin (en italien : Cavaliere Bernini), né le 7 décembre 1598 à Naples et mort le 28 novembre 1680 à Rome, est un sculpteur, architecte et un peintre italien du baroque." },
  { titre: "Léopold Ier", texte: "Léopold Ier, né le 9 juin 1640, à Vienne (Autriche) et mort dans la même ville le 5 mai 1705, est empereur du Saint-Empire romain germanique, roi de Bohême et roi de Hongrie, archiduc d'Autriche." },
  { titre: "Litchi", texte: "Le Litchi de Chine (Litchi chinensis), le Litchi de Madagascar, ou plus simplement Litchi, ou Letchi, est un arbre fruitier de la famille des Sapindaceae, qui produit le fruit comestible du même nom. Cet arbre tropical est la seule espèce du genre Litchi." },
  { titre: "Livre", texte: "Un livre est un document écrit formant unité et conçu comme tel, composé de pages reliées les unes aux autres. Il a pour fonction d'être un support de l'écriture, permettant la diffusion et la conservation de textes de nature variée." },
  { titre: "Locomotive à vapeur", texte: "Une locomotive à vapeur est un type de locomotive, c'est un engin moteur pour les chemins de fer, mis en mouvement par une machine à vapeur. Ce type de moteur thermique est le plus couramment utilisé, de la naissance du chemin de fer jusque dans les années 1950." },
  { titre: "Logiciel", texte: "Un logiciel est un ensemble de séquences d'instructions informatiques appelées programmes, interprétables par une machine (ordinateur ou calculateur), et accompagnées d'un jeu de données (ordinairement structurées en fichiers) nécessaires à ces opérations." },
  { titre: "Lois de Mendel", texte: "Les lois de Mendel sont trois lois concernant les principes de l'hérédité biologique, énoncées par le moine et botaniste de nationalité austro-hongroise Gregor Mendel (1822-1884)." },
  { titre: "Lophiiformes", texte: "Les Lophiiformes, souvent appelés poissons-pêcheurs, sont un ordre de poissons marins benthiques. Il s'agit de poissons osseux ayant un mode de prédation caractéristique : la première épine de la nageoire dorsale, appelée illicium ou « tige », est surmontée de l’esca ou « leurre », leur permettant d’attirer des proies." },
  { titre: "Lucien de Samosate", texte: "Lucien de Samosate, né vers 120 et mort après 180, est un rhéteur et auteur satirique originaire de Samosate (Turquie actuelle), principale ville de Commagène, région alors intégrée à la province romaine de Syrie, qui écrivait en grec, dans un style néo-attique." },
  { titre: "Lucrèce", texte: "Lucrèce (en latin Titus Lucretius Carus) est un poète et philosophe latin du Ier siècle av. J.-C. (peut-être 98-55), auteur d'un seul ouvrage en six parties, le De rerum natura (De la nature des choses, qu’on traduit le plus souvent par De la nature), un long poème en style épique (hexamètre dactylique) qui décrit le" },
  { titre: "Luigi Pirandello", texte: "Luigi Pirandello est un écrivain, poète, nouvelliste, romancier et dramaturge italien né le 28 juin 1867 à Agrigente en Sicile et mort le 10 décembre 1936 à Rome." },
  { titre: "Lviv", texte: "Lviv (anciennement en français : Léopol, Lwów, Lvov ; en ukrainien : Львів, L'viv (/lʲwiu̯/ ) ; en polonais : Lwów (/lvuf/ ) ; en russe : Львов, Lvov (/lʲvof/) ; en allemand : Lemberg ; en yiddish : לעמבערג, Lemberg ; en hongrois : Illyvó) est le centre historique de la Galicie et la plus grande ville de la partie" },
  { titre: "Machhad", texte: "Machhad, parfois transcrit Mashhad, Mechhed ou Méched, est une grande ville du Nord-Est de l'Iran, capitale de la province du Khorassan-e Razavi, située à plus de 900 km à l'est de Téhéran." },
  { titre: "Machine à sous", texte: "Une machine à sous (aussi appelé bandit manchot) est un appareil électronique ou mécanique de jeux de hasard et d'argent qui ne demande aucune stratégie ou habileté particulière." },
  { titre: "Maillot de bain", texte: "Le maillot de bain, ou le costume de bain en Suisse et au Canada, est un vêtement destiné à cacher certaines parties du corps lors de la pratique de la natation, de la baignade, de la détente au bord de l'eau (plage, bronzage…) ou, plus généralement, lors de toute activité de plein air." },
  { titre: "Majorité sexuelle", texte: "La majorité sexuelle est l'âge au-dessous duquel une personne civilement mineure ne peut se livrer à une activité sexuelle avec une personne civilement majeure sans que celle-ci commette une infraction pénale conformément au droit national." },
  { titre: "Mangrove", texte: "La mangrove est un écosystème de marais maritime incluant un groupement de végétaux spécifiques principalement ligneux, ne se développant que dans la zone de balancement des marées, des côtes basses des régions tropicales." },
  { titre: "Marais", texte: "En géographie, un marais est une couche d'eau stagnante, en général peu profonde, et envahie par la végétation aquatique ou herbacée. C'est une zone humide." },
  { titre: "Marcel Mauss", texte: "Marcel Mauss, né le 10 mai 1872 à Épinal (département des Vosges), mort le 11 février 1950 à Paris (14e arrondissement), est un sociologue et anthropologue, généralement considéré comme le « père de l'anthropologie française »." },
  { titre: "Marelle", texte: "La marelle (de merel, mereau, XIIe siècle, « palet, jeton, caillou »), ou palet, est un jeu enfantin pratiqué sur un schéma tracé au sol, le plus souvent dans la cour de récréation des écoles primaires." },
  { titre: "Margarine", texte: "La margarine est une préparation culinaire inventée par Hippolyte Mege-Mouries, à la suite d'un concours organisé par Napoléon III en 1869 afin de trouver un produit susceptible de remplacer le beurre, qui était une denrée rare et coûteuse." },
  { titre: "Masse", texte: "En physique, la masse est une grandeur physique positive intrinsèque d'un corps, qui mesure sa résistance à l'accélération. L'unité de masse dans le Système international d'unités (SI) est le kilogramme (kg)." },
  { titre: "Matrice", texte: "En mathématiques, une matrice se présente comme un tableau rectangulaire de nombres ou plus formellement comme une famille d'éléments (souvent appelés coefficients) indexés par un numéro de ligne et un numéro de colonne." },
  { titre: "Maurice de Saxe", texte: "Maurice de Saxe, né le 28 octobre 1696 à Goslar (ville libre d'Empire) et mort le 30 novembre 1750 au château de Chambord, est un militaire français d'origine saxonne, titré comte de la Raute (1696-1710) puis comte de Saxe (1710-1750)." },
  { titre: "Maurits Cornelis Escher", texte: "Maurits Cornelis Escher, né le 17 juin 1898 à Leeuwarden (Frise) et mort le 27 mars 1972 à Laren (Hollande-Septentrionale), plus couramment nommé M. C. Escher, est un artiste néerlandais, connu pour ses gravures sur bois, manières noires et lithographies souvent inspirées des mathématiques et des motifs de l'art" },
  { titre: "Max Planck", texte: "Max Planck, né Max Karl Ernst Ludwig Planck le 23 avril 1858 à Kiel dans le duché de Holstein et mort le 4 octobre 1947 à Göttingen en Allemagne occupée, est un physicien allemand." },
  { titre: "Maxime Gorki", texte: "Maxime Gorki,, nom de plume d’Alekseï Maksimovitch Pechkov, est un écrivain russe né le 16 mars 1868 (28 mars dans le calendrier grégorien) à Nijni Novgorod et mort le 18 juin 1936 à Moscou." },
  { titre: "Maya Angelou", texte: "Maya Angelou, de son vrai nom Marguerite Annie Johnson, née le 4 avril 1928 à Saint-Louis (Missouri) aux États-Unis, et morte le 28 mai 2014 à Winston-Salem (Caroline du Nord), est une romancière, poète, dramaturge essayiste, actrice, scénariste, productrice, documentariste, professeure d'université et militante" },
  { titre: "Méandre", texte: "Un méandre, qui doit son nom à un fleuve de Turquie, est une sinuosité très prononcée du cours d'un fleuve ou d’une rivière, qui se produit naturellement lorsque le courant est suffisant pour éroder les berges en présence de matériaux plus résistants, d'embâcles ou de barrages de castors." },
  { titre: "Mécanique des fluides", texte: "La mécanique des fluides est un domaine de la physique consacré à l’étude du comportement des fluides (liquides, gaz et plasmas) et des forces internes associées." },
  { titre: "Médiane", texte: "En statistiques, on appelle médiane d'une série statistique quantitative un nombre tel qu'une moitié des valeurs de cette série lui sont inférieures, et l'autre moitié lui sont supérieures (en comptant, pour chaque valeur, toutes ses apparitions dans la série)." },
  { titre: "Méditation", texte: "Le terme méditation désigne un ensemble de pratiques mentales et corporelles qui impliquent en règle générale une focalisation de l’attention vers la respiration, un objet particulier, des caractéristiques telles que la pensée, des émotions, des sensations du corps." },
  { titre: "Meiji", texte: "L'empereur Meiji, ou prince Sachi no Miya, connu de son vivant en Occident par son nom personnel Mutsuhito, né à Kyoto le 3 novembre 1852, fut le 122e empereur du Japon du 3 février 1867 à sa mort le 30 juillet 1912." },
  { titre: "Menelik II", texte: "Menelik II (en ge'ez : ዳግማዊ ምኒልክ, dagmawi Menilek ), né Sahle Maryam (en ge'ez : ሳህለ ማርያም) le 17 août 1844 et mort le 12 décembre 1913, est prince, Négus du Choa, puis roi des rois (negusse negest) d'Éthiopie." },
  { titre: "Méthodisme", texte: "Le méthodisme est un courant du protestantisme issu d'un schisme avec l'Église anglicane, regroupant de nombreuses Églises d'orientations diverses, mais qui trouvent leur inspiration dans la prédication de John Wesley au XVIIIe siècle." },
  { titre: "Mithridate VI", texte: "Mithridate « Eupator » le Grand, plus couramment appelé Mithridate VI du Pont ou encore Mithridate Ier du Bosphore (né en 135 ou en 132 av. J.-C. et mort par suicide en 63 av. J.-C.), est un roi du Pont et du Bosphore de la dynastie des Mithridatides." },
  { titre: "Moctezuma II", texte: "Moctezuma II (ou Moteuczoma, Motecuhzoma), de son nom complet en nahuatl Motecuhzoma Xocoyotzin, né vers 1466 et mort le 29 juin 1520 à Mexico-Tenochtitlan, neuvième tlatoani de la cité de Mexico-Tenochtitlan, est à la tête de l'Empire aztèque de 1502 à 1520." },
  { titre: "Modeste Moussorgski", texte: "Modeste Petrovitch Moussorgski, né le 9 mars 1839 (21 mars dans le calendrier grégorien) à Karevo, près de Toropets dans le gouvernement de Pskov, et mort le 16 mars 1881 (28 mars dans le calendrier grégorien) à Saint-Pétersbourg, est un compositeur russe." },
  { titre: "Monarchie", texte: "La monarchie (du grec mono « seul », arkhe « pouvoir » : « pouvoir d'un seul ») est un régime politique où l'unité du pouvoir est symbolisée par une seule personne, appelée « monarque » et n'est pas nécessairement une royauté." },
  { titre: "Mondialisation", texte: "La mondialisation ou globalisation est un développement des échanges entre nations, dans une optique de libre échange, en minimisant les restrictions et les taxes aux frontières, des marchandises, des capitaux, des services, des personnes, des techniques et de l'information." },
  { titre: "Monnaie", texte: "La monnaie ou l'argent est définie par trois fonctions : c'est une unité de compte, une réserve de valeur, et un intermédiaire des échanges." },
  { titre: "Monrovia", texte: "Monrovia est la capitale du Liberia. Fondée en 1822, elle est située sur le cap Mesurado sur la côte atlantique et comptait, lors du recensement de 2022, 1 761 032 habitants, soit 33,5 % de la population totale du Libéria." },
  { titre: "Muscle", texte: "Le muscle est un organe contractile composé de tissu mou retrouvé chez les animaux. Il est composé de tissus musculaires et de tissus conjonctifs." },
  { titre: "Musique classique", texte: "La musique classique ou, plus précisément, la musique classique occidentale, est le nom habituellement donné à la musique occidentale « savante » de tradition écrite." },
  { titre: "Musique country", texte: "La musique country (en anglais : country music, « musique de la campagne ») est un mélange de musiques traditionnelles développé principalement dans le sud-est des États-Unis et dans les provinces maritimes du Canada, mais aussi en Europe comme en Irlande ou dans le nord des Pays-Bas." },
  { titre: "Musique électronique", texte: "La musique électronique est un groupe de genres musicaux dont la particularité est d'être générée essentiellement par des instruments électroniques de type synthétiseurs, claviers ou orgues électroniques, et dans laquelle le son tient une place prépondérante dans le processus de composition." },
  { titre: "Musique soul", texte: "La musique soul, ou simplement soul, est une musique populaire afro-américaine apparue à la fin des années 1950 aux États-Unis et dérivée, entre autres, à la fois du gospel et du rhythm and blues." },
  { titre: "Mustela putorius", texte: "Mustela putorius, le Putois, mais plus spécifiquement désigné sous le nom de Putois d’Europe, est une espèce de mammifère carnivore de la famille des Mustélidés. Cette espèce se trouve d’un bout à l’autre du continent européen, mais aussi dans les montagnes du Rif, en Afrique du Nord." },
  { titre: "Mythologie égyptienne", texte: "La mythologie égyptienne démontre un fort lien de cette civilisation avec la nature, les dieux sont mi-animaux comme Hathor (déesse à corps de vache) et Thot (dieu à tête d'ibis). De plus, ils représentent leur réalité géographique (Seth pour le désert), cosmique (la course du soleil), etc." },
  { titre: "Nellie Bly", texte: "Elizabeth Jane Cochrane, dite Nellie Bly, née le 5 mai 1864 à Cochran's Mills dans le comté d'Armstrong en Pennsylvanie et morte le 27 janvier 1922 à New York, est une journaliste américaine." },
  { titre: "Neurosciences", texte: "Les neurosciences sont les études scientifiques du système nerveux, de sa structure et de son fonctionnement, depuis l'échelle moléculaire jusqu'au niveau des organes, pour exemple le cerveau, aussi bien que de l'organisme nerveux entier." },
  { titre: "Niccolò Paganini", texte: "Niccolò Paganini, né le 27 octobre 1782 à Gênes et mort le 27 mai 1840 à Nice, est un violoniste, altiste, guitariste et compositeur génois." },
  { titre: "Nicolas de Myre", texte: "Nicolas de Myre ou Nicolas de Bari, communément connu sous le nom de saint Nicolas, est un Grec d'Anatolie né à Patare en Lycie (actuellement Turquie) vers 270 et mort à Myre en 343. Évêque de Myre en Lycie, il a probablement participé au premier concile de Nicée au cours duquel il combattit l'arianisme." },
  { titre: "Nicolas Gogol", texte: "Nicolas Vassiliévitch Gogol est un romancier, nouvelliste, dramaturge, poète et critique littéraire russe d'origine ukrainienne né le 20 mars 1809 (1er avril 1809 dans le calendrier grégorien) au domaine de Vassilievka, près de Sorotchintsy dans le gouvernement de Poltava (Empire russe, aujourd'hui en Ukraine) et mort" },
  { titre: "Nicolas Ier", texte: "Nicolas Ier de Russie, né le 6 juillet 1796 à Gatchina et mort le 2 mars 1855 à Saint-Pétersbourg, fut empereur de Russie, roi de Pologne et grand-duc de Finlande du 1er décembre 1825 jusqu'à sa mort." },
  { titre: "Nicolas Poussin", texte: "Nicolas Poussin, né en juin 1594 au hameau de Villers, dans la commune des Andelys, et mort le 19 novembre 1665 à Rome, est un peintre français du XVIIe siècle, représentant majeur du classicisme pictural." },
  { titre: "Nicotine", texte: "La nicotine est un alcaloïde toxique issu principalement de la plante de tabac (Nicotiana tabacum) utilisé comme psychotrope (stimulant), particulièrement lors de l'inhalation de la fumée du tabac. La nicotine agit directement sur le système nerveux, cette molécule est en partie responsable de la dépendance tabagique." },
  { titre: "Niels Bohr", texte: "Niels Henrik David Bohr (7 octobre 1885 à Copenhague, Danemark - 18 novembre 1962 à Copenhague) est un physicien danois. Il est surtout connu pour son apport à l'édification de la mécanique quantique, pour lequel il a reçu de nombreux honneurs." },
  { titre: "Nijni Novgorod", texte: "Nijni Novgorod ou Nijni-Novgorod, à l’époque soviétique Gorki, est l'une des principales villes de Russie. Elle est située dans la partie centrale de la Russie européenne au confluent de la Volga et de l'Oka, à 400 km à l'est-nord-est de la capitale du pays Moscou." },
  { titre: "Nirvana", texte: "Le nirvana (sanskrit IAST : nirvāṇa ; pali : nibbāna) est un concept philosophique de l'hindouisme, du jaïnisme et du bouddhisme qui signifie « extinction » (du feu des passions, de l'ignorance) ou « libération » (du saṃsāra, du cycle des réincarnations)." },
  { titre: "Noisette", texte: "La noisette est le fruit du noisetier commun (Corylus avellana), ainsi que de diverses espèces voisines du genre Corylus (non étudiées ici)." },
  { titre: "Noix", texte: "La noix est un fruit comestible à coque. Elle est produite par les noyers, arbres du genre Juglans L., de la famille des Juglandacées. La forme commercialisée la plus importante des régions tempérées provient de la culture du noyer commun." },
  { titre: "Noix de muscade", texte: "La noix de muscade (ou noix muscade) est l'albumen de la graine du fruit ovoïde du muscadier (Myristica fragrans), un arbre tropical de la famille des Myristicacées haut de dix à quinze mètres. La coque de la noix de muscade en est le tégument." },
  { titre: "Nombre", texte: "Un nombre est un concept mathématique permettant d’évaluer et de comparer des quantités ou des rapports de grandeurs, mais aussi d’ordonner des éléments en indiquant leur rang." },
  { titre: "Nouvel Empire", texte: "Le Nouvel Empire est la période la plus prospère de toute l'histoire égyptienne après l'âge d'or connu dans l'Ancien Empire. C'est une période de raffinement et d'évolutions qui s'étale sur un peu plus de cinq siècles." },
  { titre: "Nouvelle-Galles du Sud", texte: "La Nouvelle-Galles du Sud (NGS, en anglais : New South Wales, NSW) est le plus peuplé des États de l'Australie. Sa capitale est Sydney, ville la plus peuplée du pays." },
  { titre: "Nouvelle-Zemble", texte: "La Nouvelle-Zemble est un archipel russe des mers de Kara (pour les deux plus grandes îles) et de Barents (pour l'île Mejdoucharski et l'île Pankrat'yeva) situé au-delà du 70e parallèle nord dans le prolongement de l'Oural." },
  { titre: "Novossibirsk", texte: "Novossibirsk est une ville d'importance régionale de Russie, dans la plaine de Sibérie occidentale, et la capitale administrative de l’oblast de Novossibirsk. Ses habitants sont appelés les Novossibirskiens." },
  { titre: "Nuage", texte: "Un nuage est en météorologie une masse visible constituée initialement d'une grande quantité de gouttelettes d’eau (parfois de cristaux de glace associés à des aérosols chimiques ou des minéraux) en suspension dans l’atmosphère au-dessus de la surface d'une planète." },
  { titre: "Nuage de Oort", texte: "En astronomie, le nuage de Oort, ou nuage d'Oort, aussi appelé le nuage d'Öpik-Oort (/ˈø.pik/), est un vaste ensemble sphérique hypothétique de corps planétésimaux situé aux limites du Système solaire, approximativement entre 20 000 et 30 000 unités astronomiques (au) et jusqu'à plus de 100 000 au, au-delà des" },
  { titre: "Oblast de Kaliningrad", texte: "L'oblast de Kaliningrad est une entité constitutive de la fédération de Russie, dont le centre administratif est la ville de Kaliningrad. Rosstat lui attribue le code 27 et son code d'immatriculation est le 39." },
  { titre: "Olmèques", texte: "Les Olmèques sont un ancien peuple précolombien de Mésoamérique dont la culture apparaît aujourd’hui comme un ensemble multiethnique et plurilinguistique qui s’étend à partir de 2500 av. J.-C. jusqu’à 500 av. J.-C.." },
  { titre: "Organisation non gouvernementale", texte: "Une organisation non gouvernementale (ONG) est une structure d'intérêt public et à but non lucratif, dont la forme juridique est généralement, selon les pays, une association à but non lucratif ou une fondation à but non lucratif, qui ne relève ni de l'État ni d'institutions internationales." },
  { titre: "Orville et Wilbur Wright", texte: "Les frères Orville Wright (né le 19 août 1871 à Dayton et mort le 30 janvier 1948 dans la même ville) et Wilbur Wright (né le 16 avril 1867 à Millville dans l'Indiana et mort le 30 mai 1912 à Dayton) sont deux célèbres pionniers américains de l'aviation, à la fois chercheurs, ingénieurs, concepteurs, constructeurs et" },
  { titre: "Osamu Tezuka", texte: "Osamu Tezuka, né le 3 novembre 1928 à Toyonaka, dans la préfecture d'Osaka, et mort le 9 février 1989 à Tokyo, est un mangaka, animateur, character designer, producteur, scénariste d'anime." },
  { titre: "Oscar Niemeyer", texte: "Oscar Ribeiro de Almeida de Niemeyer Soares (né le 15 décembre 1907 à Rio de Janeiro, où il meurt le 5 décembre 2012) est un architecte et un designer brésilien." },
  { titre: "Osman Ier", texte: "Osman Ier, également appelé Osman Gazi en turc, est le fondateur de l'Empire ottoman (en turc : Osmanlı İmparatorluğu). Il est né vers 1258 à Söğüt, il est le fils d'Ertuğrul et lui succède en 1281. Osman meurt vers 1324 ou 1326." },
  { titre: "Othmân ibn Affân", texte: "Othman ibn Affan, également connu en français (par l'intermédiaire du turc et du persan) comme Osman, né en 574 à Taëf et mort assassiné en 656 à Médine, est le beau-fils et un éminent compagnon de Mahomet, prophète de l'islam, ainsi que le troisième calife bien guidé." },
  { titre: "Otton Ier", texte: "Otton Ier du Saint-Empire, surnommé en allemand Otto der Große (Otton le Grand en français), né le 23 novembre 912 à Wallhausen (Saxe) et mort le 7 mai 973 au palais familial de Memleben (Thuringe), est l'un des plus célèbres souverains allemands du Moyen Âge, fondateur du Saint-Empire romain germanique." },
  { titre: "Pablo Casals", texte: "Pau Carles Salvador Casals i Defilló, plus communément connu sous les noms de Pau Casals ou Pablo Casals, né le 29 décembre 1876 à El Vendrell (province de Tarragone, Espagne) et mort le 22 octobre 1973 à San Juan (Porto Rico), est un violoncelliste, chef d'orchestre et compositeur espagnol." },
  { titre: "Paco de Lucía", texte: "Francisco Sánchez Gómez, connu sous le nom de Paco de Lucía (né le 21 décembre 1947 à Algésiras, dans la province de Cadix, en Espagne, et mort le 25 février 2014 à Playa del Carmen, au Mexique) est un guitariste et compositeur espagnol." },
  { titre: "Palais de Dioclétien", texte: "Le palais de Dioclétien (en croate : Dioklecijanova palača) est la résidence impériale fortifiée construite par l'empereur romain Dioclétien sur la côte dalmate pour s'y retirer après son abdication volontaire en 305." },
  { titre: "Palais de Westminster", texte: "Le palais de Westminster (en anglais : 'Westminster Palace '), également désigné sous le nom de Chambres du Parlement (Houses of Parliament), est le lieu où siège le Parlement du Royaume-Uni : la Chambre des communes (House of Commons) et la Chambre des lords (House of Lords)." },
  { titre: "Paléozoïque", texte: "Le Paléozoïque est une ère géologique qui s'étend de −538,8 à −252,2 Ma. Anciennement appelée Ère Primaire ou Ère des Poissons, elle est la première ère du Phanérozoïque." },
  { titre: "Palmyre", texte: "Palmyre ou Tadmor est une ville antique de Syrie, située à proximité d'une oasis du désert de Syrie, à 210 km au nord-est de Damas et dont les ruines sont adjacentes à la ville moderne de Tadmor." },
  { titre: "Pampa", texte: "La pampa (« plaine » en quechua) est un milieu naturel qui forme un biome du type prairies, savanes et brousses tempérées, ou extérieurs enneigés. C'est une plaine fertile recouverte d'herbes (à dominante de graminées) et presque dépourvue d’arbres." },
  { titre: "Papyrus", texte: "Le papyrus (pluriel : papyrus, pluriel latin : papyri) est un support d'écriture obtenu grâce à la transformation des tiges d’une plante africaine, également appelée papyrus (Cyperus papyrus), en une surface souple, lisse, de plusieurs mètres de long, facile à replier en rouleau." },
  { titre: "Paracelse", texte: "Paracelse ou Paracelsus, dont le nom d'origine est Philippus Theophrastus Aureolus Bombast von Hohenheim, né le 10 novembre 1493 à Einsiedeln (en Suisse centrale) et mort le 24 septembre 1541 à Salzbourg (aujourd'hui en Autriche), est un médecin, philosophe et alchimiste, mais aussi théologien laïc suisse," },
  { titre: "Parallaxe", texte: "La parallaxe est l’impact d'un changement d'incidence d'observation, c'est-à-dire du changement de position de l'observateur, sur l'observation d'un objet. En d'autres termes, la parallaxe est l'effet du changement de position de l'observateur sur ce qu'il perçoit." },
  { titre: "Parfum", texte: "Un parfum est une odeur ou plus souvent une composition odorante plus ou moins persistante naturellement émise par une plante, un animal, un champignon ou un environnement. Dans la nature, les parfums sont souvent des messages chimiques et biochimiques, et notamment des phéromones ou phytohormones." },
  { titre: "Parsec", texte: "Le parsec, de symbole pc, est une unité de longueur utilisée en astronomie. Il est défini comme valant exactement 648 000/π unités astronomiques, soit environ 3,26 années-lumière." },
  { titre: "Particule élémentaire", texte: "En physique des particules, une particule élémentaire, ou particule fondamentale, est une particule dont on ne connaît pas la composition : on ne sait pas si elle est constituée d'autres particules plus petites." },
  { titre: "Pasteurisation", texte: "La pasteurisation, ou débactérisation thermocontrôlée, est un procédé de conservation des aliments par chauffage à une température comprise entre 70 et 100 °C, pendant une durée définie, suivi d'un refroidissement rapide." },
  { titre: "Peanuts", texte: "Peanuts, aussi connu en version française sous les noms de Snoopy, Snoopy et les Peanuts, Snoopy et le petit monde des Peanuts ou Charlie Brown, est un comic strip écrit et dessiné par l'Américain Charles M. Schulz (1922-2000), publié sans interruption ni assistance du 2 octobre 1950 au 13 février 2000." },
  { titre: "Peinture", texte: "La peinture est une forme artistique dont les diverses techniques consistent à appliquer manuellement ou mécaniquement, sur une surface, des couleurs sous forme de pigments mélangés à un liant ou un diluant." },
  { titre: "Peinture à l'huile", texte: "La peinture à l'huile est une peinture dont le liant ou véhicule est une huile siccative qui enveloppe complètement les particules de pigment." },
  { titre: "Péninsule", texte: "Une péninsule (du latin paeninsula, paene signifiant « presque » et insula « île ») est une partie de terres émergées rattachée à une masse continentale par un de ses côtés. Elle se distingue d'une presqu'île par sa taille supérieure ou par l’absence d’isthme." },
  { titre: "Période des Royaumes combattants", texte: "La période des Royaumes combattants (chinois simplifié : 战国 ; chinois traditionnel : 戰國 ; pinyin : zhànguó ; litt. « pays (guó) en guerre (zhàn) ») s'étend, dans l'histoire de la Chine, du Ve siècle av. J.-C. à l'unification des royaumes chinois par la dynastie Qin en 221 av. J.-C. Ce nom lui est donné tardivement," },
  { titre: "Période Jōmon", texte: "La période Jōmon ou l'ère Jōmon est l'une des quatorze subdivisions traditionnelles de l'histoire du Japon. Elle couvre la période qui va, approximativement, de 13 000 jusqu'à, environ, 400 av. J.-C. Le Japon est alors peuplé par des chasseurs-cueilleurs." },
  { titre: "Personnage de fiction", texte: "Un personnage de fiction est un être imaginaire issu d'une œuvre de fiction. La création et le développement des personnages sont appelés représentation, peinture ou traitement des personnages." },
  { titre: "Peste bubonique", texte: "La peste bubonique est la forme la plus fréquente de peste en milieu naturel. Elle fait le plus souvent suite à l'infection par la morsure de puces infectées provenant d'un rat ou autre petit mammifère, mais elle peut également se faire par l'exposition à des liquides biologiques d'un animal mort infecté par la peste." },
  { titre: "Phineas Taylor Barnum", texte: "Phineas Taylor Barnum, né le 5 juillet 1810 à Bethel (Connecticut) et mort le 7 avril 1891 à Bridgeport (Connecticut), est un homme d'affaires et entrepreneur du monde du spectacle américain, devenu par la suite homme politique." },
  { titre: "Pierre Boulez", texte: "Pierre Boulez, né le 26 mars 1925 à Montbrison (Loire) et mort le 5 janvier 2016 à Baden-Baden (Bade-Wurtemberg, Allemagne), est un compositeur et chef d'orchestre français." },
  { titre: "Pierre de Fermat", texte: "Pierre de Fermat, né dans la première décennie du XVIIe siècle, à Beaumont-de-Lomagne (département actuel de Tarn-et-Garonne), près de Montauban, et mort le 12 janvier 1665 à Castres (département actuel du Tarn), est un magistrat, polymathe et surtout mathématicien français, surnommé par E.T. Bell « le prince des" },
  { titre: "Pierre Ier", texte: "Pierre Ier (en portugais : Pedro I do Brasil), également connu sous le nom de Pierre IV (portugais : Pedro IV de Portugal), est né le 12 octobre 1798 au palais de Queluz, à Lisbonne, au Portugal, et mort le 24 septembre 1834 au même endroit." },
  { titre: "Pierre II", texte: "Pierre II ou Pedro II (de son nom complet Pedro de Alcântara João Carlos Leopoldo Salvador Bibiano Francisco Xavier de Paula Leocádio Miguel Gabriel Rafael Gonzaga), né le 2 décembre 1825 à Rio de Janeiro et mort le 5 décembre 1891 à Paris (8e arrondissement), est empereur du Brésil de 1831 à 1889." },
  { titre: "Pierre Kropotkine", texte: "Pierre Kropotkine, né le 9 décembre 1842 (27 novembre du calendrier julien) à Moscou dans l'Empire russe et mort le 8 février 1921 à Dmitrov près de Moscou, issu d'une lignée princière riourikide, est un géographe, explorateur, zoologiste, anthropologue et géologue russe, ainsi que, sur le plan politique, un" },
  { titre: "Pierre Paul Rubens", texte: "Pierre Paul Rubens — ou Petrus Paulus Rubens, ou Peter Paul Rubens en néerlandais, et Pietro Paolo Rubens à partir de 1608 — est un peintre anversois de l'école baroque flamande, né le 28 juin 1577 à Siegen (principauté de Nassau-Dillenbourg) et mort le 30 mai 1640 à Anvers." },
  { titre: "Pierre-Simon de Laplace", texte: "Pierre-Simon de Laplace ou Pierre-Simon Laplace, comte Laplace, puis 1er marquis de Laplace, né le 23 mars 1749 à Beaumont-en-Auge et mort le 5 mars 1827 à Paris, est un mathématicien, astronome, physicien et homme politique français." },
  { titre: "Plotin", texte: "Plotin, né en 205 à Lycopolis et mort en 270 à Naples, philosophe gréco-romain de l'Antiquité tardive, est le représentant principal du courant philosophique appelé « néoplatonisme » : à travers lui, la pensée grecque classique affronte désormais les mouvements gnostiques plus ou moins proches du christianisme et du" },
  { titre: "Plutonium", texte: "Le plutonium est l'élément chimique de symbole Pu et de numéro atomique 94. C'est un métal radioactif transuranien de la famille des actinides." },
  { titre: "Poids", texte: "Le poids est la force de la pesanteur, d'origine gravitationnelle et inertielle, exercée, par exemple, par la Terre sur un corps massique en raison uniquement du voisinage de la Terre. Son unité dans le Système international est le newton." },
  { titre: "Point de Lagrange", texte: "Un point de Lagrange (noté L1 à L5), ou, plus rarement, point de libration, est une position de l'espace où les champs de gravité de deux corps en mouvement orbital l'un autour de l'autre, et de masses substantielles, fournissent exactement la force centripète requise pour que ce point de l'espace accompagne" },
  { titre: "Poireau", texte: "Le poireau cultivé (Allium ampeloprasum var. porrum, anciennement Allium porrum) est une variété d'une espèce de plantes à fleurs herbacées vivaces largement cultivée comme plante potagère pour ses feuilles (pseudo-tiges) consommées comme légumes." },
  { titre: "Pois cultivé", texte: "Le Pois cultivé (Pisum sativum, syn. Lathyrus oleraceus) est une espèce de plantes annuelles de la famille des Fabacées, largement cultivée pour ses graines et consommée comme légume ou utilisée comme aliment du bétail." },
  { titre: "Poison", texte: "Les poisons sont, en biologie, des substances qui provoquent des blessures, des maladies ou la mort d'organismes par une réaction chimique, à l'échelle moléculaire. Cette définition exclut les agents physiques, même de petite taille (un caillot, une bulle d'air dans le sang, un courant électrique, une radiation, etc.)." },
  { titre: "Police", texte: "Le terme « police » désigne à la fois une fonction de puissance publique et l'ensemble des institutions chargées d'assurer la sécurité des personnes et des biens, de prévenir les infractions, de maintenir l'ordre public et de faire appliquer la loi." },
  { titre: "Politique de l'enfant unique", texte: "La politique de l'enfant unique est une politique publique ayant pour but la régulation des naissances. Elle est mise en œuvre par la république populaire de Chine de 1979 à 2015." },
  { titre: "Processeur", texte: "Un processeur (ou unité centrale de calcul, UCC ; en anglais central processing unit, CPU) ou unité centrale de traitement est un composant électronique présent dans de nombreux dispositifs électroniques qui exécute les instructions machine des programmes informatiques, c’est le « cerveau » de l’ordinateur." },
  { titre: "Programmation informatique", texte: "La programmation informatique est l'ensemble des activités liées à la conception, l'écriture, le test et la maintenance de programmes informatiques à l'aide de langages de programmation." },
  { titre: "Pseudoscorpiones", texte: "Les Pseudoscorpions (Pseudoscorpionida, Pseudoscorpiones ou Chelonethida), connus également sous le nom de « faux scorpions » ou chernètes, sont un ordre d'arachnides. Le pseudoscorpion ne possède pas la fameuse queue du scorpion." },
  { titre: "Pseudotsuga menziesii", texte: "Pseudotsuga menziesii est une espèce de conifère de la famille des Pinaceae, originaire de l'ouest de l'Amérique du Nord. En français on l’appelle principalement Douglas." },
  { titre: "Psychiatrie", texte: "La psychiatrie est une spécialité médicale traitant de la maladie mentale. Le mot « psychiatre » a été forgé à partir des noms grecs ψυχή / psykhḗ, « souffle de vie, âme », et ἰατρός / iatrós, « médecin » (littéralement « médecin de l'âme »)." },
  { titre: "Psychologie de la forme", texte: "La psychologie de la forme, théorie de la Gestalt ou gestaltisme (de l'allemand, Gestaltpsychologie) est une théorie psychologique et philosophique proposée au début du XXe siècle selon laquelle les processus de la perception et de la représentation mentale traitent les phénomènes comme des formes globales plutôt que" },
  { titre: "Psychose", texte: "La psychose est un terme générique d'utilisation très variée, désignant en psychiatrie une maladie mentale où le sujet n'est pas conscient de son trouble. La psychose évoque le plus souvent une « perte de contact avec la réalité »." },
  { titre: "Quark", texte: "En physique des particules, un quark est une particule élémentaire et un constituant de la matière observable. Les quarks s'associent entre eux pour former différents types de hadrons, des particules composites (notamment les protons et les neutrons, les seuls qui soient aussi des constituants de la matière)." },
  { titre: "Quasar", texte: "Un quasar (source de rayonnement quasi-stellaire, quasi-stellar radiosource en anglais, ou plus récemment « source de rayonnement astronomique quasi-stellaire », quasi-stellar astronomical radiosource) est un trou noir supermassif au centre d'une région extrêmement lumineuse (noyau actif de galaxie)." },
  { titre: "Quaternaire", texte: "Le Quaternaire est la troisième et dernière période géologique de l'ère du Cénozoïque, après le Paléogène et le Néogène. C'est la plus récente sur l'échelle des temps géologiques et elle est toujours en cours." },
  { titre: "Rachi", texte: "Rabbi Chlomo ben Itzhak HaTzarfati, plus connu sous les noms de Rachi, Rabbi Salomon et Salomon de Troyes, né vers 1040 à Troyes où il est mort le 13 juillet 1105, est un rabbin, exégète, talmudiste, poète, légiste et décisionnaire français." },
  { titre: "Rafael Trujillo", texte: "Rafael Leónidas Trujillo Molina, né le 24 octobre 1891 à San Cristóbal et mort le 30 mai 1961 à Ciudad Trujillo, est un militaire et homme d'État dominicain qui fut à deux reprises président de la République dominicaine (1930-1938 et 1942-1952)." },
  { titre: "Ralph Waldo Emerson", texte: "Ralph Waldo Emerson, né le 25 mai 1803 à Boston (Massachusetts) et mort le 27 avril 1882 à Concord (Massachusetts), est un essayiste, philosophe et poète américain, chef de file du mouvement transcendantaliste américain du début du XIXe siècle." },
  { titre: "Réaction d'oxydoréduction", texte: "Une réaction d'oxydoréduction ou réaction rédox est une réaction chimique au cours de laquelle se produit un transfert d'électrons. Elle consiste en une réaction oxydante, couplée à une réaction réductrice." },
  { titre: "Récif corallien", texte: "Un récif corallien ou une barrière de corail est une structure naturelle bioconstruite à l'origine de laquelle sont essentiellement les coraux. La plus grande de ces formations, la Grande Barrière de corail, au large des côtes australiennes, s'étend sur quelque 2 000 km et est visible depuis l'espace." },
  { titre: "Rein", texte: "Le rein est un organe de l'appareil urinaire des vertébrés. Il a de multiples fonctions : hormonales, de régulation de la pression sanguine et d'élimination des toxines. Il assure ainsi, par filtration et excrétion d'urine, l'équilibre hydroélectrolytique (homéostasie) du sang et de l'organisme en général." },
  { titre: "Reproduction", texte: "En biologie, la reproduction est un processus biologique qui permet la production de nouveaux organismes d'une espèce à partir d'individus préexistants de cette espèce." },
  { titre: "Requin-tigre", texte: "Le Requin-tigre (Galeocerdo cuvier) est une espèce de requins de l'ordre des Carcharhiniformes, et l'unique représentant actuel du genre Galeocerdo et de la famille des Galeocerdonidae." },
  { titre: "Réseau informatique", texte: "Un réseau informatique est un ensemble d’ordinateurs et d’équipements communicants (appelés hôtes) capables d’échanger des données à l’aide de protocoles de communication et de matériel réseau." },
  { titre: "Restaurant", texte: "Un restaurant est un établissement de commerce où l'on sert des plats préparés et des boissons à consommer sur place, en échange d'un paiement." },
  { titre: "Restauration de Meiji", texte: "La restauration de Meiji, aussi appelée révolution de Meiji ou renouvellement de Meiji, est la période de l'histoire du Japon correspondant au renversement du shogunat Tokugawa et au recouvrement des pouvoirs de Meiji, empereur du Japon, en 1868 (à la fin de l'ère Keiō)." },
  { titre: "Restauration rapide", texte: "La restauration rapide, également appelée fast-food ou fastfood (de l’anglais fast food), est un mode de restauration dont le but est de faire gagner du temps au client en lui permettant de consommer rapidement les plats commandés ou de les emporter, pour un prix généralement moindre que dans la restauration" },
  { titre: "Réunification allemande", texte: "La réunification allemande (allemand : deutsche Wiedervereinigung, ou dans les lois allemandes Herstellung der Einheit Deutschlands) est le processus qui, d'octobre 1989 à octobre 1990, a conduit à l'intégration de la République démocratique allemande dans la République fédérale d'Allemagne, laquelle était constituée" },
  { titre: "Révolte des cipayes", texte: "La révolte des cipayes est un soulèvement populaire qui a lieu en Inde en 1857 contre la Compagnie britannique des Indes orientales. Il est également appelé première guerre d'indépendance indienne ou rébellion indienne de 1857." },
  { titre: "Révolte des Taiping", texte: "La révolte des Taiping est une révolte armée devenue une guerre totale qui eut lieu dans le sud, puis le centre de la Chine, entre 1851 et 1864." },
  { titre: "Révolution belge", texte: "La révolution belge désigne la révolte du peuple belge, habitant majoritairement les huit provinces méridionales du royaume uni des Pays-Bas (Anvers, Brabant, Flandre-Occidentale, Flandre-Orientale, Hainaut, Liège, Limbourg, et province de Namur ; le grand-duché de Luxembourg étant alors propriété privée du roi des" },
  { titre: "Révolution chinoise de 1911", texte: "La révolution chinoise de 1911 ou révolution Xinhai est une période de bouleversements sociaux et politiques de grande envergure en Chine qui aboutit au renversement de la dynastie des Qing après 268 ans de règne (1644-1912)." },
  { titre: "Révolution cubaine", texte: "La révolution cubaine est l'ensemble des événements commençant en 1953 ayant conduit en janvier 1959 au renversement du régime de Fulgencio Batista, soutenu par les États-Unis, et aboutissant à l’actuelle république de Cuba." },
  { titre: "Révolution russe de 1905", texte: "La révolution russe de 1905 englobe l'ensemble des troubles politiques et sociaux qui agitèrent l'Empire russe en 1905. Elle commence le 9 janvier 1905 (22 janvier dans le calendrier grégorien), lors du « Dimanche rouge », et aboutit neuf mois plus tard à la promesse d'une constitution, le Manifeste d'octobre." },
  { titre: "Révolution sexuelle", texte: "Les expressions « révolution sexuelle » et « libération sexuelle » recouvrent les changements du comportement sexuel entamés dans les années 1960 : reconnaissance des sexualités non procréatrices ; affirmation de l'égalité des sexes ; légalisation de la contraception et de l'avortement" },
  { titre: "Rhum", texte: "Le rhum (anglais : rum, espagnol : ron, portugais : rum) est une eau-de-vie produite par fermentation puis distillation de dérivés de canne à sucre : mélasse (on parle alors de rhum industriel, rhum de sucrerie ou rhum traditionnel), jus de canne frais (on parle alors de rhum agricole) ou autres sous-produits de" },
  { titre: "Rideau de fer", texte: "Le rideau de fer (en anglais : Iron Curtain, en allemand : Eiserner Vorhang) est la frontière physique et idéologique au sein de l'Europe, entre les pays du bloc de l'Ouest (capitaliste, sous l'influence des États-Unis) et ceux du bloc de l'Est (communiste, sous l'influence de l'URSS) pendant la guerre froide." },
  { titre: "Riga", texte: "Riga est la capitale de la Lettonie. Construite sur la mer Baltique au fond du golfe de Riga, dans lequel se jette la Daugava, c'est un centre industriel, commercial, culturel et financier majeur de la région de Vidzeme." },
  { titre: "Rio Paraná", texte: "Le rio Paraná est un fleuve qui s'écoule des hauts plateaux brésiliens vers l'Argentine pour se jeter dans l'océan Atlantique à travers le río de la Plata. Avec ses affluents, il constitue le sixième réseau hydrographique du monde et le troisième d'Amérique." },
  { titre: "Robert Guiscard", texte: "Robert de Hauteville dit Robert Guiscard (en italien : Roberto d'Altavilla, Roberto il Guiscardo ; en latin : Robertus de Altavilla, Robertus cognomento Guiscardus, Robertus Wiscardus), né après 1015 à Hauteville et mort le 17 juillet 1085 à Céphalonie, comte d'Apulie (1057-1059), puis duc d'Apulie, de Calabre et de" },
  { titre: "Robert Mugabe", texte: "Robert Gabriel Karigamombe Mugabe, dit Robert Mugabe, né le 21 février 1924 à Kutama en Rhodésie du Sud (actuel Zimbabwe) et mort le 6 septembre 2019 à Singapour, est un homme d'État zimbabwéen. Il est Premier ministre de 1980 à 1987 et président de la république du Zimbabwe de 1987 à 2017." },
  { titre: "Rostov-sur-le-Don", texte: "Rostov-sur-le-Don, communément abrégé en Rostov, est la plus grande ville du Sud-Ouest de la Russie, et le centre administratif du district fédéral du Sud et de l'oblast de Rostov. La ville forme sa propre subdivision en tant qu'okroug urbain au sein de l'oblast." },
  { titre: "Rugby à XIII", texte: "Le rugby à XIII, appelé rugby league dans les pays anglophones, est un sport collectif de contact opposant deux équipes de treize joueurs sur un terrain rectangulaire de 68 m de large et 112 à 122 m de long, équipé de poteaux en forme de H. Il constitue, avec le rugby à XV, l’un des deux principaux codes du rugby." },
  { titre: "Samoa américaines", texte: "Les Samoa américaines (en anglais : American Samoa) sont un territoire non incorporé et non organisé des États-Unis situé en Océanie. Les Samoa américaines sont la partie américaine de l'archipel des Samoa, divisé le 2 décembre 1899 par un traité entre, notamment, l'Empire allemand et les États-Unis." },
  { titre: "San Diego", texte: "San Diego est une ville américaine, située dans l'État de Californie, sur la côte ouest, au bord de l'océan Pacifique, près de la frontière avec le Mexique." },
  { titre: "Sardine", texte: "La sardine (Sardina pilchardus) est une espèce de poissons de la famille des Alosidae (qui comprend également l'alose). Selon la région, elle prend les noms de célan, célerin, pilchard, royan, sarda, sardinyola ou magne." },
  { titre: "Sargon d'Akkad", texte: "Sargon d’Akkad (akkadien : Šarru(m)-kīn ; « Roi légitime » ; « le Roi est légitime » ou encore « Roi loyal »), est le fondateur de l'Empire d'Akkad. Il unifia par la force les principales cités de Mésopotamie sous son autorité." },
  { titre: "Sarmates", texte: "Les Sarmates (Sauromates pour les Sarmates protohistoriques) sont un ancien peuple cavalier scythique de nomades de la steppe pontique, appartenant sur le plan ethno-linguistique au rameau iranien oriental septentrional du grand ensemble indo-européen." },
  { titre: "Saule", texte: "Le saule (Salix) est un genre de plantes à fleurs de la famille des Salicacées (Salicaceae). Il comprend 360 espèces environ, réparties à travers le monde, principalement dans les zones fraîches et humides des régions tempérées et froides de l'hémisphère nord." },
  { titre: "Saxons", texte: "Les Saxons sont un peuple germanique, rattaché sur le plan ethnolinguistique au rameau occidental. Ils sont mentionnés pour la première fois par le grec Ptolémée sur la carte Germania Magna au IIe siècle de l'ère chrétienne." },
  { titre: "Science politique", texte: "La science politique, également appelée politologie, est une discipline académique qui étudie les phénomènes politiques. L'objet de la science politique est celle de l'étude scientifique du fait politique, du mouvement politique et des phénomènes relatifs aux systèmes politiques." },
  { titre: "Sciences sociales", texte: "Les sciences sociales sont un ensemble de disciplines académiques ayant en commun l'étude du social humain, et des interactions sociales entre les individus, les groupes et leurs environnements." },
  { titre: "Sécurisexe", texte: "Le sexe sans risque (SSR), sexe à moindre risque (anglais : safe sex, safer sex) ou sécurisexe est un mode de relations sexuelles qui minimise les risques de contracter une infection sexuellement transmissible telles le VIH, le papillomavirus humain, l'hépatite B, l'herpès génital ou encore la syphilis." },
  { titre: "Séleucides", texte: "Les Séleucides sont une dynastie de l'époque hellénistique issue de Séleucos Ier, l'un des Diadoques d'Alexandre le Grand, qui a constitué un empire formé de la majeure partie des territoires orientaux conquis par Alexandre, allant de l'Anatolie à l'Indus." },
  { titre: "Sélim Ier", texte: "Sélim Ier, dit « le Brave » ou « le Terrible » (en turc : yavuz, « brave », « hardi », « audacieux »), né le 10 octobre 1470 à Amasya et mort le 22 septembre 1520 à Constantinople, est le neuvième sultan de l'Empire ottoman." },
  { titre: "Sémiotique", texte: "La sémiotique (également appelée études sémiotiques) est la discipline scientifique qui étudie les signes, la production et la réception du sens. Elle peut être considérée comme la science de la signification." },
  { titre: "Séparation des pouvoirs", texte: "La séparation des pouvoirs législatif, exécutif et judiciaire est un principe fondamental des démocraties représentatives. Au contraire, les régimes despotiques et dictatoriaux pratiquent une concentration des pouvoirs." },
  { titre: "Serbo-croate", texte: "Le serbo-croate, également appelé bosnien-croate-monténégrin-serbe ou BCMS, ou encore yougoslave, est une langue slave méridionale parlée dans l’ancienne Yougoslavie à la fois par les Serbes, les Croates, les Bosniaques et les Monténégrins. « Serbo-croate » était sa dénomination officielle dans l'ancienne Yougoslavie." },
  { titre: "Sesame Street", texte: "Sesame Street est une série télévisée éducative américaine pour enfants créée par Joan Ganz Cooney et Lloyd Morrisett, produite par Children's Television Workshop et diffusée depuis le 10 novembre 1969 sur le réseau PBS." },
  { titre: "Sexisme", texte: "Le sexisme est une attitude discriminatoire fondée sur le sexe, ou, par extension, sur le genre d'une personne. Le sexisme est lié aux préjugés et au concept de stéréotype et de rôle de genre, pouvant comprendre la croyance qu'un sexe ou qu'un genre serait intrinsèquement supérieur à l'autre." },
  { titre: "Soeharto", texte: "Suharto (également retranscrit Soeharto), né le 8 juin 1921 et mort le 27 janvier 2008 à Jakarta, est un général militaire, homme d'État indonésien, et président de la république d'Indonésie de 1967 à 1998." },
  { titre: "Soekarno", texte: "Soekarno ou Sukarno, né Koesno Sosrodihardjo le 6 juin 1901 à Surabaya et mort le 21 juin 1970 à Jakarta, est le premier président de la république d'Indonésie (1945-1967) dont il a proclamé l'indépendance le 17 août 1945 avec Hatta, le premier vice-président." },
  { titre: "Spectrométrie de masse", texte: "La spectrométrie de masse est une technique physique d'analyse permettant de détecter et d'identifier des molécules d’intérêt par mesure de leur masse, et de caractériser leur structure chimique." },
  { titre: "Sphenisciformes", texte: "Les Sphénisciformes (Sphenisciformes) sont un ordre d'oiseaux de mer inaptes au vol vivant dans l'hémisphère sud et dont les membres sont appelés « manchots ». Les manchots à aigrettes (le genre Eudyptes) sont également nommés « gorfous »." },
  { titre: "Sphère", texte: "En géométrie dans l'espace, une sphère est une surface constituée de tous les points situés à une même distance d'un point appelé centre. La valeur de cette distance au centre est le rayon de la sphère." },
  { titre: "Sphyraena", texte: "Sphyraena est un genre de poissons, communément appelés barracudas, bécunes ou sphyrènes, de la famille monotypique des Sphyraenidae. Ce genre regroupe entre 18 et 20 espèces de poissons prédateurs réparties dans les eaux tropicales et subtropicales." },
  { titre: "Spin", texte: "Le spin (/spin/) est, en physique quantique, une propriété interne des particules, au même titre que la masse ou la charge électrique. Comme d'autres observables quantiques, sa mesure donne des valeurs discrètes et est soumise au principe d'incertitude." },
  { titre: "Sport hippique", texte: "Le sport hippique ou hippisme est la discipline qui rassemble toutes les activités sportives équestres autour des courses de chevaux au galop, au trot ou à l'amble." },
  { titre: "Squash", texte: "Le squash est un sport de raquette qui se joue sur un terrain de jeu entièrement entouré de murs ou éventuellement de paroi(s) entièrement vitrée(s) pour permettre la présence de spectateurs lors des tournois internationaux." },
  { titre: "Statistique", texte: "La statistique ou les statistiques est la discipline qui étudie des phénomènes à travers la collecte de données, leur traitement, leur analyse, l'interprétation des résultats et leur présentation afin de rendre ces données compréhensibles par tous." },
  { titre: "Suédois", texte: "Le suédois (svenska ) est une langue appartenant à la branche scandinave des langues germaniques parlée par environ 10,4 millions de locuteurs, principalement en Suède et en Finlande, les deux pays dont il est langue officielle." },
  { titre: "Suite", texte: "En mathématiques, une suite est une liste d'éléments. Un élément peut y apparaître plusieurs fois et l'ordre des éléments est important. Dit autrement, une suite est une famille d'éléments — appelés ses « termes » — indexée par les entiers naturels." },
  { titre: "Sumatra", texte: "Sumatra est une île de l'Ouest de l'Indonésie située sur l'équateur. Son nom vient de Samudra, la capitale du sultanat de Pasai dans le nord de l'île (en langue malaise, samudera signifie « océan »)." },
  { titre: "Surf", texte: "Le surf, prononcé en français (abréviation française de l'anglais surf-riding) est une pratique physique individuelle de glisse sur les vagues déferlantes, au bord de l'océan." },
  { titre: "Sushi", texte: "Le sushi est un plat traditionnel japonais, composé d'un riz vinaigré appelé shari combiné avec un autre ingrédient appelé neta qui est habituellement du poisson cru ou des fruits de mer." },
  { titre: "Syllabe", texte: "La syllabe est une unité ininterrompue du langage oral. Son noyau, autour duquel elle se construit, est généralement une voyelle. Une syllabe peut également avoir des extrémités précédant ou suivant la voyelle, qui, lorsqu'elles existent, sont toujours constituées de consonnes." },
  { titre: "Sylviculture", texte: "La sylviculture est l'activité et l'ensemble des méthodes et pratiques par lesquelles un sylviculteur ou une sylvicultrice agit sur le développement, la gestion et la mise en valeur d'une forêt ou d'un boisement pour en obtenir un bénéfice économique et/ou certains services profitables à la société (dans une approche" },
  { titre: "Symbole", texte: "Un symbole peut être un objet, une image, un mot écrit, un son voire un être vivant, ou une marque particulière qui représente quelque chose d'autre par association, ressemblance ou convention." },
  { titre: "Symon Petlioura", texte: "Symon Petlioura est un homme d'État et journaliste ukrainien né à Poltava le 22 mai 1879 et mort assassiné à Paris (6e arrondissement) le 25 mai 1926. Il est l'un des personnages les plus importants du mouvement national, le commandant suprême de l'Armée et le troisième président de la République populaire ukrainienne." },
  { titre: "Tacite", texte: "Tacite, en latin Publius Cornelius Tacitus Ca(ecina Paetus), né en 58 et mort vers 120 ap. J.-C, mène comme sénateur romain une carrière dans la haute administration impériale." },
  { titre: "Tapir", texte: "Les tapirs (Tapirus) sont un genre de mammifères ongulés, dont une espèce est originaire d'Asie alors que quatre sont d'Amérique centrale et d'Amérique du Sud. C'est le seul genre actuel de la famille des Tapiridés (Tapiridae)." },
  { titre: "Tarsier", texte: "Les tarsiers (Tarsiidae) forment une famille de primates haplorhiniens vivant en Asie du Sud-Est, caractérisés par leurs yeux énormes et leurs pieds très développés." },
  { titre: "Tarzan", texte: "Tarzan (John Clayton III, Lord Greystoke) est un personnage de fiction représentant l’enfant sauvage archétypal élevé par des Grands Singes dans la jungle africaine." },
  { titre: "Taxonomie", texte: "La taxonomie ou taxinomie est une branche des sciences naturelles qui a pour objet l'étude de la diversité du monde vivant. Cette activité consiste à décrire et circonscrire en termes d'espèces les organismes vivants et à les organiser en catégories hiérarchisées appelées taxons." },
  { titre: "Télécommunications", texte: "Les télécommunications sont définies comme la transmission d’informations à distance en utilisant des technologies électronique, informatique, de transmission filaire, optique ou électromagnétique. Ce terme a un sens plus large que son acception équivalente officielle « communications électroniques »." },
  { titre: "Télégraphe", texte: "Le télégraphe est un système destiné à transmettre des messages, appelés télégrammes, d'un point à un autre sur de grandes distances, à l'aide de codes pour une transmission rapide et fiable." },
  { titre: "Température", texte: "La température est une grandeur physique mesurée à l’aide d’un thermomètre et étudiée en thermométrie. Dans la vie courante, elle est reliée aux sensations de froid et de chaud, provenant du transfert thermique entre le corps humain et son environnement." },
  { titre: "Temple de Borobudur", texte: "Le temple de Borobudur (en indonésien : Candi Borobudur ; en javanais : Candhi Barabudhur) est une importante construction bouddhiste, bâtie aux VIIIe et IXe siècles à l'époque de la dynastie Sailendra dans le centre de l'île de Java en Indonésie." },
  { titre: "Tension superficielle", texte: "La tension superficielle est un phénomène physico-chimique lié aux interactions moléculaires d'un fluide. Elle résulte de l'augmentation de l'énergie à l'interface entre deux fluides." },
  { titre: "Teotihuacan", texte: "Teotihuacan ou Teotihuacán est une ancienne métropole mésoaméricaine située dans l’actuel État de Mexico, au nord-est de Mexico ; édifiée et occupée principalement entre le Ier et le VIIe siècle, elle fut l’un des principaux foyers urbains, religieux et culturels de la Mésoamérique classique." },
  { titre: "Terre de Feu", texte: "La Terre de Feu (en espagnol : Tierra del Fuego ; en selk'nam : Karukinka ; en yagan : Onaisin) est le nom donné à l'archipel qui se trouve à l'extrême sud du continent sud-américain." },
  { titre: "Thèbes", texte: "Thèbes (aujourd'hui Louxor) est le nom grec (Thēbai) de la ville d'Égypte antique Ouaset (« Le sceptre » ou « La Puissante »), appartenant au quatrième nome de Haute-Égypte, sur la rive orientale du Nil, la vallée des Rois lui faisant face sur l'autre rive." },
  { titre: "Thémistocle", texte: "Thémistocle, né vers 524 av. J.-C. à Phréarres et mort vers 459 av. J.-C. à Magnésie du Méandre, est un homme d'État et stratège athénien. Il fait partie d'un nouveau type de politiciens d'origine non aristocratique qui prend de l'importance dans les premières années de la démocratie athénienne." },
  { titre: "Théodoric le Grand", texte: "Théodoric le Grand ou Théodoric l'Amales, né vers 455 et mort le 30 août 526 à Ravenne, est un roi des Ostrogoths et empereur (Princeps) d'Occident." },
  { titre: "Théodose Ier", texte: "Théodose Ier (en latin : Flavius Theodosius Augustus), aussi connu sous le nom de Théodose le Grand (en latin : Theodosius Magnus), est un empereur romain de l’Antiquité tardive. Né en 347, il règne de 379 jusqu'à sa mort le 17 janvier 395." },
  { titre: "Thucydide", texte: "Thucydide est un homme politique, stratège et historien athénien, né vers 460 av. J.-C. dans le dème d'Halimonte (de nos jours, Álimos) en Attique ; il est mort, peut-être assassiné, entre 400 av. J.-C. et 395 av. J.-C.." },
  { titre: "Tianjin", texte: "Tianjin, ou Tientsin en français, est une municipalité autonome du nord-est de la république populaire de Chine. Avec près de 14 millions d'habitants en 2020, il s'agit de la quatrième ville de Chine en nombre d'habitants, après Shanghai, Pékin et Chongqing." },
  { titre: "Tigre", texte: "Le Tigre est un fleuve de Mésopotamie long de 1 900 km. Ce fleuve prend sa source en Turquie comme l'autre grand fleuve de la région, l'Euphrate." },
  { titre: "Tim Berners-Lee", texte: "Tim Berners-Lee, né le 8 juin 1955 à Londres, est un physicien informaticien britannique. Il est le principal inventeur du World Wide Web (WWW, le Web), qu'il conçoit au tournant des années 1990 alors qu'il travaille à l'Organisation européenne pour la recherche nucléaire (CERN)." },
  { titre: "Titien", texte: "Tiziano Vecellio, Tiziano Vecelli ou Tiziano da Cador, plus communément appelé Titien ou le Titien en français, né vers 1488 à Pieve di Cadore (république de Venise) et mort le 27 août 1576 à Venise, est un peintre et graveur italien (vénitien) de l'école vénitienne, auteur d'une importante œuvre picturale." },
  { titre: "Tiwanaku", texte: "La civilisation de Tiwanaku (en aymara, ou Tiahuanaco, nom de la ville moderne en espagnol), est une civilisation pré-inca qui a dominé la moitié sud des Andes centrales entre les Ve et XIe siècles." },
  { titre: "Travail", texte: "Dans un sens très général, le travail est une activité humaine qui vise intentionnellement à transformer le monde physique. Au sens économique usuel, le travail ou activité professionnelle est l'activité humaine qui permet la production de biens et de services." },
  { titre: "Univers observable", texte: "L'Univers observable est, en cosmologie, la partie de notre Univers visible depuis la Terre. Il est donc une boule dont la limite est située à l'horizon cosmologique et dont la Terre constitue le centre." },
  { titre: "Unix", texte: "Unix, officiellement UNIX, est une famille de systèmes d'exploitation ouverts, multitâches et multi-utilisateurs. Unix est dérivé de l'Unix d'origine créé par AT&T, le développement de ce dernier ayant commencé dans les années 1970 au centre de recherche de Bell Labs mené par Kenneth Thompson." },
  { titre: "Vaslav Nijinski", texte: "Vaslav Nijinski, aussi retranscrit Vaclav Nijinsky ou Vatslav Nizhinski, né à Kiev probablement le 28 février 1889 (12 mars dans le calendrier grégorien) et mort le 8 avril 1950 à Londres, est un danseur et chorégraphe russe d'origine polonaise." },
  { titre: "Vertébrés", texte: "Les Vertébrés (Vertebrata) forment un sous-phylum très diversifié d'animaux chordés appartenant au clade des Olfactoriens et ayant pour particularité principale de posséder un squelette interne composé notamment d'un crâne et d'une colonne vertébrale." },
  { titre: "Vespa", texte: "Vespa est un genre d'insectes sociaux, de la famille des Vespidae, sous-famille des Vespinae, communément appelés frelons (ou talènes en Suisse romande)." },
  { titre: "Vessie", texte: "La vessie est l'organe du système urinaire dont la fonction est de recevoir l'urine terminale produite par les reins puis de la conserver avant son évacuation au cours de la miction. L'urine arrive dans la vessie par les uretères et est émise via l'urètre." },
  { titre: "Vientiane", texte: "Vientiane est la ville la plus peuplée et la capitale du Laos. Elle est située sur la rive gauche du Mékong, qui marque la frontière avec la Thaïlande, presque en face de la ville thaïlandaise de Nong Khai." },
  { titre: "Vietnamien", texte: "Le vietnamien (en vietnamien tiếng Việt), également appelé annamite autrefois en France, est la langue officielle du Viêt Nam. Il appartient à la branche viétiques des langues austroasiatiques. C'est la langue austroasiatique qui possède le plus de locuteurs (environ dix fois plus que la seconde, le khmer)." },
  { titre: "Village", texte: "Un village est une « agglomération rurale caractérisée par un habitat plus ou moins concentré, possédant des services de première nécessité et offrant une forme de vie communautaire »." },
  { titre: "Ville", texte: "Une ville est un lieu qui se caractérise par une forte densité de population et une forte densité de bâtiments. La population qui l'habite y organise l'espace en fonction de ses besoins et de ses activités propres, ainsi que de l'environnement physique." },
  { titre: "Vistule", texte: "La Vistule (en polonais : Wisła, en latin : Vistula, en allemand : Weichsel) est le principal fleuve polonais, qui arrose notamment Varsovie et Cracovie, et le 9e plus long fleuve d’Europe." },
  { titre: "Vogue", texte: "Vogue est un magazine américain, un des principaux magazines de mode féminins dans le monde, avec une diffusion supérieure à 1 million d'exemplaires mensuels. Le titre est édité par Condé Nast, basé à New York, et fait l'objet de nombreuses éditions internationales." },
  { titre: "Voyelle", texte: "En phonétique, on appelle voyelle un son du langage humain dont le mode de production est caractérisé par le libre passage de l'air dans les cavités situées au-dessus de la glotte, à savoir la cavité buccale et/ou les fosses nasales." },
  { titre: "Weekly Shōnen Jump", texte: "Weekly Shōnen Jump, fréquemment abrégé en Shōnen Jump, est un magazine de prépublication de mangas hebdomadaire de type shōnen créé par l’éditeur Shūeisha le 11 juillet 1968 et toujours en cours de publication." },
  { titre: "Western", texte: "Le western est un genre cinématographique dont l'action se déroule généralement en Amérique du Nord, plus spécifiquement aux États-Unis, lors de la conquête de l'Ouest dans les dernières décennies du XIXe siècle." },
  { titre: "Xénophon", texte: "Xénophon est un historien, philosophe et chef militaire de la Grèce antique né à Athènes vers 430 av. J.-C. et mort vers 355 av. J.-C. Outre l’Anabase et la Cyropédie, il a écrit une suite à l’Histoire de la guerre du Péloponnèse de Thucydide intitulée les Helléniques." },
  { titre: "Yaourt", texte: "Le yaourt, yogourt ou yoghourt (en turc : yoğurt), est un lait fermenté par le développement de bactéries lactiques thermophiles telles que Lactobacillus delbrueckii subsp. bulgaricus et Streptococcus thermophilus." },
  { titre: "Yasunari Kawabata", texte: "Yasunari Kawabata, né le 11 juin 1899 à Osaka et mort le 16 avril 1972 à Zushi, est un écrivain japonais, prix Nobel de littérature en 1968." },
];
